INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C1','sci',5,2,'u2',1,'날씨와 생활 모습 — 비 오는 날 우산·비옷, 더운 날 부채질, 추운 날 두꺼운 옷, 눈 오는 날 눈사람처럼 날씨에 따라 옷차림·놀이·하는 일이 달라짐 · 같은 날씨라도 사람마다 생활 모습이 다를 수 있고, 같은 생활 모습(산책)이 여러 날씨에서 나올 수도 있음 · 같은 날이라도 지역마다 날씨가 달라 생활 모습도 다름',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C2','sci',5,2,'u2',2,'기상 요소의 종류와 뜻 — 날씨를 표현하는 기상 요소에는 기온(공기의 따뜻하고 차가운 정도), 바람(방향과 세기), 습도(공기 중에 수증기가 포함된 정도), 구름의 양(맑음·흐림), 강수량(비나 눈 등이 내린 정도) 등이 있음 · 하늘의 색깔처럼 재어 견줄 수 없는 것은 기상 요소가 아님',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C3','sci',5,2,'u2',2,'기상 자료 속 관계 — 여러 날의 기상 자료를 보면 기상 요소는 날마다 변하고 서로 영향을 줌 · 비 오는 날은 맑은 날보다 구름이 많고 습도가 높은 편이며 하루 기온 차가 작은 편 · 하루 자료만 보고 규칙을 정하지 않고 여러 날을 견줌',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C4','sci',5,2,'u2',2,'기상 요소로 나타내기와 풍향 — 「맑음」 한마디보다 기온·습도·구름의 양처럼 기상 요소로 나타내면 날씨를 구체적이고 객관적으로 알고 지역·날짜끼리 견주기 쉬움 · 풍향은 바람이 불어오는 방향(북풍 = 북쪽에서 불어오는 바람) · 조선의 측우기는 빗물의 깊이를 재어 강수량을 견줌',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C5','sci',5,2,'u2',3,'날씨가 생활에 주는 영향 — 날씨는 옷차림·활동·쓰는 물건·음식·농사·교통까지 생활 곳곳에 영향을 줌 · 습한 날 제습기, 더운 날 그늘과 물 마시기, 바람 센 날 창문 닫기, 비 오는 날 빨래 들여놓기 · 기온과 습도가 높으면 음식이 쉽게 상함',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C6','sci',5,2,'u2',3,'날씨 정보와 대처 — 날씨 정보를 미리 알면 날씨에 맞는 옷을 챙기고, 피해를 예방하고, 야외 활동을 계획할 수 있음 · 날씨를 바꿀 수는 없지만 대비할 수는 있음 · 폭염에 야외 활동 줄이기, 서리 예보에 작물 덮기, 강한 바람 예보에 화분 들여놓기',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C7','sci',5,2,'u2',3,'날씨와 생활 만화 — 경험한 날씨를 떠올리고 영향을 조사해 한 컷~네 컷 만화로 표현함 · 인물의 옷차림·생활용품·야외 활동 모습에 날씨가 드러나야 함 · 한 가지 날씨나 날씨의 변화로 줄거리를 짬',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C8','sci',5,2,'u2',4,'이슬 — 차가운 캔 표면을 닦고 두면 물방울이 맺힘: 캔 주변 공기 중의 수증기가 차가운 표면에 닿아 응결한 것(캔 속 음료가 아님) · 이슬은 공기 중의 수증기가 차가워진 물체 표면에 응결해 맺힌 것(풀잎·거미줄·자동차 위) · 차가워진 안경이 따뜻한 방에서 흐려지는 것도 같은 과정',ARRAY['[6과06-02] 이슬·안개·구름이 생기는 과정을 실험으로 알아보고, 공통점과 차이점을 비교할 수 있다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C9','sci',5,2,'u2',4,'안개 — 미지근한 물을 조금 넣은 집기병에 향 연기를 잠깐 넣고 얼음 지퍼 백을 얹으면 안이 뿌옇게 흐려짐: 공기 중의 수증기가 차가워져 응결해 작은 물방울로 떠 있는 것(향 연기는 응결을 돕는 정도) · 안개는 지표면 가까이에 작은 물방울이 떠 있는 것 · 기온이 낮은 새벽에 잘 생기고 해가 떠 기온이 오르면 걷힘',ARRAY['[6과06-02] 이슬·안개·구름이 생기는 과정을 실험으로 알아보고, 공통점과 차이점을 비교할 수 있다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C10','sci',5,2,'u2',4,'이슬·안개·구름 견주기 — 셋 모두 공기 중의 수증기가 응결해 나타남(공통점) · 생기는 위치가 다름: 이슬은 물체 표면, 안개는 지표면 가까이, 구름은 지표면으로부터 높은 곳 · 안개와 구름은 물방울이 떠 있는 높이로 가름',ARRAY['[6과06-02] 이슬·안개·구름이 생기는 과정을 실험으로 알아보고, 공통점과 차이점을 비교할 수 있다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C11','sci',5,2,'u2',5,'기압·고기압·저기압 — 일정한 넓이에 작용하는 공기의 무게가 기압 · 주변보다 기압이 높은 곳이 고기압, 낮은 곳이 저기압 · 정해진 숫자가 아니라 주변과 견주어 정함 · 일기 예보 지도에 고기압·저기압이 표시됨',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C12','sci',5,2,'u2',5,'기상 위성 사진 읽기 — 위성 사진에서 구름이 많이 낀 곳은 저기압, 구름이 적은 곳은 고기압이 있는 경우가 많음 · 사진의 구름을 보고 비가 올 수 있는 곳과 맑은 곳을 찾음',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C13','sci',5,2,'u2',5,'고기압과 저기압의 날씨 — 고기압이 있는 곳은 대체로 구름이 적고 맑아 야외 활동·빨래에 좋음 · 저기압이 있는 곳은 대체로 구름이 많고 습도가 높으며 비나 눈이 올 수 있음 · 「대체로」이지 「항상」이 아님 · 두 날의 기상 요소(습도·구름의 양·강수량)를 견주어 어떤 기압의 영향인지 판단함',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C14','sci',5,2,'u2',6,'온도와 기압 — 상대적으로 차가운 공기는 무거워 기압이 높아지고(고기압), 따뜻한 공기는 가벼워 기압이 낮아짐(저기압) · 두 곳의 온도가 다르면 기압 차이가 생기고, 기압 차이로 공기가 이동하는 것이 바람',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C15','sci',5,2,'u2',6,'바람 발생 모형실험과 바람의 방향 — 모래와 따뜻한 물이 담긴 두 그릇 사이에 향 연기를 넣으면 연기가 온도가 낮은 모래 쪽(고기압)에서 따뜻한 물 쪽(저기압)으로 옆으로 움직임 · 바람은 고기압에서 저기압으로 붊 · 두 그릇의 온도 차가 클수록 방향이 뚜렷하고, 향불은 모래 상자에서 끔 · 온도 → 기압 → 바람 순서로 생각함',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C16','sci',5,2,'u2',6,'해풍과 육풍 — 맑은 날 낮에는 육지가 바다보다 빨리 데워져 육지 위가 저기압, 바다 위가 고기압이 되어 바다에서 육지로 해풍이 붊 · 밤에는 육지가 빨리 식어 육지 위가 고기압이 되어 육지에서 바다로 육풍이 붊 · 겨울에 창문을 열면 찬 바깥 공기가 따뜻한 방으로 들어오는 것도 같은 까닭',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C17','sci',5,2,'u2',7,'날씨 앱에 담을 정보 — 날씨 앱은 같은 기상 정보를 아이콘·그래프·배경 등 여러 방법으로 보여 줌 · 기온(현재·최고·최저), 비 올 확률·강수량, 구름의 양, 습도, 바람 같은 기상 요소가 가장 잘 드러나야 하고, 옷차림·우산 같은 생활 정보를 더함 · 꾸밈보다 정확하고 알기 쉬운 정보가 목적 · 개인 정보는 넣지 않고 그림·자료 출처를 밝힘',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C18','sci',5,2,'u2',7,'날씨 앱 만드는 차례와 나누기 — 계획하기(넣을 기상 요소·생활 정보·배치 정하기) → 해 보기(디자인 플랫폼으로 만들기) → 나누기(공유하고 댓글 달기) · 댓글은 잘한 점과 보완할 점을 구체적으로, 바르고 고운 말로 씀 · 쓰는 사람(어르신 등)에 맞게 글씨·말을 바꿈',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C19','sci',5,2,'u2',8,'기상 관측과 관측 장비 — 여러 가지 기상 요소를 재고 기상 현상을 살피는 것이 기상 관측 · 땅(종합 기상 관측탑·기상 레이더), 바다(해양 기상 관측선·해양 기상 부표), 하늘(풍선에 단 레윈존데·드론), 우주(기상 위성 — 구름의 모습) · 생활에서도 온도계로 기온, 빗물을 받아 강수량, 바람개비로 바람을 잼',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C20','sci',5,2,'u2',8,'예보가 만들어지기까지 — 관측 → 분석 → 판단: 땅·바다·하늘·우주의 관측 자료와 전 세계의 자료를 모아 슈퍼컴퓨터로 분석하고, 일기 예보관이 실제 상황을 종합해 판단해 예보·주의보를 발표함 · 기계만으로 저절로 정확해지지 않음 · 인공지능을 예보에 쓰려는 연구도 함',ARRAY['[6과06-01] 기온·바람·습도·구름의 양·강수량 같은 기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 설명할 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u2-C21','sci',5,2,'u2',8,'단원 정리 — 날씨 읽고 대비하기 — 기상 요소로 날씨를 나타내고 생활에 대비함 · 이슬·안개·구름은 수증기의 응결로, 생기는 위치로 가름 · 고기압은 대체로 맑고 저기압은 대체로 흐림 · 바람은 고기압에서 저기압으로 붊 · 여러 개념을 이어 실제 상황(체험 학습·소풍·바닷가)을 판단함',ARRAY['[6과06-03] 고기압과 저기압일 때의 날씨 특징을 알고, 기압 차이에 따라 바람이 부는 방향을 설명할 수 있다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X01','sci',5,'u2',ARRAY['SC5-2-u2-C1','SC5-2-u2-C5']::text[],'날씨는 우리 생활과 상관이 없다고 여긴다','옷차림·활동·물건이 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X02','sci',5,'u2',ARRAY['SC5-2-u2-C1']::text[],'생활 모습 하나나 그림 하나로 날씨를 단정한다(우산 = 꼭 비, 산책 = 꼭 맑음)','양산도 우산이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X03','sci',5,'u2',ARRAY['SC5-2-u2-C2']::text[],'기상 요소가 아닌 것(하늘의 색깔·날씨의 예쁨)을 기상 요소로 고른다','기온·바람·습도·구름의 양·강수량') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X04','sci',5,'u2',ARRAY['SC5-2-u2-C2']::text[],'기상 요소의 뜻을 바꾸어 안다(습도를 비의 양으로, 강수량을 공기 속 수증기로)','습도 = 수증기 정도 · 강수량 = 내린 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X05','sci',5,'u2',ARRAY['SC5-2-u2-C3']::text[],'비 오는 날의 기상 요소를 거꾸로 안다(습도가 낮다, 구름이 적다)','비 오는 날 — 구름 많고 습도 높아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X06','sci',5,'u2',ARRAY['SC5-2-u2-C3','SC5-2-u2-C13']::text[],'하루 자료 하나만 보고 규칙을 정하거나 기온 하나로만 날씨를 견준다','여러 날 · 여러 요소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X07','sci',5,'u2',ARRAY['SC5-2-u2-C4']::text[],'풍향을 바람이 불어 가는 방향으로 안다','불어오는 쪽이 이름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X08','sci',5,'u2',ARRAY['SC5-2-u2-C4']::text[],'날씨를 맑음·흐림 한마디로만 나타내거나 기상 요소로 나타내는 좋은 점을 놓친다','구체적 · 견주기 쉬워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X09','sci',5,'u2',ARRAY['SC5-2-u2-C5']::text[],'날씨에 맞지 않게 대처한다(비 오는 날 빨래를 밖에, 추운 날 얇은 옷)','날씨에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X10','sci',5,'u2',ARRAY['SC5-2-u2-C6']::text[],'날씨 정보를 미리 알면 날씨를 바꿀 수 있다고 여긴다','바꿀 수는 없고 대비해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X11','sci',5,'u2',ARRAY['SC5-2-u2-C6']::text[],'날씨 정보를 미리 알아 두는 쓸모(피해 예방·계획 세우기)를 놓친다','미리 알면 대비해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X12','sci',5,'u2',ARRAY['SC5-2-u2-C7']::text[],'날씨와 생활의 관계가 드러나지 않는 장면을 고르거나 그린다','옷차림·물건·활동에 날씨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X13','sci',5,'u2',ARRAY['SC5-2-u2-C8']::text[],'차가운 캔 표면의 물방울을 캔 속 음료가 새어 나온 것으로 여긴다','주변 공기의 수증기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X14','sci',5,'u2',ARRAY['SC5-2-u2-C8']::text[],'이슬을 하늘에서 내린 비나 땅에서 솟은 물로 여긴다','표면에서 응결해 맺혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X15','sci',5,'u2',ARRAY['SC5-2-u2-C9']::text[],'집기병 안이 뿌연 까닭을 향 연기 자체로 여긴다','수증기가 응결한 작은 물방울') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X16','sci',5,'u2',ARRAY['SC5-2-u2-C9','SC5-2-u2-C10']::text[],'안개와 구름을 같은 높이에 생기는 것으로 여긴다','안개 땅 가까이 · 구름 높은 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X17','sci',5,'u2',ARRAY['SC5-2-u2-C10']::text[],'이슬·안개·구름이 생기는 위치를 바꾸어 안다','표면 · 지표면 가까이 · 높은 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X18','sci',5,'u2',ARRAY['SC5-2-u2-C10']::text[],'이슬·안개·구름이 서로 다른 것에서 생긴다고 여겨 공통점(수증기의 응결)을 놓친다','셋 다 수증기가 응결') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X19','sci',5,'u2',ARRAY['SC5-2-u2-C8','SC5-2-u2-C9']::text[],'물방울이 생기는 조건을 거꾸로 안다(데워져야 맺힌다, 차가운 표면엔 안 맺힌다)','차가워지면 응결') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X20','sci',5,'u2',ARRAY['SC5-2-u2-C11']::text[],'고기압과 저기압의 뜻을 거꾸로 안다','주변보다 높으면 고기압') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X21','sci',5,'u2',ARRAY['SC5-2-u2-C11']::text[],'정해진 숫자보다 높으면 고기압이라고 여긴다','주변과 견주어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X22','sci',5,'u2',ARRAY['SC5-2-u2-C12']::text[],'위성 사진에서 구름이 많은 곳을 고기압으로 읽는다','구름 많음 → 저기압인 경우가 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X23','sci',5,'u2',ARRAY['SC5-2-u2-C13']::text[],'고기압이면 항상 맑고 저기압이면 항상 비가 온다고 단정한다','대체로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X24','sci',5,'u2',ARRAY['SC5-2-u2-C13']::text[],'고기압과 저기압의 날씨를 바꾸어 안다','고 — 대체로 맑음 · 저 — 대체로 흐림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X25','sci',5,'u2',ARRAY['SC5-2-u2-C14']::text[],'따뜻한 공기 쪽이 기압이 높다고 여긴다','차가우면 고기압') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X26','sci',5,'u2',ARRAY['SC5-2-u2-C15']::text[],'바람이 저기압에서 고기압으로, 따뜻한 곳에서 차가운 곳으로 분다고 여긴다','고기압 → 저기압') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X27','sci',5,'u2',ARRAY['SC5-2-u2-C15']::text[],'바람 발생 모형실험의 방법·안전을 놓친다(두 그릇 온도를 같게, 위로 오르는 연기만 봄, 향불 그대로)','온도 차 크게 · 옆으로 · 모래 상자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X28','sci',5,'u2',ARRAY['SC5-2-u2-C16']::text[],'해풍과 육풍의 낮과 밤을 바꾸어 안다','낮 해풍 · 밤 육풍') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X29','sci',5,'u2',ARRAY['SC5-2-u2-C14','SC5-2-u2-C15']::text[],'바람이 생기는 까닭을 기압 차이가 아닌 것(나무가 흔들려서, 공기가 가고 싶어서)으로 든다','기압 차이로 공기가 이동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X30','sci',5,'u2',ARRAY['SC5-2-u2-C17']::text[],'날씨 앱은 예쁘게 꾸미기만 하면 된다고 여겨 기상 요소를 작게 하거나 뺀다','날씨 정보가 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X31','sci',5,'u2',ARRAY['SC5-2-u2-C17']::text[],'날씨 앱 화면에 개인 정보를 넣거나 그림·자료 출처를 뺀다','개인 정보 없이 · 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X32','sci',5,'u2',ARRAY['SC5-2-u2-C18']::text[],'만드는 차례를 놓치거나 까닭 없는 말·흉보는 댓글을 쓴다','계획 → 해 보기 → 나누기 · 고운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X33','sci',5,'u2',ARRAY['SC5-2-u2-C19']::text[],'기상 관측 장비와 그 장비가 있는 곳·재는 것을 바꾸어 짝짓는다','땅·바다·하늘·우주') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X34','sci',5,'u2',ARRAY['SC5-2-u2-C20']::text[],'예보는 기계가 다 하거나 우리나라 자료만으로 충분하다고 여긴다','전 세계 자료 · 예보관의 판단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u2-X35','sci',5,'u2',ARRAY['SC5-2-u2-C21']::text[],'배운 개념을 실제 상황에 잇지 못해 엉뚱하게 판단한다(구름·기압·바람을 따로따로 봄)','기상 요소 → 기압 → 바람 → 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#1','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',1,'mc','auto','비가 오는 날 볼 수 있는 생활 모습은 어느 것인가요?',ARRAY['SC5-2-u2-X09']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"mc","stem":"비가 오는 날 볼 수 있는 생활 모습은 어느 것인가요?","options":[{"t":"우산을 쓰고 장화를 신는다","correct":true},{"t":"그늘에서 부채질을 한다","mis":"SC5-2-u2-X09"},{"t":"공원 잔디밭에 돗자리를 편다","mis":"SC5-2-u2-X09"},{"t":"눈사람을 만든다","mis":"SC5-2-u2-X09"}],"explanation":["비가 오면 젖어요.","우산과 장화를 챙겨요.","날씨에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#2','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',1,'mc','auto','추운 날 볼 수 있는 생활 모습은 어느 것인가요?',ARRAY['SC5-2-u2-X09']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"mc","stem":"추운 날 볼 수 있는 생활 모습은 어느 것인가요?","options":[{"t":"두꺼운 외투를 입고 장갑을 낀다","correct":true},{"t":"반소매 옷을 입는다","mis":"SC5-2-u2-X09"},{"t":"물놀이를 한다","mis":"SC5-2-u2-X09"},{"t":"부채를 챙긴다","mis":"SC5-2-u2-X09"}],"explanation":["추우면 몸이 떨려요.","두껍게 입어요.","장갑도 껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#3','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',1,'ox','auto','날씨에 따라 사람들의 옷차림과 하는 일이 달라져요.',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"ox","stem":"날씨에 따라 사람들의 옷차림과 하는 일이 달라져요.","answer":"O","reason_options":[{"t":"우리는 날씨의 영향을 받으며 생활하기 때문에","correct":true},{"t":"날씨는 생활과 상관이 없기 때문에","mis":"SC5-2-u2-X01"}],"mis":"SC5-2-u2-X01","explanation":["비 오면 우산을 써요.","더우면 부채질해요.","날씨가 생활을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#4','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',1,'sa','auto','같은 날씨 찾기 놀이에서 같은 날씨 카드 두 장을 찾으면 카드를 가져가고 그 날씨의 모습을 무엇으로 표현하나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"sa","stem":"같은 날씨 찾기 놀이에서 같은 날씨 카드 두 장을 찾으면 카드를 가져가고 그 날씨의 모습을 무엇으로 표현하나요? 한 글자로 쓰세요.","answer":["말"],"explanation":["짝을 찾았어요.","날씨를 표현해요.","말로 표현해요."],"mis":"SC5-2-u2-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#5','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',2,'mc','auto','날씨 카드 여섯 장에서 날씨 때문에 생긴 생활 모습을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X02']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"mc","stem":"날씨 카드 여섯 장에서 날씨 때문에 생긴 생활 모습을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉢ — 더워서 그늘에서 부채질을 했다","correct":true},{"t":"㉠ — 더워서 우산을 썼다","mis":"SC5-2-u2-X02"},{"t":"㉣ — 비가 와서 장갑을 꼈다","mis":"SC5-2-u2-X02"},{"t":"㉤ — 맑아서 눈사람을 만들었다","mis":"SC5-2-u2-X02"}],"explanation":["㉢은 더운 날이에요.","부채질로 더위를 식혀요.","날씨와 생활이 짝이에요."],"asset":{"type":"passage","lines":["㉠ 비 — 우산을 쓰고 장화를 신었다","㉡ 강한 바람 — 옷깃을 여미고 모자를 잡았다","㉢ 더운 날 — 그늘에서 부채질을 했다","㉣ 추운 날 — 두꺼운 외투와 장갑을 꼈다","㉤ 눈 — 친구들과 눈사람을 만들었다","㉥ 맑은 날 — 공원으로 소풍을 갔다"],"title":"날씨 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#6','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',2,'mc','auto','날씨와 상관없이 하는 일은 어느 것인가요?',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"mc","stem":"날씨와 상관없이 하는 일은 어느 것인가요?","options":[{"t":"이를 닦는다","correct":true},{"t":"눈 오는 날 눈싸움을 한다","mis":"SC5-2-u2-X01"},{"t":"비 오는 날 비옷을 입는다","mis":"SC5-2-u2-X01"},{"t":"더운 날 시원한 물을 마신다","mis":"SC5-2-u2-X01"}],"explanation":["양치는 날마다 해요.","날씨와 상관없어요.","나머지는 날씨 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#7','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',2,'mc','auto','맑은 날 하기 좋은 활동은 어느 것인가요?',ARRAY['SC5-2-u2-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"mc","stem":"맑은 날 하기 좋은 활동은 어느 것인가요?","options":[{"t":"공원으로 소풍 가기","correct":true},{"t":"우산 챙기기","mis":"SC5-2-u2-X09"},{"t":"창문 꼭 닫고 실내에만 있기","mis":"SC5-2-u2-X09"},{"t":"장화 신기","mis":"SC5-2-u2-X09"}],"explanation":["맑으면 하늘이 개요.","밖에서 놀기 좋아요.","소풍이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#8','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',2,'ox','auto','햇볕이 아주 강한 날에도 우산(양산)을 쓰는 사람이 있어요.',ARRAY['SC5-2-u2-X02']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"ox","stem":"햇볕이 아주 강한 날에도 우산(양산)을 쓰는 사람이 있어요.","answer":"O","reason_options":[{"t":"같은 물건이라도 여러 날씨에서 쓸 수 있기 때문에","correct":true},{"t":"우산은 비가 올 때만 쓰기 때문에","mis":"SC5-2-u2-X02"}],"mis":"SC5-2-u2-X02","explanation":["양산도 우산이에요.","햇볕을 가려요.","그림 하나로 단정 안 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#9','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',2,'mc','auto','안개가 짙게 낀 날 조심할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X01']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"mc","stem":"안개가 짙게 낀 날 조심할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞이 잘 보이지 않으니 천천히 조심해서 다닌다","correct":true},{"t":"빨리 뛰어서 이동한다","mis":"SC5-2-u2-X09"},{"t":"날씨와 상관없이 평소처럼 한다","mis":"SC5-2-u2-X01"},{"t":"부채를 챙긴다","mis":"SC5-2-u2-X09"}],"explanation":["안개 낀 날은 뿌옇게 보여요.","앞이 잘 안 보여요.","천천히 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_basic#10','sci',5,2,'u2','L01','g5_2_sci_u2_L01_basic','lesson_basic','SC5-2-u2-C1',3,'error','auto','날씨 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X02','SC5-2-u2-X01']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C1","difficulty":3,"kind":"error","stem":"날씨 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「산책하는 그림이니까 이날은 꼭 맑은 날이야.」","correct":true,"mis_target":"SC5-2-u2-X02"},{"t":"하린 — 「눈 오는 날에는 길이 미끄러워 조심해야 해.」","mis":"SC5-2-u2-X01"},{"t":"도윤 — 「바람이 센 날에는 모자가 날아가지 않게 잡아.」","mis":"SC5-2-u2-X01"}],"explanation":["산책은 여러 날씨에 해요.","구름 낀 날에도 해요.","준서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#1','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',2,'match','auto','날씨와 그 날씨에 볼 수 있는 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"match","stem":"날씨와 그 날씨에 볼 수 있는 생활 모습을 알맞게 이으세요.","pairs":[{"l":"비","r":"비옷을 입는다"},{"l":"눈","r":"눈사람을 만든다"},{"l":"더운 날","r":"부채질을 한다"},{"l":"강한 바람","r":"모자를 꼭 잡는다"}],"mis":"SC5-2-u2-X01","explanation":["비에는 비옷이에요.","눈에는 눈사람이에요.","날씨마다 생활이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#2','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',2,'mc','auto','날씨 카드 여섯 장을 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X02']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C1","difficulty":2,"kind":"mc","stem":"날씨 카드 여섯 장을 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"날씨에 따라 옷차림·놀이·하는 일이 달라진다","correct":true},{"t":"날씨는 생활에 아무 영향을 주지 않는다","mis":"SC5-2-u2-X01"},{"t":"사람들은 날씨와 상관없이 늘 같은 옷을 입는다","mis":"SC5-2-u2-X01"},{"t":"우산은 비 오는 날에만 쓴다","mis":"SC5-2-u2-X02"}],"explanation":["카드마다 모습이 달라요.","날씨가 달라서예요.","날씨와 생활은 이어져요."],"asset":{"type":"passage","lines":["㉠ 비 — 우산을 쓰고 장화를 신었다","㉡ 강한 바람 — 옷깃을 여미고 모자를 잡았다","㉢ 더운 날 — 그늘에서 부채질을 했다","㉣ 추운 날 — 두꺼운 외투와 장갑을 꼈다","㉤ 눈 — 친구들과 눈사람을 만들었다","㉥ 맑은 날 — 공원으로 소풍을 갔다"],"title":"날씨 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#3','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',3,'mc','auto','같은 날 서울은 비가 오고 부산은 맑았어요. 두 도시 사람들의 모습을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X09','SC5-2-u2-X02']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C1","difficulty":3,"kind":"mc","stem":"같은 날 서울은 비가 오고 부산은 맑았어요. 두 도시 사람들의 모습을 바르게 견준 것은 어느 것인가요?","options":[{"t":"서울 사람들은 우산을 쓰고, 부산 사람들은 밖에서 산책을 한다","correct":true},{"t":"두 도시 사람들의 모습은 똑같다","mis":"SC5-2-u2-X01"},{"t":"부산 사람들이 우산을 쓰고, 서울 사람들이 소풍을 간다","mis":"SC5-2-u2-X09"},{"t":"같은 날이니 날씨도 꼭 같다","mis":"SC5-2-u2-X02"}],"explanation":["같은 날도 지역마다 달라요.","서울은 비가 와요.","부산은 맑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#4','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',3,'mc','auto','눈 오는 날의 생활 모습을 즐거운 점과 불편한 점으로 바르게 나눈 것은 어느 것인가요?',ARRAY['SC5-2-u2-X12','SC5-2-u2-X09','SC5-2-u2-X01']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C1","difficulty":3,"kind":"mc","stem":"눈 오는 날의 생활 모습을 즐거운 점과 불편한 점으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"즐거운 점 — 눈싸움 · 불편한 점 — 길이 미끄럽다","correct":true},{"t":"즐거운 점 — 길이 미끄럽다 · 불편한 점 — 눈싸움","mis":"SC5-2-u2-X12"},{"t":"즐거운 점 — 부채질 · 불편한 점 — 땀이 난다","mis":"SC5-2-u2-X09"},{"t":"눈 오는 날은 생활이 달라지지 않는다","mis":"SC5-2-u2-X01"}],"explanation":["눈으로 놀 수 있어요.","길은 미끄러워요.","둘 다 날씨 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#5','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',3,'ox','auto','산책하는 사람 그림만 보고 그날 날씨가 맑았다고 단정할 수 있어요.',ARRAY['SC5-2-u2-X02']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C1","difficulty":3,"kind":"ox","stem":"산책하는 사람 그림만 보고 그날 날씨가 맑았다고 단정할 수 있어요.","answer":"X","reason_options":[{"t":"산책은 맑은 날에도 구름이 조금 낀 날에도 할 수 있기 때문에","correct":true},{"t":"산책은 맑은 날에만 하기 때문에","mis":"SC5-2-u2-X02"}],"mis":"SC5-2-u2-X02","explanation":["산책은 여러 날 해요.","그림 하나로는 몰라요.","단정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#6','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',3,'error','auto','놀이가 끝나고 알게 된 점을 한 문장씩 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X02']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C1","difficulty":3,"kind":"error","stem":"놀이가 끝나고 알게 된 점을 한 문장씩 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"은우 — 「날씨는 날마다 같아서 생활도 늘 같다.」","correct":true,"mis_target":"SC5-2-u2-X01"},{"t":"서아 — 「같은 날씨라도 사람마다 하는 일이 다를 수 있다.」","mis":"SC5-2-u2-X02"},{"t":"지호 — 「날씨에 따라 챙기는 물건이 달라진다.」","mis":"SC5-2-u2-X01"}],"explanation":["날씨는 날마다 바뀌어요.","생활도 따라 바뀌어요.","은우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#7','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',3,'mc','auto','아침에 일기 예보를 보고 「오후에 비가 온다」는 것을 알았어요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X01']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C1","difficulty":3,"kind":"mc","stem":"아침에 일기 예보를 보고 「오후에 비가 온다」는 것을 알았어요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"우산을 챙겨 나간다","correct":true},{"t":"빨래를 밖에 널어 둔다","mis":"SC5-2-u2-X09"},{"t":"반소매만 입고 나간다","mis":"SC5-2-u2-X09"},{"t":"예보와 상관없이 아무것도 챙기지 않는다","mis":"SC5-2-u2-X01"}],"explanation":["오후에 비가 와요.","미리 우산을 챙겨요.","날씨에 맞게 준비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#8','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',4,'mc','auto','날씨 카드 여섯 장을 「밖에서 하기 좋은 날」과 「조심하거나 대비할 날」로 나눌 때 바르게 나눈 것은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C1","difficulty":4,"kind":"mc","stem":"날씨 카드 여섯 장을 「밖에서 하기 좋은 날」과 「조심하거나 대비할 날」로 나눌 때 바르게 나눈 것은 어느 것인가요?","options":[{"t":"밖에서 하기 좋은 날 ㉥ · 대비할 날 ㉠ ㉡ ㉣","correct":true},{"t":"밖에서 하기 좋은 날 ㉠ · 대비할 날 ㉥","mis":"SC5-2-u2-X09"},{"t":"모든 카드가 밖에서 하기 좋은 날","mis":"SC5-2-u2-X01"},{"t":"밖에서 하기 좋은 날 ㉡ ㉣ · 대비할 날 ㉥","mis":"SC5-2-u2-X09"}],"explanation":["맑은 날은 소풍이 좋아요.","비·바람·추위는 대비해요.","날씨에 맞게 나눠요."],"asset":{"type":"passage","lines":["㉠ 비 — 우산을 쓰고 장화를 신었다","㉡ 강한 바람 — 옷깃을 여미고 모자를 잡았다","㉢ 더운 날 — 그늘에서 부채질을 했다","㉣ 추운 날 — 두꺼운 외투와 장갑을 꼈다","㉤ 눈 — 친구들과 눈사람을 만들었다","㉥ 맑은 날 — 공원으로 소풍을 갔다"],"title":"날씨 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#9','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',4,'mc','auto','소풍날 비가 와서 소풍이 취소되었어요. 미리 날씨를 알았다면 할 수 있었던 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X09','SC5-2-u2-X11']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C1","difficulty":4,"kind":"mc","stem":"소풍날 비가 와서 소풍이 취소되었어요. 미리 날씨를 알았다면 할 수 있었던 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실내에서 할 활동을 미리 준비한다","correct":true},{"t":"비가 오지 않게 날씨를 바꾼다","mis":"SC5-2-u2-X10"},{"t":"비가 와도 돗자리를 펴고 그대로 소풍을 한다","mis":"SC5-2-u2-X09"},{"t":"날씨는 미리 알 수 없으니 준비할 것이 없다","mis":"SC5-2-u2-X11"}],"explanation":["비 오는 날을 미리 알아요.","계획을 바꿔요.","실내 활동을 준비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L01_challenge#10','sci',5,2,'u2','L01','g5_2_sci_u2_L01_challenge','lesson_challenge','SC5-2-u2-C1',4,'essay','teacher','날씨 때문에 내 계획이나 생활 모습이 바뀌었던 경험을 하나 쓰고, 그때의 날씨와 바뀐 모습, 미리 알았다면 어떻게 했을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C1","difficulty":4,"kind":"essay","stem":"날씨 때문에 내 계획이나 생활 모습이 바뀌었던 경험을 하나 쓰고, 그때의 날씨와 바뀐 모습, 미리 알았다면 어떻게 했을지 쓰세요.","answer_guide":{"answer":"예: 여름에 친구들과 공원에서 놀기로 했는데 갑자기 비가 쏟아졌다. 우산이 없어 비를 맞고 집으로 돌아왔다. 미리 날씨를 알았다면 우산을 챙기거나 실내 놀이터에서 만나기로 했을 것이다.","scoring_points":["날씨를 구체적으로 썼는가","날씨 때문에 바뀐 생활 모습을 썼는가","미리 알았을 때의 대비를 썼는가"]},"explanation":["그날 날씨를 써요.","바뀐 모습을 써요.","대비도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#1','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C2',1,'mc','auto','공기 중에 수증기가 포함된 정도를 나타내는 기상 요소는 어느 것인가요?',ARRAY['SC5-2-u2-X04']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"mc","stem":"공기 중에 수증기가 포함된 정도를 나타내는 기상 요소는 어느 것인가요?","options":[{"t":"습도","correct":true},{"t":"기온","mis":"SC5-2-u2-X04"},{"t":"강수량","mis":"SC5-2-u2-X04"},{"t":"구름의 양","mis":"SC5-2-u2-X04"}],"explanation":["수증기는 공기 속에 있어요.","그 정도를 나타내요.","습도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#2','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C2',1,'mc','auto','공기의 따뜻하고 차가운 정도를 나타내는 기상 요소는 어느 것인가요?',ARRAY['SC5-2-u2-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"mc","stem":"공기의 따뜻하고 차가운 정도를 나타내는 기상 요소는 어느 것인가요?","options":[{"t":"기온","correct":true},{"t":"습도","mis":"SC5-2-u2-X04"},{"t":"바람","mis":"SC5-2-u2-X04"},{"t":"강수량","mis":"SC5-2-u2-X04"}],"explanation":["덥고 추운 정도예요.","온도계로 재요.","기온이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#3','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C2',1,'mc','auto','날씨를 표현하는 기상 요소가 아닌 것은 어느 것인가요?',ARRAY['SC5-2-u2-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"mc","stem":"날씨를 표현하는 기상 요소가 아닌 것은 어느 것인가요?","options":[{"t":"하늘의 색깔","correct":true},{"t":"기온","mis":"SC5-2-u2-X03"},{"t":"바람","mis":"SC5-2-u2-X03"},{"t":"강수량","mis":"SC5-2-u2-X03"}],"explanation":["기상 요소는 다섯 가지예요.","기온·바람·습도 등이에요.","하늘 색은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#4','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C2',1,'sa','auto','비나 눈 등이 내린 정도를 나타내는 기상 요소는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"sa","stem":"비나 눈 등이 내린 정도를 나타내는 기상 요소는 무엇인가요? 세 글자로 쓰세요.","answer":["강수량"],"explanation":["비와 눈이 내려요.","내린 정도를 재요.","강수량이에요."],"mis":"SC5-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#5','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C3',2,'mc','auto','나흘 동안의 날씨 기록에서 비 오는 날의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X05','SC5-2-u2-X06']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"mc","stem":"나흘 동안의 날씨 기록에서 비 오는 날의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"구름이 많고 습도가 높다","correct":true},{"t":"구름이 적고 습도가 낮다","mis":"SC5-2-u2-X05"},{"t":"낮과 밤 기온 차가 크다","mis":"SC5-2-u2-X05"},{"t":"습도와 상관없다","mis":"SC5-2-u2-X06"}],"explanation":["2일과 4일이 비예요.","구름이 많아요.","습도도 높아요."],"asset":{"type":"passage","lines":["1일 맑음 — 구름 적음 · 습도 낮은 편 · 낮과 밤 기온 차 큼","2일 비 — 구름 많음 · 습도 높음 · 낮과 밤 기온 차 작음","3일 맑음 — 구름 적음 · 습도 낮은 편 · 낮과 밤 기온 차 큼","4일 비 — 구름 많음 · 습도 높음 · 낮과 밤 기온 차 작음"],"title":"나흘 동안의 날씨 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#6','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C3',2,'ox','auto','나흘 동안의 날씨 기록을 보면 맑은 날은 비 오는 날보다 낮과 밤의 기온 차가 큰 편이에요.',ARRAY['SC5-2-u2-X06']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"ox","stem":"나흘 동안의 날씨 기록을 보면 맑은 날은 비 오는 날보다 낮과 밤의 기온 차가 큰 편이에요.","answer":"O","reason_options":[{"t":"1일·3일 맑은 날이 2일·4일 비 오는 날보다 기온 차가 크기 때문에","correct":true},{"t":"날씨와 상관없이 기온 차는 늘 같기 때문에","mis":"SC5-2-u2-X06"}],"mis":"SC5-2-u2-X06","explanation":["맑은 날은 기온 차가 커요.","비 오는 날은 작아요.","기록에서 찾아요."],"asset":{"type":"passage","lines":["1일 맑음 — 구름 적음 · 습도 낮은 편 · 낮과 밤 기온 차 큼","2일 비 — 구름 많음 · 습도 높음 · 낮과 밤 기온 차 작음","3일 맑음 — 구름 적음 · 습도 낮은 편 · 낮과 밤 기온 차 큼","4일 비 — 구름 많음 · 습도 높음 · 낮과 밤 기온 차 작음"],"title":"나흘 동안의 날씨 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#7','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C4',2,'mc','auto','운동장 바람 관찰 메모를 보고 이날의 풍향을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X07','SC5-2-u2-X06','SC5-2-u2-X03']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C4","difficulty":2,"kind":"mc","stem":"운동장 바람 관찰 메모를 보고 이날의 풍향을 바르게 말한 것은 어느 것인가요?","options":[{"t":"북풍 — 북쪽에서 불어오는 바람","correct":true},{"t":"남풍 — 깃발이 남쪽을 향했으니까","mis":"SC5-2-u2-X07"},{"t":"서풍 — 바람은 늘 서쪽에서 불어오니까","mis":"SC5-2-u2-X06"},{"t":"바람은 방향을 말할 수 없다","mis":"SC5-2-u2-X03"}],"explanation":["바람이 북쪽에서 와요.","깃발은 남쪽을 향해요.","불어오는 쪽이 북풍이에요."],"asset":{"type":"passage","lines":["운동장 깃발이 남쪽을 향해 펄럭였다.","바람자루도 남쪽을 가리켰다.","얼굴에 바람이 닿은 쪽은 북쪽이었다."],"title":"운동장 바람 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#8','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C4',2,'mc','auto','「오늘은 날씨가 좋다」보다 기상 요소로 나타낸 날씨가 더 좋은 까닭은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X08']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C4","difficulty":2,"kind":"mc","stem":"「오늘은 날씨가 좋다」보다 기상 요소로 나타낸 날씨가 더 좋은 까닭은 어느 것인가요?","options":[{"t":"날씨를 구체적으로 알고 다른 날·다른 지역과 견주기 쉽다","correct":true},{"t":"날씨를 마음대로 바꿀 수 있다","mis":"SC5-2-u2-X10"},{"t":"날씨가 더 예뻐 보인다","mis":"SC5-2-u2-X08"},{"t":"한마디로 짧게 말할 수 있다","mis":"SC5-2-u2-X08"}],"explanation":["숫자로 나타내요.","구체적이에요.","견주기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#9','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C2',2,'match','auto','기상 요소와 그것이 알려 주는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC5-2-u2-C2","difficulty":2,"kind":"match","stem":"기상 요소와 그것이 알려 주는 것을 알맞게 이으세요.","pairs":[{"l":"기온","r":"따뜻하고 차가운 정도"},{"l":"습도","r":"수증기가 포함된 정도"},{"l":"강수량","r":"비나 눈 등이 내린 정도"},{"l":"구름의 양","r":"맑음과 흐림"}],"mis":"SC5-2-u2-X04","explanation":["기온은 덥고 추움이에요.","습도는 수증기예요.","강수량은 내린 양이에요."],"asset":{"type":"passage","lines":["기온 — 공기의 따뜻하고 차가운 정도","바람 — 공기가 움직이는 방향과 세기","습도 — 공기 중에 수증기가 포함된 정도","구름의 양 — 하늘을 덮은 구름의 많고 적음","강수량 — 비나 눈 등이 내린 정도"],"title":"날씨를 나타내는 다섯 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_basic#10','sci',5,2,'u2','L02','g5_2_sci_u2_L02_basic','lesson_basic','SC5-2-u2-C2',3,'error','auto','날씨 앱을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X04','SC5-2-u2-X03']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C2","difficulty":3,"kind":"error","stem":"날씨 앱을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「습도는 오늘 비가 얼마나 왔는지를 알려 줘.」","correct":true,"mis_target":"SC5-2-u2-X04"},{"t":"지후 — 「구름의 양으로 맑은지 흐린지 알 수 있어.」","mis":"SC5-2-u2-X03"},{"t":"예린 — 「기온은 공기가 따뜻한지 차가운지 알려 줘.」","mis":"SC5-2-u2-X04"}],"explanation":["비가 온 양은 강수량이에요.","습도는 수증기 정도예요.","민서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#1','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C2',2,'mc','auto','날씨를 표현하는 기상 요소만 모은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C2","difficulty":2,"kind":"mc","stem":"날씨를 표현하는 기상 요소만 모은 것은 어느 것인가요?","options":[{"t":"기온, 바람, 습도, 구름의 양, 강수량","correct":true},{"t":"기온, 하늘의 색깔, 습도","mis":"SC5-2-u2-X03"},{"t":"바람, 날씨의 기분, 강수량","mis":"SC5-2-u2-X03"},{"t":"구름의 모양, 무지개, 기온","mis":"SC5-2-u2-X03"}],"explanation":["기상 요소는 잴 수 있어요.","다섯 가지가 있어요.","색깔·기분은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#2','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C3',2,'mc','auto','나흘 동안의 날씨 기록을 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X06','SC5-2-u2-X05']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"mc","stem":"나흘 동안의 날씨 기록을 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기상 요소는 날마다 변하고 서로 영향을 준다","correct":true},{"t":"기상 요소는 날마다 똑같다","mis":"SC5-2-u2-X06"},{"t":"비 오는 날은 습도가 낮다","mis":"SC5-2-u2-X05"},{"t":"구름의 양은 다른 요소와 상관없다","mis":"SC5-2-u2-X06"}],"explanation":["날마다 달라졌어요.","구름·습도가 함께 바뀌어요.","서로 영향을 줘요."],"asset":{"type":"passage","lines":["1일 맑음 — 구름 적음 · 습도 낮은 편 · 낮과 밤 기온 차 큼","2일 비 — 구름 많음 · 습도 높음 · 낮과 밤 기온 차 작음","3일 맑음 — 구름 적음 · 습도 낮은 편 · 낮과 밤 기온 차 큼","4일 비 — 구름 많음 · 습도 높음 · 낮과 밤 기온 차 작음"],"title":"나흘 동안의 날씨 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#3','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C3',3,'mc','auto','같은 날 두 도시의 날씨를 보고 비가 올 가능성이 더 큰 곳과 그 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X06','SC5-2-u2-X05','SC5-2-u2-X08']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C3","difficulty":3,"kind":"mc","stem":"같은 날 두 도시의 날씨를 보고 비가 올 가능성이 더 큰 곳과 그 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"나 도시 — 습도가 높고 구름이 많아 비 오는 날과 닮았다","correct":true},{"t":"가 도시 — 기온이 높으니까","mis":"SC5-2-u2-X06"},{"t":"가 도시 — 습도가 낮으니까","mis":"SC5-2-u2-X05"},{"t":"두 도시 모두 같다","mis":"SC5-2-u2-X08"}],"explanation":["비 오는 날을 떠올려요.","습도 높고 구름 많아요.","나 도시예요."],"asset":{"type":"passage","lines":["가 도시 — 기온 28 °C · 습도 40 % · 구름 조금","나 도시 — 기온 21 °C · 습도 90 % · 구름 많음"],"title":"같은 날 두 도시의 날씨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#4','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C4',3,'ox','auto','서풍은 서쪽으로 불어 가는 바람이에요.',ARRAY['SC5-2-u2-X07']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C4","difficulty":3,"kind":"ox","stem":"서풍은 서쪽으로 불어 가는 바람이에요.","answer":"X","reason_options":[{"t":"풍향은 바람이 불어오는 방향이라 서풍은 서쪽에서 불어오는 바람이기 때문에","correct":true},{"t":"바람의 이름은 불어 가는 쪽을 따르기 때문에","mis":"SC5-2-u2-X07"}],"mis":"SC5-2-u2-X07","explanation":["풍향은 불어오는 쪽이에요.","서풍은 서쪽에서 와요.","동쪽으로 불어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#5','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C4',3,'mc','auto','조선 시대 측우기가 쓸모 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X04','SC5-2-u2-X08']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C4","difficulty":3,"kind":"mc","stem":"조선 시대 측우기가 쓸모 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 그릇에 고인 빗물의 깊이를 재어 강수량을 정확히 견줄 수 있었다","correct":true},{"t":"비가 오지 않게 막을 수 있었다","mis":"SC5-2-u2-X10"},{"t":"바람의 방향을 알려 주었다","mis":"SC5-2-u2-X04"},{"t":"땅이 젖은 깊이를 재서 흙마다 값이 달랐다","mis":"SC5-2-u2-X08"}],"explanation":["측우기는 빗물을 받아요.","깊이를 재요.","강수량을 견줬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#6','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C3',3,'error','auto','기상 자료를 보고 친구들이 규칙을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X06','SC5-2-u2-X05']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C3","difficulty":3,"kind":"error","stem":"기상 자료를 보고 친구들이 규칙을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「어제 하루 습도가 높았는데 비가 안 왔으니 습도와 비는 상관없어.」","correct":true,"mis_target":"SC5-2-u2-X06"},{"t":"유나 — 「여러 날을 견주니 비 오는 날 구름이 많았어.」","mis":"SC5-2-u2-X05"},{"t":"시우 — 「비 오는 날은 맑은 날보다 습도가 높은 편이었어.」","mis":"SC5-2-u2-X05"}],"explanation":["하루로는 몰라요.","여러 날을 견줘요.","하준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#7','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C2',3,'mc','auto','눈이 내릴 때 강수량을 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X03','SC5-2-u2-X04']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C2","difficulty":3,"kind":"mc","stem":"눈이 내릴 때 강수량을 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"쌓인 눈의 깊이를 재거나 눈을 녹인 물의 양을 잰다","correct":true},{"t":"눈송이의 색깔을 본다","mis":"SC5-2-u2-X03"},{"t":"눈은 강수량에 들어가지 않는다","mis":"SC5-2-u2-X04"},{"t":"바람의 세기를 잰다","mis":"SC5-2-u2-X04"}],"explanation":["눈도 내린 것이에요.","깊이나 녹인 물로 재요.","강수량이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#8','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C4',4,'mc','auto','「오늘은 날씨가 좋다」를 기상 요소로 가장 잘 고쳐 쓴 것은 어느 것인가요?',ARRAY['SC5-2-u2-X08','SC5-2-u2-X03']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C4","difficulty":4,"kind":"mc","stem":"「오늘은 날씨가 좋다」를 기상 요소로 가장 잘 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"기온 22 °C, 습도 45 %, 구름 조금, 비는 오지 않는다","correct":true},{"t":"하늘이 예쁘고 기분이 좋다","mis":"SC5-2-u2-X08"},{"t":"날씨가 정말 좋다","mis":"SC5-2-u2-X08"},{"t":"하늘이 파란색이고 구름이 귀엽다","mis":"SC5-2-u2-X03"}],"explanation":["기상 요소를 넣어요.","값이나 상태를 붙여요.","구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#9','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C3',4,'mc','auto','두 도시 날씨에서 가 도시 사람들에게 알맞은 안내는 어느 것인가요?',ARRAY['SC5-2-u2-X05','SC5-2-u2-X06','SC5-2-u2-X09']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C3","difficulty":4,"kind":"mc","stem":"두 도시 날씨에서 가 도시 사람들에게 알맞은 안내는 어느 것인가요?","options":[{"t":"구름이 조금이고 습도가 낮으니 빨래를 널거나 야외 활동을 하기 좋다","correct":true},{"t":"습도가 높고 구름이 많으니 우산을 꼭 챙긴다","mis":"SC5-2-u2-X05"},{"t":"기온이 높으니 반드시 비가 온다","mis":"SC5-2-u2-X06"},{"t":"두꺼운 외투를 입는다","mis":"SC5-2-u2-X09"}],"explanation":["가 도시는 습도가 낮아요.","구름도 조금이에요.","야외 활동이 좋아요."],"asset":{"type":"passage","lines":["가 도시 — 기온 28 °C · 습도 40 % · 구름 조금","나 도시 — 기온 21 °C · 습도 90 % · 구름 많음"],"title":"같은 날 두 도시의 날씨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L02_challenge#10','sci',5,2,'u2','L02','g5_2_sci_u2_L02_challenge','lesson_challenge','SC5-2-u2-C4',4,'essay','teacher','오늘 우리 지역 날씨를 기상 요소 세 가지 이상으로 나타내는 문장을 쓰고, 「맑음」 한마디로 말할 때보다 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C4","difficulty":4,"kind":"essay","stem":"오늘 우리 지역 날씨를 기상 요소 세 가지 이상으로 나타내는 문장을 쓰고, 「맑음」 한마디로 말할 때보다 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 오늘 우리 지역은 기온 18 °C, 습도 50 %, 구름이 조금 있고 북쪽에서 바람이 불어오며 비는 오지 않았다. 기상 요소로 나타내면 날씨를 구체적으로 알 수 있고, 어제나 다른 지역 날씨와 견주기 쉽다.","scoring_points":["기상 요소를 세 가지 이상 썼는가","값이나 상태를 붙였는가","좋은 점(구체적·견주기)을 썼는가"]},"explanation":["기상 요소를 골라요.","값을 붙여요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#1','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C5',1,'mc','auto','습도가 높은 날 교실에서 쓰기 알맞은 물건은 어느 것인가요?',ARRAY['SC5-2-u2-X09']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C5","difficulty":1,"kind":"mc","stem":"습도가 높은 날 교실에서 쓰기 알맞은 물건은 어느 것인가요?","options":[{"t":"제습기","correct":true},{"t":"난로","mis":"SC5-2-u2-X09"},{"t":"부채만","mis":"SC5-2-u2-X09"},{"t":"얼음 주머니","mis":"SC5-2-u2-X09"}],"explanation":["습하면 끈적해요.","공기 속 물기를 줄여요.","제습기를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#2','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C5',1,'ox','auto','비가 오는 날에는 빨래를 밖에 널어 말려요.',ARRAY['SC5-2-u2-X09']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C5","difficulty":1,"kind":"ox","stem":"비가 오는 날에는 빨래를 밖에 널어 말려요.","answer":"X","reason_options":[{"t":"비가 오면 빨래가 젖으니 안에 들여놓기 때문에","correct":true},{"t":"비 오는 날 빨래가 더 잘 마르기 때문에","mis":"SC5-2-u2-X09"}],"mis":"SC5-2-u2-X09","explanation":["비가 오면 젖어요.","빨래를 들여놓아요.","날씨에 맞게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#3','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C6',1,'mc','auto','날씨 정보를 미리 알면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X11']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C6","difficulty":1,"kind":"mc","stem":"날씨 정보를 미리 알면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"날씨에 맞는 옷과 물건을 챙길 수 있다","correct":true},{"t":"날씨를 마음대로 바꿀 수 있다","mis":"SC5-2-u2-X10"},{"t":"날씨 정보는 쓸모가 없다","mis":"SC5-2-u2-X11"},{"t":"비가 오지 않게 할 수 있다","mis":"SC5-2-u2-X10"}],"explanation":["미리 알 수 있어요.","준비할 수 있어요.","옷과 물건을 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#4','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C5',1,'sa','auto','여름에 기온이 아주 높아 무척 더운 날씨를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u2-C5","difficulty":1,"kind":"sa","stem":"여름에 기온이 아주 높아 무척 더운 날씨를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["폭염"],"explanation":["아주 더운 날이에요.","야외 활동을 줄여요.","폭염이에요."],"mis":"SC5-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#5','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C5',2,'mc','auto','날씨가 우리 생활에 주는 영향을 옳게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X01']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C5","difficulty":2,"kind":"mc","stem":"날씨가 우리 생활에 주는 영향을 옳게 말한 것은 어느 것인가요?","options":[{"t":"바람이 센 날에는 창문을 닫고 화분을 들여놓는다","correct":true},{"t":"추운 날에는 얇은 옷을 입는다","mis":"SC5-2-u2-X09"},{"t":"비 오는 날에는 운동장에서 체육을 한다","mis":"SC5-2-u2-X09"},{"t":"날씨는 농사와 상관없다","mis":"SC5-2-u2-X01"}],"explanation":["바람이 세면 위험해요.","창문을 닫아요.","화분도 들여놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#6','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C6',2,'mc','auto','날씨에 대처한 모습 가운데 「서리 예보」를 듣고 한 일은 어느 것인가요?',ARRAY['SC5-2-u2-X09']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C6","difficulty":2,"kind":"mc","stem":"날씨에 대처한 모습 가운데 「서리 예보」를 듣고 한 일은 어느 것인가요?","options":[{"t":"다 — 밭에 비닐을 덮었다","correct":true},{"t":"가 — 제습기를 켰다","mis":"SC5-2-u2-X09"},{"t":"나 — 체육을 실내 수업으로 바꾸었다","mis":"SC5-2-u2-X09"},{"t":"라 — 화분을 들여놓았다","mis":"SC5-2-u2-X09"}],"explanation":["서리는 작물을 상하게 해요.","비닐로 덮어요.","다가 맞아요."],"asset":{"type":"passage","lines":["가 — 습한 날 교실에서 제습기를 켰다.","나 — 폭염 날 체육을 실내 수업으로 바꾸었다.","다 — 서리 예보를 듣고 밭에 비닐을 덮었다.","라 — 강한 바람 예보에 베란다 화분을 들여놓았다."],"title":"날씨에 대처한 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#7','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C5',2,'mc','auto','날씨와 관련 있는 직업 이야기로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C5","difficulty":2,"kind":"mc","stem":"날씨와 관련 있는 직업 이야기로 알맞은 것은 어느 것인가요?","options":[{"t":"어부는 높은 파도 예보가 있으면 배를 띄우지 않는다","correct":true},{"t":"농부는 날씨를 보지 않고 농사를 짓는다","mis":"SC5-2-u2-X01"},{"t":"어부는 태풍이 와도 늘 배를 띄운다","mis":"SC5-2-u2-X09"},{"t":"비행기는 날씨와 상관없이 뜬다","mis":"SC5-2-u2-X01"}],"explanation":["파도가 높으면 위험해요.","배를 띄우지 않아요.","직업에도 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#8','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C6',2,'ox','auto','날씨 예보를 미리 알면 날씨를 바꿀 수 있어요.',ARRAY['SC5-2-u2-X10']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C6","difficulty":2,"kind":"ox","stem":"날씨 예보를 미리 알면 날씨를 바꿀 수 있어요.","answer":"X","reason_options":[{"t":"날씨는 바꿀 수 없지만 미리 대비할 수는 있기 때문에","correct":true},{"t":"예보를 들으면 날씨가 예보대로 바뀌기 때문에","mis":"SC5-2-u2-X10"}],"mis":"SC5-2-u2-X10","explanation":["날씨는 못 바꿔요.","대비는 할 수 있어요.","그래서 예보를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#9','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C7',2,'mc','auto','날씨와 생활의 관계가 잘 드러나는 만화 장면은 어느 것인가요?',ARRAY['SC5-2-u2-X12']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C7","difficulty":2,"kind":"mc","stem":"날씨와 생활의 관계가 잘 드러나는 만화 장면은 어느 것인가요?","options":[{"t":"더운 날 친구들이 그늘에서 부채질을 한다","correct":true},{"t":"친구들이 교실에서 숙제를 한다","mis":"SC5-2-u2-X12"},{"t":"친구가 이를 닦는다","mis":"SC5-2-u2-X12"},{"t":"친구들이 책을 읽는다","mis":"SC5-2-u2-X12"}],"explanation":["더운 날씨가 보여요.","부채질도 보여요.","날씨와 생활이 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_basic#10','sci',5,2,'u2','L03','g5_2_sci_u2_L03_basic','lesson_basic','SC5-2-u2-C5',3,'error','auto','날씨에 대처한 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C5","difficulty":3,"kind":"error","stem":"날씨에 대처한 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「가는 날씨와 상관없이 늘 하는 일이야.」","correct":true,"mis_target":"SC5-2-u2-X01"},{"t":"서아 — 「나는 폭염에서 건강을 지키려는 거야.」","mis":"SC5-2-u2-X01"},{"t":"하준 — 「라는 강한 바람 피해를 막으려는 거야.」","mis":"SC5-2-u2-X01"}],"explanation":["가는 습한 날이에요.","제습기는 날씨 때문이에요.","도윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["가 — 습한 날 교실에서 제습기를 켰다.","나 — 폭염 날 체육을 실내 수업으로 바꾸었다.","다 — 서리 예보를 듣고 밭에 비닐을 덮었다.","라 — 강한 바람 예보에 베란다 화분을 들여놓았다."],"title":"날씨에 대처한 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#1','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C6',2,'match','auto','날씨 예보와 알맞은 대처를 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u2-C6","difficulty":2,"kind":"match","stem":"날씨 예보와 알맞은 대처를 이으세요.","pairs":[{"l":"폭염 예보","r":"야외 활동을 줄이고 물을 자주 마신다"},{"l":"서리 예보","r":"작물에 비닐을 덮는다"},{"l":"강한 바람 예보","r":"화분과 빨래를 들여놓는다"},{"l":"비 예보","r":"우산을 챙긴다"}],"mis":"SC5-2-u2-X09","explanation":["예보마다 대처가 달라요.","피해를 미리 막아요.","날씨에 맞게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#2','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C6',2,'mc','auto','날씨 정보를 미리 알면 좋은 점을 모두 바르게 고른 것은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X11']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C6","difficulty":2,"kind":"mc","stem":"날씨 정보를 미리 알면 좋은 점을 모두 바르게 고른 것은 어느 것인가요?","options":[{"t":"옷 챙기기 · 피해 예방 · 활동 계획 세우기","correct":true},{"t":"옷 챙기기 · 날씨 바꾸기","mis":"SC5-2-u2-X10"},{"t":"날씨 바꾸기 · 비 멈추기","mis":"SC5-2-u2-X10"},{"t":"좋은 점이 없다","mis":"SC5-2-u2-X11"}],"explanation":["미리 알면 준비해요.","피해를 막아요.","계획을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#3','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C5',3,'mc','auto','어느 날 기온과 습도가 모두 높았는데 아껴 둔 빵에 곰팡이가 생겼어요. 가장 알맞은 설명은 어느 것인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X09']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C5","difficulty":3,"kind":"mc","stem":"어느 날 기온과 습도가 모두 높았는데 아껴 둔 빵에 곰팡이가 생겼어요. 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"기온과 습도가 높으면 곰팡이가 잘 자라 음식이 쉽게 상한다","correct":true},{"t":"빵이 오래되어서일 뿐 날씨와 상관없다","mis":"SC5-2-u2-X01"},{"t":"습도가 높으면 음식이 더 오래간다","mis":"SC5-2-u2-X09"},{"t":"기온이 높으면 곰팡이가 자라지 못한다","mis":"SC5-2-u2-X09"}],"explanation":["덥고 습한 날이에요.","곰팡이가 잘 자라요.","날씨가 음식에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#4','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C6',3,'mc','auto','곰팡이가 잘 피는 덥고 습한 날에 할 대처로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X11']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C6","difficulty":3,"kind":"mc","stem":"곰팡이가 잘 피는 덥고 습한 날에 할 대처로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"음식을 냉장 보관하고 제습기로 습도를 낮춘다","correct":true},{"t":"음식을 햇볕 드는 창가에 둔다","mis":"SC5-2-u2-X09"},{"t":"창문을 모두 닫고 젖은 빨래를 방에 넌다","mis":"SC5-2-u2-X09"},{"t":"날씨는 바꿀 수 없으니 할 일이 없다","mis":"SC5-2-u2-X11"}],"explanation":["차갑게 보관해요.","습도를 낮춰요.","날씨에 맞게 대처해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#5','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C5',3,'ox','auto','비 오는 날 학교에서는 운동장 대신 강당이나 교실에서 체육을 하기도 해요.',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C5","difficulty":3,"kind":"ox","stem":"비 오는 날 학교에서는 운동장 대신 강당이나 교실에서 체육을 하기도 해요.","answer":"O","reason_options":[{"t":"날씨가 학교생활의 활동 장소에도 영향을 주기 때문에","correct":true},{"t":"체육 장소는 날씨와 상관없이 정해지기 때문에","mis":"SC5-2-u2-X01"}],"mis":"SC5-2-u2-X01","explanation":["비가 오면 운동장이 젖어요.","실내로 옮겨요.","날씨가 학교생활을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#6','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C6',3,'error','auto','「강한 바람 예보」를 듣고 할 일을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X11']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C6","difficulty":3,"kind":"error","stem":"「강한 바람 예보」를 듣고 할 일을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「바람이 세니까 베란다에 화분을 더 내놓자.」","correct":true,"mis_target":"SC5-2-u2-X09"},{"t":"지호 — 「학교에서는 창문을 닫고 야외 수업을 바꾸자.」","mis":"SC5-2-u2-X11"},{"t":"민서 — 「집에서는 빨래를 들여놓자.」","mis":"SC5-2-u2-X11"}],"explanation":["바람이 세면 떨어져요.","화분은 들여놓아요.","예린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#7','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C7',3,'blank','auto','날씨 만화 콘티의 3컷에 들어갈 장면으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X12','SC5-2-u2-X02']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C7","difficulty":3,"kind":"blank","stem":"날씨 만화 콘티의 3컷에 들어갈 장면으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비가 쏟아져 친구들이 공을 들고 교실로 뛰어 들어간다","correct":true},{"t":"친구들이 맑은 하늘 아래 계속 축구를 한다","mis":"SC5-2-u2-X12"},{"t":"친구가 교실에서 양치를 한다","mis":"SC5-2-u2-X12"},{"t":"눈이 내려 눈사람을 만든다","mis":"SC5-2-u2-X02"}],"explanation":["2컷에 구름이 왔어요.","4컷엔 비가 와요.","사이에 비가 와야 해요."],"asset":{"type":"passage","lines":["1컷 — 아침, 하늘이 맑아 운동장에서 축구를 한다.","2컷 — 갑자기 짙은 구름이 몰려온다.","3컷 — (    )","4컷 — 교실에서 창밖 비를 보며 다음 경기를 약속한다."],"title":"날씨 만화 콘티"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#8','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C5',4,'mc','auto','날씨와 관련된 직업 가운데 날씨 정보를 쓰는 모습을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X09','SC5-2-u2-X11']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C5","difficulty":4,"kind":"mc","stem":"날씨와 관련된 직업 가운데 날씨 정보를 쓰는 모습을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"농부 — 서리 예보에 비닐을 덮고, 어부 — 높은 파도 예보에 배를 띄우지 않는다","correct":true},{"t":"농부 — 날씨를 보지 않고, 어부 — 늘 배를 띄운다","mis":"SC5-2-u2-X01"},{"t":"농부 — 서리 예보에 물을 더 준다, 어부 — 태풍에 배를 띄운다","mis":"SC5-2-u2-X09"},{"t":"날씨 정보는 직업과 상관없다","mis":"SC5-2-u2-X11"}],"explanation":["서리는 작물을 상하게 해요.","높은 파도는 위험해요.","정보로 피해를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#9','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C7',4,'mc','auto','「바람이 센 날」을 날씨와 생활 만화로 그릴 때 날씨가 가장 잘 드러나는 계획은 어느 것인가요?',ARRAY['SC5-2-u2-X12']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C7","difficulty":4,"kind":"mc","stem":"「바람이 센 날」을 날씨와 생활 만화로 그릴 때 날씨가 가장 잘 드러나는 계획은 어느 것인가요?","options":[{"t":"모자가 날아가 잡으러 뛰고, 우산이 뒤집히는 모습을 그린다","correct":true},{"t":"친구들이 교실에서 조용히 그림을 그리는 모습만 그린다","mis":"SC5-2-u2-X12"},{"t":"맑은 하늘에서 해가 웃는 모습만 그린다","mis":"SC5-2-u2-X12"},{"t":"바람이 센 날이라고 글자로만 크게 쓴다","mis":"SC5-2-u2-X12"}],"explanation":["바람이 모습에 보여야 해요.","모자·우산이 날려요.","날씨가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L03_challenge#10','sci',5,2,'u2','L03','g5_2_sci_u2_L03_challenge','lesson_challenge','SC5-2-u2-C6',4,'essay','teacher','내일 「강한 바람과 비」 예보가 있어요. 학교와 집에서 할 대처를 하나씩 쓰고, 날씨 정보를 미리 아는 것이 왜 중요한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C6","difficulty":4,"kind":"essay","stem":"내일 「강한 바람과 비」 예보가 있어요. 학교와 집에서 할 대처를 하나씩 쓰고, 날씨 정보를 미리 아는 것이 왜 중요한지 쓰세요.","answer_guide":{"answer":"예: 학교에서는 창문을 닫고 운동장 체육을 강당 수업으로 바꾼다. 집에서는 베란다 화분과 빨래를 들여놓고 우산을 챙긴다. 날씨는 바꿀 수 없지만 미리 알면 피해를 예방하고 하루 계획을 세울 수 있기 때문에 중요하다.","scoring_points":["학교에서의 대처를 썼는가","집에서의 대처를 썼는가","미리 아는 것의 중요성(예방·계획)을 썼는가"]},"explanation":["학교 대처를 써요.","집 대처를 써요.","미리 알면 대비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#1','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C8',1,'mc','auto','차가운 음료수 캔 겉면을 마른 수건으로 닦고 잠시 두면 어떤 변화가 생기나요?',ARRAY['SC5-2-u2-X19','SC5-2-u2-X13']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C8","difficulty":1,"kind":"mc","stem":"차가운 음료수 캔 겉면을 마른 수건으로 닦고 잠시 두면 어떤 변화가 생기나요?","options":[{"t":"겉면에 작은 물방울이 맺힌다","correct":true},{"t":"아무 변화가 없다","mis":"SC5-2-u2-X19"},{"t":"캔이 뜨거워진다","mis":"SC5-2-u2-X19"},{"t":"캔 속 음료가 줄어든다","mis":"SC5-2-u2-X13"}],"explanation":["캔이 차가워요.","겉면에 물방울이 맺혀요.","이슬과 같은 모습이에요."],"asset":{"type":"passage","lines":["① 냉장고에서 꺼낸 음료수 캔을 책상에 놓았다.","② 캔 겉면을 마른 수건으로 닦았다.","③ 잠시 뒤 캔 겉면에 작은 물방울이 맺혔다.","④ 물방울은 점점 커져 아래로 흘렀다."],"title":"차가운 캔 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#2','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C9',1,'mc','auto','집기병 관찰에서 집기병 안이 뿌옇게 흐려진 모습은 어떤 자연 현상과 닮았나요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C9","difficulty":1,"kind":"mc","stem":"집기병 관찰에서 집기병 안이 뿌옇게 흐려진 모습은 어떤 자연 현상과 닮았나요?","options":[{"t":"안개","correct":true},{"t":"이슬","mis":"SC5-2-u2-X17"},{"t":"바람","mis":"SC5-2-u2-X18"},{"t":"무지개","mis":"SC5-2-u2-X18"}],"explanation":["작은 물방울이 떠 있어요.","뿌옇게 보여요.","안개와 닮았어요."],"asset":{"type":"passage","lines":["① 집기병에 미지근한 물을 조금 넣었다.","② 향 연기를 잠깐 넣고 뚜껑을 덮었다.","③ 뚜껑을 열고 얼음을 넣은 지퍼 백을 입구에 얹었다.","④ 집기병 안이 점점 뿌옇게 흐려졌다."],"title":"집기병 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#3','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C10',1,'sa','auto','공기 중의 수증기가 응결해 지표면으로부터 높은 곳에 떠 있는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u2-C10","difficulty":1,"kind":"sa","stem":"공기 중의 수증기가 응결해 지표면으로부터 높은 곳에 떠 있는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["구름"],"explanation":["높은 곳에 떠 있어요.","하늘에 보여요.","구름이에요."],"mis":"SC5-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#4','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C8',1,'ox','auto','차가운 캔 겉면의 물방울은 캔 속 음료가 새어 나온 거예요.',ARRAY['SC5-2-u2-X13']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C8","difficulty":1,"kind":"ox","stem":"차가운 캔 겉면의 물방울은 캔 속 음료가 새어 나온 거예요.","answer":"X","reason_options":[{"t":"캔 주변 공기 중의 수증기가 차가운 겉면에서 응결한 것이기 때문에","correct":true},{"t":"캔에 작은 구멍이 있어 음료가 새기 때문에","mis":"SC5-2-u2-X13"}],"mis":"SC5-2-u2-X13","explanation":["캔은 새지 않아요.","주변 공기에 수증기가 있어요.","겉면에서 응결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#5','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C10',2,'mc','auto','물방울 사진 카드에서 「이슬」에 해당하는 것만 모은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X16']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C10","difficulty":2,"kind":"mc","stem":"물방울 사진 카드에서 「이슬」에 해당하는 것만 모은 것은 어느 것인가요?","options":[{"t":"㉮ ㉱","correct":true},{"t":"㉯ ㉰","mis":"SC5-2-u2-X17"},{"t":"㉮ ㉯","mis":"SC5-2-u2-X16"},{"t":"㉰ ㉱","mis":"SC5-2-u2-X17"}],"explanation":["이슬은 표면에 맺혀요.","풀잎·자동차 위예요.","㉮와 ㉱예요."],"asset":{"type":"passage","lines":["㉮ 새벽 풀잎과 거미줄에 맺힌 물방울","㉯ 아침 호수 위에 낮게 깔린 뿌연 것","㉰ 산꼭대기 위 하늘에 떠 있는 하얀 것","㉱ 밤새 세워 둔 자동차 위의 물방울"],"title":"물방울 사진 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#6','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C10',2,'mc','auto','이슬·안개·구름의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C10","difficulty":2,"kind":"mc","stem":"이슬·안개·구름의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"모두 공기 중의 수증기가 응결해 나타난다","correct":true},{"t":"모두 하늘 높은 곳에 떠 있다","mis":"SC5-2-u2-X17"},{"t":"모두 땅속의 물이 솟아 나온 것이다","mis":"SC5-2-u2-X18"},{"t":"모두 물체 표면에 맺힌다","mis":"SC5-2-u2-X17"}],"explanation":["셋 다 물방울이에요.","수증기가 응결했어요.","자리는 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#7','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C9',2,'mc','auto','안개와 구름을 무엇으로 가를 수 있나요?',ARRAY['SC5-2-u2-X16','SC5-2-u2-X18']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C9","difficulty":2,"kind":"mc","stem":"안개와 구름을 무엇으로 가를 수 있나요?","options":[{"t":"물방울이 떠 있는 높이","correct":true},{"t":"물방울의 색깔","mis":"SC5-2-u2-X16"},{"t":"생긴 날짜","mis":"SC5-2-u2-X16"},{"t":"구분할 수 없다","mis":"SC5-2-u2-X18"}],"explanation":["둘 다 떠 있어요.","안개는 땅 가까이예요.","구름은 높은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#8','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C9',2,'ox','auto','안개는 기온이 낮은 새벽에 잘 생겨요.',ARRAY['SC5-2-u2-X19']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C9","difficulty":2,"kind":"ox","stem":"안개는 기온이 낮은 새벽에 잘 생겨요.","answer":"O","reason_options":[{"t":"기온이 낮으면 공기 중의 수증기가 잘 응결하기 때문에","correct":true},{"t":"새벽에는 공기가 데워져 수증기가 늘어나기 때문에","mis":"SC5-2-u2-X19"}],"mis":"SC5-2-u2-X19","explanation":["새벽은 차가워요.","수증기가 응결해요.","안개가 잘 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#9','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C10',2,'match','auto','이슬·안개·구름과 생기는 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC5-2-u2-C10","difficulty":2,"kind":"match","stem":"이슬·안개·구름과 생기는 자리를 알맞게 이으세요.","pairs":[{"l":"이슬","r":"차가워진 물체 표면"},{"l":"안개","r":"지표면 가까이"},{"l":"구름","r":"지표면으로부터 높은 곳"}],"mis":"SC5-2-u2-X17","explanation":["이슬은 표면이에요.","안개는 땅 가까이예요.","구름은 높은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_basic#10','sci',5,2,'u2','L04','g5_2_sci_u2_L04_basic','lesson_basic','SC5-2-u2-C9',3,'error','auto','집기병 관찰을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X15','SC5-2-u2-X19','SC5-2-u2-X18']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C9","difficulty":3,"kind":"error","stem":"집기병 관찰을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「뿌옇게 보인 건 넣어 둔 향 연기 때문이야.」","correct":true,"mis_target":"SC5-2-u2-X15"},{"t":"준서 — 「얼음 때문에 집기병 안 공기가 차가워졌어.」","mis":"SC5-2-u2-X19"},{"t":"서아 — 「수증기가 응결해 작은 물방울로 떠 있어.」","mis":"SC5-2-u2-X18"}],"explanation":["향 연기는 잠깐 넣었어요.","응결을 도와줄 뿐이에요.","하린의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 집기병에 미지근한 물을 조금 넣었다.","② 향 연기를 잠깐 넣고 뚜껑을 덮었다.","③ 뚜껑을 열고 얼음을 넣은 지퍼 백을 입구에 얹었다.","④ 집기병 안이 점점 뿌옇게 흐려졌다."],"title":"집기병 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#1','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C8',2,'mc','auto','캔의 물방울이 음료가 아니라는 근거를 찾으려면 어떻게 하면 좋을까요?',ARRAY['SC5-2-u2-X13','SC5-2-u2-X19']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C8","difficulty":2,"kind":"mc","stem":"캔의 물방울이 음료가 아니라는 근거를 찾으려면 어떻게 하면 좋을까요?","options":[{"t":"겉면 물방울과 캔 속 음료를 흰 종이에 묻혀 색깔을 견준다","correct":true},{"t":"캔을 더 세게 흔들어 본다","mis":"SC5-2-u2-X13"},{"t":"캔을 따뜻한 물에 넣어 둔다","mis":"SC5-2-u2-X19"},{"t":"물방울의 개수를 센다","mis":"SC5-2-u2-X13"}],"explanation":["색이 다르면 다른 물이에요.","물방울은 투명해요.","음료가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#2','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C10',2,'mc','auto','물방울 사진 카드를 이슬·안개·구름으로 바르게 나눈 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X16','SC5-2-u2-X18']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C10","difficulty":2,"kind":"mc","stem":"물방울 사진 카드를 이슬·안개·구름으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"이슬 ㉮ ㉱ · 안개 ㉯ · 구름 ㉰","correct":true},{"t":"이슬 ㉯ · 안개 ㉮ ㉱ · 구름 ㉰","mis":"SC5-2-u2-X17"},{"t":"이슬 ㉮ · 안개 ㉰ · 구름 ㉯ ㉱","mis":"SC5-2-u2-X16"},{"t":"모두 구름","mis":"SC5-2-u2-X18"}],"explanation":["표면이면 이슬이에요.","땅 가까이면 안개예요.","높은 곳이면 구름이에요."],"asset":{"type":"passage","lines":["㉮ 새벽 풀잎과 거미줄에 맺힌 물방울","㉯ 아침 호수 위에 낮게 깔린 뿌연 것","㉰ 산꼭대기 위 하늘에 떠 있는 하얀 것","㉱ 밤새 세워 둔 자동차 위의 물방울"],"title":"물방울 사진 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#3','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C8',3,'mc','auto','추운 날 바깥에 있다가 따뜻한 교실에 들어오자 안경이 뿌옇게 흐려졌어요. 이 일과 같은 과정으로 생기는 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X18','SC5-2-u2-X14']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C8","difficulty":3,"kind":"mc","stem":"추운 날 바깥에 있다가 따뜻한 교실에 들어오자 안경이 뿌옇게 흐려졌어요. 이 일과 같은 과정으로 생기는 것은 어느 것인가요?","options":[{"t":"이슬","correct":true},{"t":"구름","mis":"SC5-2-u2-X17"},{"t":"바람","mis":"SC5-2-u2-X18"},{"t":"비","mis":"SC5-2-u2-X14"}],"explanation":["안경이 차가워졌어요.","표면에 수증기가 응결해요.","이슬과 같은 과정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#4','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C8',3,'ox','auto','겨울에 따뜻한 집 안 유리창 안쪽에 물방울이 맺히는 것은 이슬이 생기는 과정과 같아요.',ARRAY['SC5-2-u2-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C8","difficulty":3,"kind":"ox","stem":"겨울에 따뜻한 집 안 유리창 안쪽에 물방울이 맺히는 것은 이슬이 생기는 과정과 같아요.","answer":"O","reason_options":[{"t":"집 안 공기 중의 수증기가 차가운 유리창 표면에서 응결하기 때문에","correct":true},{"t":"바깥의 비가 유리를 뚫고 들어오기 때문에","mis":"SC5-2-u2-X14"}],"mis":"SC5-2-u2-X14","explanation":["유리창이 차가워요.","수증기가 응결해요.","표면에 맺혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#5','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C9',3,'mc','auto','해가 떠서 기온이 오르면 새벽 안개는 어떻게 될까요?',ARRAY['SC5-2-u2-X19','SC5-2-u2-X16','SC5-2-u2-X17']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C9","difficulty":3,"kind":"mc","stem":"해가 떠서 기온이 오르면 새벽 안개는 어떻게 될까요?","options":[{"t":"점점 걷힌다","correct":true},{"t":"더 짙어진다","mis":"SC5-2-u2-X19"},{"t":"구름이 되어 땅으로 내려온다","mis":"SC5-2-u2-X16"},{"t":"이슬이 되어 하늘로 올라간다","mis":"SC5-2-u2-X17"}],"explanation":["기온이 올라요.","응결한 물방울이 줄어요.","안개가 걷혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#6','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C10',3,'error','auto','이슬·안개·구름을 견주며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X16','SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C10","difficulty":3,"kind":"error","stem":"이슬·안개·구름을 견주며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「산 위에 걸린 것도 안개도 모두 높은 하늘에 떠 있어서 같은 자리야.」","correct":true,"mis_target":"SC5-2-u2-X16"},{"t":"유나 — 「이슬은 풀잎 같은 물체 표면에 맺혀.」","mis":"SC5-2-u2-X17"},{"t":"은우 — 「셋 다 수증기가 응결해서 생겨.」","mis":"SC5-2-u2-X18"}],"explanation":["안개는 땅 가까이예요.","구름은 높은 곳이에요.","시우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#7','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C9',3,'mc','auto','안개 실험을 바르게 하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X19','SC5-2-u2-X15']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C9","difficulty":3,"kind":"mc","stem":"안개 실험을 바르게 하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"미지근한 물을 조금 넣고 얼음 지퍼 백을 입구에 얹는다","correct":true},{"t":"뜨거운 물을 가득 넣고 얼음은 넣지 않는다","mis":"SC5-2-u2-X19"},{"t":"향불을 켜 둔 채 그대로 둔다","mis":"SC5-2-u2-X15"},{"t":"얼음을 빼고 따뜻한 수건을 얹는다","mis":"SC5-2-u2-X19"}],"explanation":["안을 차갑게 해요.","얼음 지퍼 백을 얹어요.","향불은 모래 상자에서 꺼요."],"asset":{"type":"passage","lines":["① 집기병에 미지근한 물을 조금 넣었다.","② 향 연기를 잠깐 넣고 뚜껑을 덮었다.","③ 뚜껑을 열고 얼음을 넣은 지퍼 백을 입구에 얹었다.","④ 집기병 안이 점점 뿌옇게 흐려졌다."],"title":"집기병 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#8','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C10',4,'mc','auto','「구름은 높은 곳에 떠 있으니 수증기와 상관없다」는 말을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u2-X18','SC5-2-u2-X17','SC5-2-u2-X16']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C10","difficulty":4,"kind":"mc","stem":"「구름은 높은 곳에 떠 있으니 수증기와 상관없다」는 말을 바르게 고친 것은 어느 것인가요?","options":[{"t":"구름도 이슬·안개처럼 공기 중의 수증기가 응결해 생기고, 생기는 높이만 다르다","correct":true},{"t":"구름은 땅속 물이 솟아올라 생긴다","mis":"SC5-2-u2-X18"},{"t":"구름은 이슬이 하늘로 날아간 것이다","mis":"SC5-2-u2-X17"},{"t":"구름과 안개는 같은 높이에 생긴다","mis":"SC5-2-u2-X16"}],"explanation":["공통점은 응결이에요.","자리만 달라요.","구름도 수증기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#9','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C8',4,'mc','auto','욕실에서 따뜻한 물로 씻은 뒤 차가운 거울이 뿌옇게 흐려졌어요. 거울에 생긴 일과 같은 원리를 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X13','SC5-2-u2-X19','SC5-2-u2-X17']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C8","difficulty":4,"kind":"mc","stem":"욕실에서 따뜻한 물로 씻은 뒤 차가운 거울이 뿌옇게 흐려졌어요. 거울에 생긴 일과 같은 원리를 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"수증기가 차가운 거울 표면에서 응결해 작은 물방울로 맺혔다","correct":true},{"t":"거울 속에서 물이 스며 나왔다","mis":"SC5-2-u2-X13"},{"t":"따뜻해지면 표면에 물방울이 생긴다","mis":"SC5-2-u2-X19"},{"t":"거울에 구름이 생겼다","mis":"SC5-2-u2-X17"}],"explanation":["욕실엔 수증기가 많아요.","거울은 차가워요.","표면에 응결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L04_challenge#10','sci',5,2,'u2','L04','g5_2_sci_u2_L04_challenge','lesson_challenge','SC5-2-u2-C10',4,'essay','teacher','이슬·안개·구름의 공통점을 쓰고, 생기는 자리로 차이점을 쓴 뒤, 생활 속에서 이슬이나 안개와 비슷한 과정으로 생기는 일을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C10","difficulty":4,"kind":"essay","stem":"이슬·안개·구름의 공통점을 쓰고, 생기는 자리로 차이점을 쓴 뒤, 생활 속에서 이슬이나 안개와 비슷한 과정으로 생기는 일을 하나 쓰세요.","answer_guide":{"answer":"예: 공통점은 셋 모두 공기 중의 수증기가 응결해 나타난다는 것이다. 이슬은 차가워진 물체 표면에 맺히고, 안개는 지표면 가까이에 떠 있으며, 구름은 지표면으로부터 높은 곳에 떠 있다. 겨울에 따뜻한 방 유리창에 물방울이 맺히는 것은 이슬과 비슷한 과정이다.","scoring_points":["공통점(수증기의 응결)을 썼는가","셋의 자리 차이를 썼는가","생활 속 예를 알맞게 들었는가"]},"explanation":["공통점은 응결이에요.","자리가 달라요.","생활 속 예를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#1','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C11',1,'mc','auto','일정한 넓이에 작용하는 공기의 무게를 무엇이라고 하나요?',ARRAY['SC5-2-u2-X04']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"mc","stem":"일정한 넓이에 작용하는 공기의 무게를 무엇이라고 하나요?","options":[{"t":"기압","correct":true},{"t":"습도","mis":"SC5-2-u2-X04"},{"t":"기온","mis":"SC5-2-u2-X04"},{"t":"강수량","mis":"SC5-2-u2-X04"}],"explanation":["공기도 무게가 있어요.","누르는 힘이에요.","기압이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#2','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C11',1,'mc','auto','주변보다 상대적으로 기압이 높은 곳을 무엇이라고 하나요?',ARRAY['SC5-2-u2-X20','SC5-2-u2-X04','SC5-2-u2-X07']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"mc","stem":"주변보다 상대적으로 기압이 높은 곳을 무엇이라고 하나요?","options":[{"t":"고기압","correct":true},{"t":"저기압","mis":"SC5-2-u2-X20"},{"t":"습도","mis":"SC5-2-u2-X04"},{"t":"풍향","mis":"SC5-2-u2-X07"}],"explanation":["주변과 견줘요.","더 높으면 고기압이에요.","낮으면 저기압이에요."],"asset":{"type":"passage","lines":["⚖️ 기압 — 일정한 넓이에 작용하는 공기의 무게","⬆️ 주변보다 기압이 높은 곳","⬇️ 주변보다 기압이 낮은 곳"],"title":"기압 낱말 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#3','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C11',1,'sa','auto','주변보다 기압이 낮은 곳을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"sa","stem":"주변보다 기압이 낮은 곳을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["저기압"],"explanation":["주변보다 낮아요.","세 글자예요.","저기압이에요."],"mis":"SC5-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#4','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C13',1,'ox','auto','고기압이 있는 곳은 대체로 구름이 적고 맑아요.',ARRAY['SC5-2-u2-X24']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C13","difficulty":1,"kind":"ox","stem":"고기압이 있는 곳은 대체로 구름이 적고 맑아요.","answer":"O","reason_options":[{"t":"고기압이 있는 곳은 대체로 날씨가 맑기 때문에","correct":true},{"t":"고기압이 있으면 대체로 비가 오기 때문에","mis":"SC5-2-u2-X24"}],"mis":"SC5-2-u2-X24","explanation":["고기압은 대체로 맑아요.","구름이 적어요.","야외 활동이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#5','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C12',2,'mc','auto','두 날의 기상 위성 사진에서 저기압의 영향을 받은 날은 어느 날인가요?',ARRAY['SC5-2-u2-X22','SC5-2-u2-X06']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C12","difficulty":2,"kind":"mc","stem":"두 날의 기상 위성 사진에서 저기압의 영향을 받은 날은 어느 날인가요?","options":[{"t":"㉡ 날 — 구름이 우리나라를 두껍게 덮었다","correct":true},{"t":"㉠ 날 — 우리나라 위가 거의 비어 있다","mis":"SC5-2-u2-X22"},{"t":"두 날 모두 같다","mis":"SC5-2-u2-X06"},{"t":"위성 사진으로는 알 수 없다","mis":"SC5-2-u2-X22"}],"explanation":["구름이 많으면 저기압인 경우가 많아요.","㉡ 날이 흐려요.","㉡ 날이에요."],"asset":{"type":"passage","lines":["㉠ 날 — 우리나라 위가 거의 비어 있고 바다 위에만 구름 조금","㉡ 날 — 우리나라 위를 하얀 구름이 두껍게 덮음"],"title":"두 날의 기상 위성 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#6','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C13',2,'mc','auto','저기압이 있는 지역의 날씨로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C13","difficulty":2,"kind":"mc","stem":"저기압이 있는 지역의 날씨로 알맞은 것은 어느 것인가요?","options":[{"t":"대체로 구름이 많고 비나 눈이 올 수 있다","correct":true},{"t":"대체로 구름 없이 맑다","mis":"SC5-2-u2-X24"},{"t":"습도가 아주 낮아 빨래가 잘 마른다","mis":"SC5-2-u2-X24"},{"t":"언제나 반드시 눈이 온다","mis":"SC5-2-u2-X23"}],"explanation":["저기압은 대체로 흐려요.","비나 눈이 올 수 있어요.","우산을 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#7','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C13',2,'mc','auto','두 날의 서울 날씨에서 고기압의 영향을 받은 날로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X06']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C13","difficulty":2,"kind":"mc","stem":"두 날의 서울 날씨에서 고기압의 영향을 받은 날로 알맞은 것은 어느 것인가요?","options":[{"t":"가 날 — 습도가 낮고 강수량 0 mm, 구름의 양 0","correct":true},{"t":"나 날 — 습도가 높고 비가 왔다","mis":"SC5-2-u2-X24"},{"t":"나 날 — 기온이 낮으니까","mis":"SC5-2-u2-X06"},{"t":"두 날 모두 고기압이다","mis":"SC5-2-u2-X06"}],"explanation":["가 날은 구름이 없어요.","비도 안 왔어요.","고기압 날씨예요."],"asset":{"type":"passage","lines":["가 날 — 최고 기온 24.7 °C · 습도 60.6 % · 강수량 0 mm · 구름의 양 0","나 날 — 최고 기온 16.6 °C · 습도 90.8 % · 강수량 20.6 mm · 구름의 양 10"],"title":"두 날의 서울 날씨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#8','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C11',2,'ox','auto','기압이 정해진 숫자보다 높으면 언제나 고기압이에요.',ARRAY['SC5-2-u2-X21']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C11","difficulty":2,"kind":"ox","stem":"기압이 정해진 숫자보다 높으면 언제나 고기압이에요.","answer":"X","reason_options":[{"t":"고기압은 주변보다 상대적으로 기압이 높은 곳이기 때문에","correct":true},{"t":"고기압은 숫자 하나로 정해지기 때문에","mis":"SC5-2-u2-X21"}],"mis":"SC5-2-u2-X21","explanation":["숫자로 외우지 않아요.","주변과 견줘요.","높으면 고기압이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#9','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C13',2,'mc','auto','고기압이 자리 잡은 날 하기 좋은 일은 어느 것인가요?',ARRAY['SC5-2-u2-X24']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C13","difficulty":2,"kind":"mc","stem":"고기압이 자리 잡은 날 하기 좋은 일은 어느 것인가요?","options":[{"t":"빨래를 밖에 널고 야외 활동을 한다","correct":true},{"t":"우산과 비옷을 꼭 챙긴다","mis":"SC5-2-u2-X24"},{"t":"제습기를 하루 종일 켠다","mis":"SC5-2-u2-X24"},{"t":"밖에 나가지 않는다","mis":"SC5-2-u2-X24"}],"explanation":["고기압은 대체로 맑아요.","빨래가 잘 말라요.","야외 활동이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_basic#10','sci',5,2,'u2','L05','g5_2_sci_u2_L05_basic','lesson_basic','SC5-2-u2-C13',3,'error','auto','고기압과 저기압의 날씨를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X23','SC5-2-u2-X24']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"error","stem":"고기압과 저기압의 날씨를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「고기압이 있으면 항상 구름 한 점 없이 맑아.」","correct":true,"mis_target":"SC5-2-u2-X23"},{"t":"민서 — 「저기압이 다가오면 비 소식이 있을 수 있어.」","mis":"SC5-2-u2-X24"},{"t":"예린 — 「고기압이 있는 곳은 대체로 맑아.」","mis":"SC5-2-u2-X24"}],"explanation":["고기압은 대체로 맑아요.","항상은 아니에요.","지호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#1','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',2,'match','auto','기압과 날씨 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u2-C13","difficulty":2,"kind":"match","stem":"기압과 날씨 특징을 알맞게 이으세요.","pairs":[{"l":"고기압","r":"대체로 맑고 구름이 적다"},{"l":"저기압","r":"대체로 흐리고 비나 눈이 올 수 있다"}],"mis":"SC5-2-u2-X24","explanation":["고기압은 맑아요.","저기압은 흐려요.","대체로 그래요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#2','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C12',2,'mc','auto','기상 위성 사진으로 비가 올 수 있는 곳을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X22']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C12","difficulty":2,"kind":"mc","stem":"기상 위성 사진으로 비가 올 수 있는 곳을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"하얀 구름이 두껍게 덮인 곳을 찾는다","correct":true},{"t":"구름이 하나도 없는 곳을 찾는다","mis":"SC5-2-u2-X22"},{"t":"바다가 파랗게 보이는 곳을 찾는다","mis":"SC5-2-u2-X22"},{"t":"위성 사진으로는 찾을 수 없다","mis":"SC5-2-u2-X22"}],"explanation":["구름이 많은 곳을 봐요.","저기압인 경우가 많아요.","비가 올 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#3','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',3,'mc','auto','어느 날 서울의 습도가 90 %, 구름의 양이 10, 강수량이 20 mm였어요. 이날은 무엇의 영향을 받았을까요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X06']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"mc","stem":"어느 날 서울의 습도가 90 %, 구름의 양이 10, 강수량이 20 mm였어요. 이날은 무엇의 영향을 받았을까요?","options":[{"t":"저기압 — 습도가 높고 구름이 많으며 비가 왔기 때문","correct":true},{"t":"고기압 — 습도가 높았기 때문","mis":"SC5-2-u2-X24"},{"t":"고기압 — 강수량이 있었기 때문","mis":"SC5-2-u2-X24"},{"t":"기온만 알아야 정할 수 있다","mis":"SC5-2-u2-X06"}],"explanation":["습도가 높아요.","구름도 많고 비가 왔어요.","저기압이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#4','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',3,'ox','auto','저기압이 있어도 비가 오지 않는 날이 있어요.',ARRAY['SC5-2-u2-X23']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"ox","stem":"저기압이 있어도 비가 오지 않는 날이 있어요.","answer":"O","reason_options":[{"t":"저기압은 「대체로」 흐리고 비가 올 수 있는 것이지 항상 비가 오는 것은 아니기 때문에","correct":true},{"t":"저기압이 있으면 반드시 비가 오기 때문에","mis":"SC5-2-u2-X23"}],"mis":"SC5-2-u2-X23","explanation":["대체로 흐려요.","항상은 아니에요.","비가 안 올 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#5','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',3,'mc','auto','두 날의 서울 날씨를 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-2-u2-X05','SC5-2-u2-X06']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"mc","stem":"두 날의 서울 날씨를 바르게 견준 것은 어느 것인가요?","options":[{"t":"나 날은 가 날보다 습도가 높고 구름이 많으며 비가 왔다","correct":true},{"t":"가 날이 나 날보다 습도가 높았다","mis":"SC5-2-u2-X05"},{"t":"두 날은 기온만 달랐다","mis":"SC5-2-u2-X06"},{"t":"가 날에 비가 더 많이 왔다","mis":"SC5-2-u2-X05"}],"explanation":["나 날 습도가 90 %가 넘어요.","구름의 양 10이에요.","비도 왔어요."],"asset":{"type":"passage","lines":["가 날 — 최고 기온 24.7 °C · 습도 60.6 % · 강수량 0 mm · 구름의 양 0","나 날 — 최고 기온 16.6 °C · 습도 90.8 % · 강수량 20.6 mm · 구름의 양 10"],"title":"두 날의 서울 날씨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#6','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C12',3,'error','auto','위성 사진을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X22','SC5-2-u2-X24']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C12","difficulty":3,"kind":"error","stem":"위성 사진을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「㉡ 날은 구름이 많으니 고기압이 자리 잡은 날이야.」","correct":true,"mis_target":"SC5-2-u2-X22"},{"t":"하준 — 「㉠ 날은 우리나라가 대체로 맑았을 거야.」","mis":"SC5-2-u2-X24"},{"t":"서아 — 「㉡ 날에는 우산이 필요했을 수 있어.」","mis":"SC5-2-u2-X24"}],"explanation":["구름이 많으면 저기압이에요.","㉡ 날은 저기압이에요.","은우의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 날 — 우리나라 위가 거의 비어 있고 바다 위에만 구름 조금","㉡ 날 — 우리나라 위를 하얀 구름이 두껍게 덮음"],"title":"두 날의 기상 위성 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#7','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C11',3,'mc','auto','「고기압」을 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X21','SC5-2-u2-X20']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C11","difficulty":3,"kind":"mc","stem":"「고기압」을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"주변보다 상대적으로 기압이 높은 곳","correct":true},{"t":"기압이 정해진 숫자보다 높은 곳","mis":"SC5-2-u2-X21"},{"t":"주변보다 기압이 낮은 곳","mis":"SC5-2-u2-X20"},{"t":"공기가 없는 곳","mis":"SC5-2-u2-X20"}],"explanation":["주변과 견줘요.","높으면 고기압이에요.","상대적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#8','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',4,'mc','auto','같은 날 동쪽 지방은 구름이 적고 서쪽 지방은 구름이 두껍게 덮였어요. 두 지방의 생활 모습을 바르게 예상한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X01','SC5-2-u2-X23']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C13","difficulty":4,"kind":"mc","stem":"같은 날 동쪽 지방은 구름이 적고 서쪽 지방은 구름이 두껍게 덮였어요. 두 지방의 생활 모습을 바르게 예상한 것은 어느 것인가요?","options":[{"t":"서쪽은 우산을 챙기고 실내 활동을, 동쪽은 빨래나 야외 활동을 한다","correct":true},{"t":"동쪽이 우산을 챙기고, 서쪽이 야외 활동을 한다","mis":"SC5-2-u2-X24"},{"t":"두 지방 모두 똑같이 생활한다","mis":"SC5-2-u2-X01"},{"t":"서쪽은 저기압이라 항상 눈이 온다","mis":"SC5-2-u2-X23"}],"explanation":["서쪽은 저기압이에요.","동쪽은 고기압이에요.","생활도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#9','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',4,'mc','auto','내일 우리 지역에 저기압이 온다는 예보가 있어요. 소풍 계획을 가장 알맞게 바꾼 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X11','SC5-2-u2-X23']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C13","difficulty":4,"kind":"mc","stem":"내일 우리 지역에 저기압이 온다는 예보가 있어요. 소풍 계획을 가장 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"구름이 많고 비가 올 수 있으니 실내 장소로 바꾸거나 우산을 챙긴다","correct":true},{"t":"저기압이니 햇볕이 강해 선크림만 챙긴다","mis":"SC5-2-u2-X24"},{"t":"예보는 바뀔 수 없으니 그대로 잔디밭에서 한다","mis":"SC5-2-u2-X11"},{"t":"저기압이 오면 항상 눈이 오니 썰매를 챙긴다","mis":"SC5-2-u2-X23"}],"explanation":["저기압은 대체로 흐려요.","비가 올 수 있어요.","계획을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L05_challenge#10','sci',5,2,'u2','L05','g5_2_sci_u2_L05_challenge','lesson_challenge','SC5-2-u2-C13',4,'essay','teacher','두 날의 서울 날씨를 보고 각 날이 고기압과 저기압 가운데 무엇의 영향을 받았는지 쓰고, 그렇게 생각한 까닭을 기상 요소 두 가지 이상으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C13","difficulty":4,"kind":"essay","stem":"두 날의 서울 날씨를 보고 각 날이 고기압과 저기압 가운데 무엇의 영향을 받았는지 쓰고, 그렇게 생각한 까닭을 기상 요소 두 가지 이상으로 쓰세요.","answer_guide":{"answer":"예: 가 날은 고기압, 나 날은 저기압의 영향을 받았다. 가 날은 구름의 양이 0이고 강수량이 0 mm로 맑았고 습도도 낮았다. 나 날은 구름의 양이 10이고 습도가 90 %가 넘었으며 비가 20 mm 넘게 왔기 때문이다.","scoring_points":["두 날의 기압을 바르게 썼는가","기상 요소 두 가지 이상을 근거로 들었는가","고기압·저기압 날씨 특징과 이었는가"]},"explanation":["가 날은 맑아요.","나 날은 비가 와요.","기상 요소로 까닭을 써요."],"asset":{"type":"passage","lines":["가 날 — 최고 기온 24.7 °C · 습도 60.6 % · 강수량 0 mm · 구름의 양 0","나 날 — 최고 기온 16.6 °C · 습도 90.8 % · 강수량 20.6 mm · 구름의 양 10"],"title":"두 날의 서울 날씨"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#1','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C15',1,'mc','auto','바람은 어느 쪽에서 어느 쪽으로 부나요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X29']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C15","difficulty":1,"kind":"mc","stem":"바람은 어느 쪽에서 어느 쪽으로 부나요?","options":[{"t":"고기압에서 저기압으로","correct":true},{"t":"저기압에서 고기압으로","mis":"SC5-2-u2-X26"},{"t":"늘 북쪽에서 남쪽으로","mis":"SC5-2-u2-X29"},{"t":"위에서 아래로만","mis":"SC5-2-u2-X29"}],"explanation":["공기는 이동해요.","기압이 높은 곳에서 출발해요.","고기압 → 저기압이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#2','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C15',1,'mc','auto','바람 발생 모형실험에서 향 연기는 어느 쪽으로 움직였나요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X27','SC5-2-u2-X29']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C15","difficulty":1,"kind":"mc","stem":"바람 발생 모형실험에서 향 연기는 어느 쪽으로 움직였나요?","options":[{"t":"모래 쪽에서 따뜻한 물 쪽으로","correct":true},{"t":"따뜻한 물 쪽에서 모래 쪽으로","mis":"SC5-2-u2-X26"},{"t":"위로만 곧게 올라갔다","mis":"SC5-2-u2-X27"},{"t":"움직이지 않았다","mis":"SC5-2-u2-X29"}],"explanation":["모래 쪽이 차가워요.","모래 쪽이 고기압이에요.","물 쪽으로 움직여요."],"asset":{"type":"passage","lines":["① 큰 그릇 두 개에 액정 온도계를 붙였다.","② 한 그릇엔 모래, 다른 그릇엔 따뜻한 물을 담았다.","③ 두 그릇을 뒷면이 검은 투명 상자에 넣었다.","④ 향 연기를 모은 작은 그릇을 두 그릇 사이에 넣었다.","⑤ 뚜껑을 열고 향 연기가 움직이는 쪽을 보았다."],"title":"바람 발생 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#3','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C14',1,'ox','auto','지면 위의 공기가 차가워지면 기압이 높아져요.',ARRAY['SC5-2-u2-X25']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C14","difficulty":1,"kind":"ox","stem":"지면 위의 공기가 차가워지면 기압이 높아져요.","answer":"O","reason_options":[{"t":"차가운 공기는 무거워 기압이 높아지기 때문에","correct":true},{"t":"차가운 공기는 가벼워 기압이 낮아지기 때문에","mis":"SC5-2-u2-X25"}],"mis":"SC5-2-u2-X25","explanation":["차가우면 무거워요.","기압이 높아져요.","고기압이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#4','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C16',1,'sa','auto','맑은 날 낮에 바닷가에서 바다에서 육지로 부는 바람을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u2-C16","difficulty":1,"kind":"sa","stem":"맑은 날 낮에 바닷가에서 바다에서 육지로 부는 바람을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["해풍"],"explanation":["바다에서 불어와요.","낮에 불어요.","해풍이에요."],"mis":"SC5-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#5','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C14',2,'mc','auto','두 곳 사이에 바람이 부는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X29','SC5-2-u2-X25']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"mc","stem":"두 곳 사이에 바람이 부는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 곳의 기압 차이로 공기가 이동하기 때문","correct":true},{"t":"나무가 흔들려 바람을 만들기 때문","mis":"SC5-2-u2-X29"},{"t":"공기가 따뜻한 곳에서 출발하고 싶어서","mis":"SC5-2-u2-X29"},{"t":"따뜻한 곳의 기압이 더 높기 때문","mis":"SC5-2-u2-X25"}],"explanation":["온도가 달라요.","기압 차이가 생겨요.","공기가 이동해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#6','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C14',2,'mc','auto','바람 발생 모형실험에서 모래와 따뜻한 물 위의 기압을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X25','SC5-2-u2-X29']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"mc","stem":"바람 발생 모형실험에서 모래와 따뜻한 물 위의 기압을 바르게 말한 것은 어느 것인가요?","options":[{"t":"모래 위 — 고기압 · 따뜻한 물 위 — 저기압","correct":true},{"t":"모래 위 — 저기압 · 따뜻한 물 위 — 고기압","mis":"SC5-2-u2-X25"},{"t":"둘 다 고기압","mis":"SC5-2-u2-X29"},{"t":"둘 다 저기압","mis":"SC5-2-u2-X29"}],"explanation":["모래 쪽이 차가워요.","차가우면 고기압이에요.","물 쪽은 저기압이에요."],"asset":{"type":"passage","lines":["① 큰 그릇 두 개에 액정 온도계를 붙였다.","② 한 그릇엔 모래, 다른 그릇엔 따뜻한 물을 담았다.","③ 두 그릇을 뒷면이 검은 투명 상자에 넣었다.","④ 향 연기를 모은 작은 그릇을 두 그릇 사이에 넣었다.","⑤ 뚜껑을 열고 향 연기가 움직이는 쪽을 보았다."],"title":"바람 발생 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#7','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C15',2,'ox','auto','바람 발생 모형실험은 두 그릇의 온도 차이가 클수록 연기의 방향이 뚜렷해요.',ARRAY['SC5-2-u2-X27']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C15","difficulty":2,"kind":"ox","stem":"바람 발생 모형실험은 두 그릇의 온도 차이가 클수록 연기의 방향이 뚜렷해요.","answer":"O","reason_options":[{"t":"온도 차이가 크면 기압 차이도 커지기 때문에","correct":true},{"t":"두 그릇의 온도가 같아야 연기가 잘 움직이기 때문에","mis":"SC5-2-u2-X27"}],"mis":"SC5-2-u2-X27","explanation":["온도 차가 커요.","기압 차도 커져요.","방향이 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#8','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C16',2,'mc','auto','맑은 날 밤 바닷가에서 부는 바람으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X28','SC5-2-u2-X29']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C16","difficulty":2,"kind":"mc","stem":"맑은 날 밤 바닷가에서 부는 바람으로 알맞은 것은 어느 것인가요?","options":[{"t":"육지에서 바다로 부는 육풍","correct":true},{"t":"바다에서 육지로 부는 해풍","mis":"SC5-2-u2-X28"},{"t":"바람이 불지 않는다","mis":"SC5-2-u2-X29"},{"t":"위에서 아래로만 부는 바람","mis":"SC5-2-u2-X29"}],"explanation":["밤엔 육지가 빨리 식어요.","육지 위가 고기압이에요.","육풍이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#9','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C15',2,'mc','auto','바람 발생 모형실험에서 지켜야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X27']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C15","difficulty":2,"kind":"mc","stem":"바람 발생 모형실험에서 지켜야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓴 향은 모래 상자에서 완전히 끈다","correct":true},{"t":"향불은 켜 둔 채 정리한다","mis":"SC5-2-u2-X27"},{"t":"두 그릇의 온도를 똑같이 맞춘다","mis":"SC5-2-u2-X27"},{"t":"연기가 위로 오르는 모습만 본다","mis":"SC5-2-u2-X27"}],"explanation":["향은 불이에요.","모래 상자에서 꺼요.","안전하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_basic#10','sci',5,2,'u2','L06','g5_2_sci_u2_L06_basic','lesson_basic','SC5-2-u2-C15',3,'error','auto','실험 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X25']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C15","difficulty":3,"kind":"error","stem":"실험 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「따뜻한 물 쪽이 따뜻하니까 거기서 바람이 출발했어.」","correct":true,"mis_target":"SC5-2-u2-X26"},{"t":"서아 — 「모래 쪽이 차가워서 고기압이 됐어.」","mis":"SC5-2-u2-X25"},{"t":"지호 — 「연기는 고기압에서 저기압으로 움직였어.」","mis":"SC5-2-u2-X26"}],"explanation":["차가운 쪽이 고기압이에요.","바람은 고기압에서 출발해요.","도윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#1','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C16',2,'match','auto','바닷가의 때와 바람을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u2-C16","difficulty":2,"kind":"match","stem":"바닷가의 때와 바람을 알맞게 이으세요.","pairs":[{"l":"맑은 날 낮","r":"바다에서 육지로 부는 해풍"},{"l":"맑은 날 밤","r":"육지에서 바다로 부는 육풍"}],"mis":"SC5-2-u2-X28","explanation":["낮엔 육지가 따뜻해요.","밤엔 육지가 차가워요.","바람 방향이 바뀌어요."],"asset":{"type":"passage","lines":["맑은 날 낮 — 바닷가 바람자루가 육지 쪽으로 펄럭였다.","맑은 날 밤 — 해변 모닥불 연기가 바다 쪽으로 흘러갔다."],"title":"바닷가 하루 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#2','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C14',2,'mc','auto','온도와 기압과 바람을 바른 순서로 이은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X29']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"mc","stem":"온도와 기압과 바람을 바른 순서로 이은 것은 어느 것인가요?","options":[{"t":"온도 차이 → 기압 차이 → 바람","correct":true},{"t":"바람 → 온도 차이 → 기압 차이","mis":"SC5-2-u2-X29"},{"t":"기압 차이 → 바람 → 온도 차이","mis":"SC5-2-u2-X29"},{"t":"온도와 바람은 상관없다","mis":"SC5-2-u2-X29"}],"explanation":["먼저 온도가 달라요.","기압 차이가 생겨요.","바람이 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#3','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C15',3,'mc','auto','모래와 따뜻한 물 대신 얼음물과 따뜻한 물을 쓰면 향 연기는 어떻게 움직일까요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X29','SC5-2-u2-X27']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C15","difficulty":3,"kind":"mc","stem":"모래와 따뜻한 물 대신 얼음물과 따뜻한 물을 쓰면 향 연기는 어떻게 움직일까요?","options":[{"t":"얼음물 쪽에서 따뜻한 물 쪽으로","correct":true},{"t":"따뜻한 물 쪽에서 얼음물 쪽으로","mis":"SC5-2-u2-X26"},{"t":"움직이지 않는다","mis":"SC5-2-u2-X29"},{"t":"위로만 올라간다","mis":"SC5-2-u2-X27"}],"explanation":["얼음물이 차가워요.","얼음물 쪽이 고기압이에요.","물 쪽으로 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#4','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C16',3,'mc','auto','바닷가 하루 관찰에서 낮에 바람자루가 육지 쪽으로 펄럭인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X25','SC5-2-u2-X28','SC5-2-u2-X29']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C16","difficulty":3,"kind":"mc","stem":"바닷가 하루 관찰에서 낮에 바람자루가 육지 쪽으로 펄럭인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"낮에 육지가 더 따뜻해 저기압이 되어 바다에서 육지로 바람이 불었다","correct":true},{"t":"낮에 바다가 더 따뜻해 바다 위가 저기압이 되었다","mis":"SC5-2-u2-X25"},{"t":"바람은 늘 바다에서 육지로만 분다","mis":"SC5-2-u2-X28"},{"t":"바람자루가 육지를 좋아해서","mis":"SC5-2-u2-X29"}],"explanation":["낮엔 육지가 빨리 데워져요.","육지 위가 저기압이에요.","해풍이 불어요."],"asset":{"type":"passage","lines":["맑은 날 낮 — 바닷가 바람자루가 육지 쪽으로 펄럭였다.","맑은 날 밤 — 해변 모닥불 연기가 바다 쪽으로 흘러갔다."],"title":"바닷가 하루 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#5','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C16',3,'ox','auto','바닷가 하루 관찰에서 밤에 모닥불 연기가 바다 쪽으로 흘러간 것은 육풍 때문이에요.',ARRAY['SC5-2-u2-X28']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C16","difficulty":3,"kind":"ox","stem":"바닷가 하루 관찰에서 밤에 모닥불 연기가 바다 쪽으로 흘러간 것은 육풍 때문이에요.","answer":"O","reason_options":[{"t":"밤에는 육지가 빨리 식어 고기압이 되어 육지에서 바다로 바람이 불기 때문에","correct":true},{"t":"밤에는 바다가 빨리 식어 고기압이 되기 때문에","mis":"SC5-2-u2-X28"}],"mis":"SC5-2-u2-X28","explanation":["밤엔 육지가 차가워요.","육지 위가 고기압이에요.","육풍이 불어요."],"asset":{"type":"passage","lines":["맑은 날 낮 — 바닷가 바람자루가 육지 쪽으로 펄럭였다.","맑은 날 밤 — 해변 모닥불 연기가 바다 쪽으로 흘러갔다."],"title":"바닷가 하루 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#6','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C14',3,'error','auto','「따뜻한 공기와 차가운 공기」를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X25','SC5-2-u2-X26','SC5-2-u2-X29']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C14","difficulty":3,"kind":"error","stem":"「따뜻한 공기와 차가운 공기」를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「따뜻한 공기는 무거워서 기압이 높아.」","correct":true,"mis_target":"SC5-2-u2-X25"},{"t":"준서 — 「차가운 공기 쪽이 고기압이 돼.」","mis":"SC5-2-u2-X26"},{"t":"유나 — 「두 곳의 기압이 다르면 공기가 움직여.」","mis":"SC5-2-u2-X29"}],"explanation":["따뜻하면 가벼워요.","기압이 낮아져요.","하린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#7','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C14',3,'mc','auto','한겨울 따뜻한 방의 창문을 조금 열었더니 찬 바깥 공기가 방 안으로 들어왔어요. 가장 알맞은 설명은 어느 것인가요?',ARRAY['SC5-2-u2-X25','SC5-2-u2-X29']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C14","difficulty":3,"kind":"mc","stem":"한겨울 따뜻한 방의 창문을 조금 열었더니 찬 바깥 공기가 방 안으로 들어왔어요. 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"차가운 바깥이 고기압, 따뜻한 방이 저기압이라 공기가 바깥에서 방으로 이동했다","correct":true},{"t":"따뜻한 방이 고기압이라 공기가 방에서 나갔다","mis":"SC5-2-u2-X25"},{"t":"찬 공기가 방에 들어오고 싶어서","mis":"SC5-2-u2-X29"},{"t":"바람은 기압과 상관없다","mis":"SC5-2-u2-X29"}],"explanation":["바깥은 차가워요.","바깥이 고기압이에요.","방 안으로 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#8','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C15',4,'mc','auto','바람 발생 모형실험에서 향 연기를 넣는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X29','SC5-2-u2-X27','SC5-2-u2-X21']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C15","difficulty":4,"kind":"mc","stem":"바람 발생 모형실험에서 향 연기를 넣는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"눈에 보이지 않는 공기의 움직임을 연기로 볼 수 있게 하려고","correct":true},{"t":"향 연기가 바람을 만들어 내려고","mis":"SC5-2-u2-X29"},{"t":"그릇을 따뜻하게 하려고","mis":"SC5-2-u2-X27"},{"t":"기압을 숫자로 재려고","mis":"SC5-2-u2-X21"}],"explanation":["공기는 보이지 않아요.","연기가 함께 움직여요.","움직임이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#9','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C16',4,'mc','auto','맑은 날 바닷가 체험 학습에서 오후엔 연을 날리고 저녁엔 해변 모닥불을 피워요. 연과 연기가 갈 쪽을 바르게 예상한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X28','SC5-2-u2-X29']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C16","difficulty":4,"kind":"mc","stem":"맑은 날 바닷가 체험 학습에서 오후엔 연을 날리고 저녁엔 해변 모닥불을 피워요. 연과 연기가 갈 쪽을 바르게 예상한 것은 어느 것인가요?","options":[{"t":"연은 육지 쪽으로, 저녁 연기는 바다 쪽으로","correct":true},{"t":"연은 바다 쪽으로, 연기는 육지 쪽으로","mis":"SC5-2-u2-X28"},{"t":"둘 다 육지 쪽으로","mis":"SC5-2-u2-X28"},{"t":"둘 다 하늘로만 올라간다","mis":"SC5-2-u2-X29"}],"explanation":["낮엔 해풍이에요.","밤엔 육풍이에요.","방향이 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L06_challenge#10','sci',5,2,'u2','L06','g5_2_sci_u2_L06_challenge','lesson_challenge','SC5-2-u2-C15',4,'essay','teacher','바람 발생 모형실험의 결과를 쓰고, 온도 → 기압 → 바람의 순서로 향 연기가 그렇게 움직인 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C15","difficulty":4,"kind":"essay","stem":"바람 발생 모형실험의 결과를 쓰고, 온도 → 기압 → 바람의 순서로 향 연기가 그렇게 움직인 까닭을 설명하세요.","answer_guide":{"answer":"예: 향 연기는 모래 쪽에서 따뜻한 물 쪽으로 움직였다. 모래 쪽은 온도가 낮아 공기가 무겁고 기압이 높아져 고기압이 되고, 따뜻한 물 쪽은 공기가 가벼워 기압이 낮아져 저기압이 된다. 두 곳에 기압 차이가 생겨 공기가 고기압에서 저기압으로 이동하므로 연기도 그 방향으로 움직였다.","scoring_points":["연기의 방향을 바르게 썼는가","온도와 기압을 바르게 이었는가","고기압에서 저기압으로 이동한다는 것을 썼는가"]},"explanation":["결과를 먼저 써요.","온도 → 기압으로 이어요.","바람 방향을 써요."],"asset":{"type":"passage","lines":["① 큰 그릇 두 개에 액정 온도계를 붙였다.","② 한 그릇엔 모래, 다른 그릇엔 따뜻한 물을 담았다.","③ 두 그릇을 뒷면이 검은 투명 상자에 넣었다.","④ 향 연기를 모은 작은 그릇을 두 그릇 사이에 넣었다.","⑤ 뚜껑을 열고 향 연기가 움직이는 쪽을 보았다."],"title":"바람 발생 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#1','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C18',1,'mc','auto','날씨 앱 화면을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X32']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C18","difficulty":1,"kind":"mc","stem":"날씨 앱 화면을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"계획하기 → 해 보기 → 나누기","correct":true},{"t":"나누기 → 계획하기 → 해 보기","mis":"SC5-2-u2-X32"},{"t":"해 보기 → 나누기 → 계획하기","mis":"SC5-2-u2-X32"},{"t":"나누기 → 해 보기 → 계획하기","mis":"SC5-2-u2-X32"}],"explanation":["먼저 계획해요.","그다음 만들어요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#2','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',1,'mc','auto','날씨 앱 화면에 넣기 알맞지 않은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C17","difficulty":1,"kind":"mc","stem":"날씨 앱 화면에 넣기 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 집 주소","correct":true},{"t":"현재 기온","mis":"SC5-2-u2-X30"},{"t":"시간별 비 올 확률","mis":"SC5-2-u2-X30"},{"t":"날씨에 맞는 옷차림","mis":"SC5-2-u2-X30"}],"explanation":["날씨 정보를 넣어요.","개인 정보는 빼요.","집 주소는 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#3','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',1,'ox','auto','날씨 앱 화면은 예쁘게 꾸미기만 하면 기상 요소가 없어도 돼요.',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C17","difficulty":1,"kind":"ox","stem":"날씨 앱 화면은 예쁘게 꾸미기만 하면 기상 요소가 없어도 돼요.","answer":"X","reason_options":[{"t":"날씨 앱은 날씨 정보를 정확하고 알기 쉽게 전하는 것이 목적이기 때문에","correct":true},{"t":"꾸밈이 멋지면 날씨 정보는 필요 없기 때문에","mis":"SC5-2-u2-X30"}],"mis":"SC5-2-u2-X30","explanation":["목적은 날씨 정보예요.","기상 요소가 중요해요.","꾸밈은 그다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#4','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',1,'sa','auto','날씨 앱에서 「비가 올지」를 알려 주는 것과 가장 관계있는 기상 요소는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u2-C17","difficulty":1,"kind":"sa","stem":"날씨 앱에서 「비가 올지」를 알려 주는 것과 가장 관계있는 기상 요소는 무엇인가요? 세 글자로 쓰세요.","answer":["강수량"],"explanation":["비·눈이 내린 정도예요.","비 소식과 이어져요.","강수량이에요."],"mis":"SC5-2-u2-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#5','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',2,'mc','auto','날씨 앱 세 가지 견주기에서 시간별 비 소식을 가장 알아보기 쉬운 앱은 어느 것인가요?',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C17","difficulty":2,"kind":"mc","stem":"날씨 앱 세 가지 견주기에서 시간별 비 소식을 가장 알아보기 쉬운 앱은 어느 것인가요?","options":[{"t":"나 앱","correct":true},{"t":"가 앱","mis":"SC5-2-u2-X30"},{"t":"다 앱","mis":"SC5-2-u2-X30"},{"t":"셋 다 알 수 없다","mis":"SC5-2-u2-X30"}],"explanation":["나 앱은 그래프예요.","시간별 비 올 확률이 보여요.","나 앱이에요."],"asset":{"type":"passage","lines":["가 앱 — 큰 아이콘과 현재 기온을 크게 보여 준다.","나 앱 — 시간별 기온·비 올 확률을 그래프로 보여 준다.","다 앱 — 하늘 사진 배경에 오늘 옷차림을 추천해 준다."],"title":"날씨 앱 세 가지 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#6','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C18',2,'mc','auto','날씨 앱 공유 게시판 댓글 가운데 바르고 도움이 되는 댓글만 모은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X32']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C18","difficulty":2,"kind":"mc","stem":"날씨 앱 공유 게시판 댓글 가운데 바르고 도움이 되는 댓글만 모은 것은 어느 것인가요?","options":[{"t":"㉮ ㉰","correct":true},{"t":"㉯ ㉱","mis":"SC5-2-u2-X32"},{"t":"㉮ ㉯","mis":"SC5-2-u2-X32"},{"t":"㉰ ㉱","mis":"SC5-2-u2-X32"}],"explanation":["잘한 점을 짚어요.","보완할 점도 써요.","㉮와 ㉰예요."],"asset":{"type":"passage","lines":["댓글 ㉮ 「비 올 확률 그래프가 한눈에 보여 좋아요. 습도도 넣으면 더 좋겠어요.」","댓글 ㉯ 「별로예요.」","댓글 ㉰ 「배경이 날씨와 잘 어울려요! 기온 숫자를 더 크게 하면 좋겠어요.」","댓글 ㉱ 「우리 모둠이 더 잘했어요 ㅋㅋ」"],"title":"날씨 앱 공유 게시판 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#7','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',2,'mc','auto','날씨 앱이 같은 기상 정보를 보여 주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C17","difficulty":2,"kind":"mc","stem":"날씨 앱이 같은 기상 정보를 보여 주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"아이콘·그래프·숫자·배경 등 여러 방법으로 보여 준다","correct":true},{"t":"글자 한 가지로만 보여 줄 수 있다","mis":"SC5-2-u2-X30"},{"t":"꾸밈 그림만 보여 준다","mis":"SC5-2-u2-X30"},{"t":"기상 정보는 보여 주지 않는다","mis":"SC5-2-u2-X30"}],"explanation":["앱마다 방법이 달라요.","그래프·아이콘을 써요.","알기 쉽게 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#8','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C18',2,'ox','auto','「별로예요.」처럼 까닭 없는 댓글은 친구에게 도움이 되지 않아요.',ARRAY['SC5-2-u2-X32']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C18","difficulty":2,"kind":"ox","stem":"「별로예요.」처럼 까닭 없는 댓글은 친구에게 도움이 되지 않아요.","answer":"O","reason_options":[{"t":"잘한 점과 보완할 점을 구체적으로 써야 도움이 되기 때문에","correct":true},{"t":"짧을수록 좋은 댓글이기 때문에","mis":"SC5-2-u2-X32"}],"mis":"SC5-2-u2-X32","explanation":["까닭이 없어요.","고칠 방향이 없어요.","구체적으로 써요."],"asset":{"type":"passage","lines":["댓글 ㉮ 「비 올 확률 그래프가 한눈에 보여 좋아요. 습도도 넣으면 더 좋겠어요.」","댓글 ㉯ 「별로예요.」","댓글 ㉰ 「배경이 날씨와 잘 어울려요! 기온 숫자를 더 크게 하면 좋겠어요.」","댓글 ㉱ 「우리 모둠이 더 잘했어요 ㅋㅋ」"],"title":"날씨 앱 공유 게시판 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#9','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',2,'mc','auto','모둠 날씨 앱 화면 계획에서 「오후 3시부터 우산 챙겨요!」는 어떤 정보인가요?',ARRAY['SC5-2-u2-X31','SC5-2-u2-X32','SC5-2-u2-X30']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C17","difficulty":2,"kind":"mc","stem":"모둠 날씨 앱 화면 계획에서 「오후 3시부터 우산 챙겨요!」는 어떤 정보인가요?","options":[{"t":"기상 정보를 생활에 맞게 바꾼 생활 정보","correct":true},{"t":"개인 정보","mis":"SC5-2-u2-X31"},{"t":"앱 이름","mis":"SC5-2-u2-X32"},{"t":"꾸밈 그림","mis":"SC5-2-u2-X30"}],"explanation":["비 소식을 담았어요.","할 일을 알려 줘요.","생활 정보예요."],"asset":{"type":"passage","lines":["맨 위 — 앱 이름 「우산 알림이」","가운데 — 현재 기온·최고·최저 기온 큰 숫자","아래 — 시간별 비 올 확률 막대그래프","맨 아래 — 「오후 3시부터 우산 챙겨요!」"],"title":"모둠 날씨 앱 화면 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_basic#10','sci',5,2,'u2','L07','g5_2_sci_u2_L07_basic','lesson_basic','SC5-2-u2-C17',3,'error','auto','날씨 앱 화면을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X31','SC5-2-u2-X30']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C17","difficulty":3,"kind":"error","stem":"날씨 앱 화면을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「인터넷에서 가져온 그림은 출처 없이 써도 돼.」","correct":true,"mis_target":"SC5-2-u2-X31"},{"t":"하준 — 「현재 기온은 크게 보이게 하자.」","mis":"SC5-2-u2-X30"},{"t":"서아 — 「시간별 비 올 확률을 그래프로 넣자.」","mis":"SC5-2-u2-X30"}],"explanation":["그림에도 주인이 있어요.","출처를 밝혀요.","은우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#1','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C18',2,'match','auto','날씨 앱 만드는 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u2-C18","difficulty":2,"kind":"match","stem":"날씨 앱 만드는 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"계획하기","r":"넣을 기상 요소와 배치 정하기"},{"l":"해 보기","r":"디자인 플랫폼으로 화면 만들기"},{"l":"나누기","r":"공유하고 댓글 달기"}],"mis":"SC5-2-u2-X32","explanation":["계획을 세워요.","만들어요.","나누고 댓글 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#2','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C17',2,'mc','auto','날씨 앱 세 가지 견주기에서 「오늘 무엇을 입을지」 바로 알 수 있는 앱은 어느 것인가요?',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C17","difficulty":2,"kind":"mc","stem":"날씨 앱 세 가지 견주기에서 「오늘 무엇을 입을지」 바로 알 수 있는 앱은 어느 것인가요?","options":[{"t":"다 앱","correct":true},{"t":"가 앱","mis":"SC5-2-u2-X30"},{"t":"나 앱","mis":"SC5-2-u2-X30"},{"t":"어느 앱도 알 수 없다","mis":"SC5-2-u2-X30"}],"explanation":["다 앱은 옷차림을 추천해요.","생활 정보예요.","다 앱이에요."],"asset":{"type":"passage","lines":["가 앱 — 큰 아이콘과 현재 기온을 크게 보여 준다.","나 앱 — 시간별 기온·비 올 확률을 그래프로 보여 준다.","다 앱 — 하늘 사진 배경에 오늘 옷차림을 추천해 준다."],"title":"날씨 앱 세 가지 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#3','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C17',3,'mc','auto','저기압이 다가오는 날, 날씨 앱 첫 화면에 크게 보여 주면 좋은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X30','SC5-2-u2-X31']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C17","difficulty":3,"kind":"mc","stem":"저기압이 다가오는 날, 날씨 앱 첫 화면에 크게 보여 주면 좋은 것은 어느 것인가요?","options":[{"t":"구름 많음·비 올 확률·강수량과 우산 챙기기 알림","correct":true},{"t":"맑은 하늘 배경 사진만","mis":"SC5-2-u2-X30"},{"t":"앱 이름과 꾸밈 그림만","mis":"SC5-2-u2-X30"},{"t":"친구들 사진과 이름","mis":"SC5-2-u2-X31"}],"explanation":["저기압은 대체로 흐려요.","비 소식이 중요해요.","크게 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#4','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C18',3,'mc','auto','어느 모둠 화면은 배경 그림이 멋진데 기온 숫자가 아주 작고 강수량이 빠졌어요. 가장 알맞은 댓글은 어느 것인가요?',ARRAY['SC5-2-u2-X32','SC5-2-u2-X30']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C18","difficulty":3,"kind":"mc","stem":"어느 모둠 화면은 배경 그림이 멋진데 기온 숫자가 아주 작고 강수량이 빠졌어요. 가장 알맞은 댓글은 어느 것인가요?","options":[{"t":"「배경이 날씨와 잘 어울려요! 기온 숫자를 크게 하고 비 올 확률도 넣으면 더 좋겠어요.」","correct":true},{"t":"「별로예요.」","mis":"SC5-2-u2-X32"},{"t":"「배경만 예쁘면 충분해요.」","mis":"SC5-2-u2-X30"},{"t":"「우리 모둠이 훨씬 잘했어요.」","mis":"SC5-2-u2-X32"}],"explanation":["잘한 점을 먼저 짚어요.","빠진 요소를 알려요.","고운 말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#5','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C17',3,'ox','auto','모둠 날씨 앱 화면 계획은 기상 요소와 생활 정보가 함께 담겨 있어요.',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C17","difficulty":3,"kind":"ox","stem":"모둠 날씨 앱 화면 계획은 기상 요소와 생활 정보가 함께 담겨 있어요.","answer":"O","reason_options":[{"t":"기온·비 올 확률과 우산 알림이 함께 있기 때문에","correct":true},{"t":"앱 이름만 있고 기상 요소가 없기 때문에","mis":"SC5-2-u2-X30"}],"mis":"SC5-2-u2-X30","explanation":["기온이 있어요.","비 올 확률도 있어요.","우산 알림도 있어요."],"asset":{"type":"passage","lines":["맨 위 — 앱 이름 「우산 알림이」","가운데 — 현재 기온·최고·최저 기온 큰 숫자","아래 — 시간별 비 올 확률 막대그래프","맨 아래 — 「오후 3시부터 우산 챙겨요!」"],"title":"모둠 날씨 앱 화면 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#6','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C18',3,'error','auto','공유 게시판 댓글을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X32']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C18","difficulty":3,"kind":"error","stem":"공유 게시판 댓글을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「㉱처럼 우리 모둠 자랑을 쓰는 게 좋은 댓글이야.」","correct":true,"mis_target":"SC5-2-u2-X32"},{"t":"유나 — 「㉮는 잘한 점과 보완할 점이 다 있어.」","mis":"SC5-2-u2-X32"},{"t":"지호 — 「㉯는 까닭이 없어서 도움이 안 돼.」","mis":"SC5-2-u2-X32"}],"explanation":["자랑은 도움이 안 돼요.","구체적으로 써요.","시우의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["댓글 ㉮ 「비 올 확률 그래프가 한눈에 보여 좋아요. 습도도 넣으면 더 좋겠어요.」","댓글 ㉯ 「별로예요.」","댓글 ㉰ 「배경이 날씨와 잘 어울려요! 기온 숫자를 더 크게 하면 좋겠어요.」","댓글 ㉱ 「우리 모둠이 더 잘했어요 ㅋㅋ」"],"title":"날씨 앱 공유 게시판 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#7','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C17',3,'mc','auto','모둠 날씨 앱 화면 계획에 하나를 더 넣는다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X31','SC5-2-u2-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C17","difficulty":3,"kind":"mc","stem":"모둠 날씨 앱 화면 계획에 하나를 더 넣는다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오늘의 습도와 바람","correct":true},{"t":"모둠원들의 전화번호","mis":"SC5-2-u2-X31"},{"t":"좋아하는 연예인 사진","mis":"SC5-2-u2-X30"},{"t":"출처 없이 가져온 그림","mis":"SC5-2-u2-X31"}],"explanation":["기상 요소를 더해요.","습도와 바람이에요.","날씨 정보가 늘어요."],"asset":{"type":"passage","lines":["맨 위 — 앱 이름 「우산 알림이」","가운데 — 현재 기온·최고·최저 기온 큰 숫자","아래 — 시간별 비 올 확률 막대그래프","맨 아래 — 「오후 3시부터 우산 챙겨요!」"],"title":"모둠 날씨 앱 화면 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#8','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C18',4,'mc','auto','할머니·할아버지가 쓰기 편한 날씨 앱으로 바꾸는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X30','SC5-2-u2-X32','SC5-2-u2-X31']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C18","difficulty":4,"kind":"mc","stem":"할머니·할아버지가 쓰기 편한 날씨 앱으로 바꾸는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글씨와 아이콘을 크게 하고 「오늘 우산 필요해요」처럼 쉬운 문장으로 알린다","correct":true},{"t":"기상 요소를 모두 빼고 꾸밈 그림만 크게 한다","mis":"SC5-2-u2-X30"},{"t":"작은 글씨로 정보를 더 많이 넣는다","mis":"SC5-2-u2-X32"},{"t":"개인 정보를 넣어 맞춤형으로 만든다","mis":"SC5-2-u2-X31"}],"explanation":["쓰는 사람을 생각해요.","크고 쉽게 해요.","정보는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#9','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C17',4,'mc','auto','날씨 앱 세 가지의 좋은 점을 모은 새 앱을 만든다면 가장 알맞은 계획은 어느 것인가요?',ARRAY['SC5-2-u2-X30']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C17","difficulty":4,"kind":"mc","stem":"날씨 앱 세 가지의 좋은 점을 모은 새 앱을 만든다면 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"현재 기온을 크게, 시간별 비 올 확률은 그래프로, 옷차림 추천을 함께 넣는다","correct":true},{"t":"배경 사진만 크게 넣는다","mis":"SC5-2-u2-X30"},{"t":"기온만 작게 넣는다","mis":"SC5-2-u2-X30"},{"t":"셋의 꾸밈 그림만 모은다","mis":"SC5-2-u2-X30"}],"explanation":["가 앱 — 큰 기온이에요.","나 앱 — 그래프예요.","다 앱 — 옷차림이에요."],"asset":{"type":"passage","lines":["가 앱 — 큰 아이콘과 현재 기온을 크게 보여 준다.","나 앱 — 시간별 기온·비 올 확률을 그래프로 보여 준다.","다 앱 — 하늘 사진 배경에 오늘 옷차림을 추천해 준다."],"title":"날씨 앱 세 가지 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L07_challenge#10','sci',5,2,'u2','L07','g5_2_sci_u2_L07_challenge','lesson_challenge','SC5-2-u2-C17',4,'essay','teacher','우리 모둠 날씨 앱 화면을 계획해 앱 이름, 넣을 기상 요소 세 가지와 나타내는 방법, 생활 정보 하나를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C17","difficulty":4,"kind":"essay","stem":"우리 모둠 날씨 앱 화면을 계획해 앱 이름, 넣을 기상 요소 세 가지와 나타내는 방법, 생활 정보 하나를 쓰세요.","answer_guide":{"answer":"예: 앱 이름은 「하늘 친구」. 현재 기온과 최고·최저 기온은 큰 숫자로, 시간별 비 올 확률은 막대그래프로, 구름의 양은 아이콘으로 나타낸다. 생활 정보로 「오늘은 겉옷을 챙기세요」처럼 옷차림을 알려 준다. 그림은 출처를 밝히고 개인 정보는 넣지 않는다.","scoring_points":["기상 요소 세 가지를 썼는가","나타내는 방법(숫자·그래프·아이콘)을 썼는가","생활 정보를 넣었는가"]},"explanation":["기상 요소를 골라요.","나타낼 방법을 정해요.","생활 정보를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#1','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C19',1,'mc','auto','우주에서 지구의 구름 모습을 찍어 날씨를 관측하는 장비는 어느 것인가요?',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"mc","stem":"우주에서 지구의 구름 모습을 찍어 날씨를 관측하는 장비는 어느 것인가요?","options":[{"t":"기상 위성","correct":true},{"t":"해양 기상 부표","mis":"SC5-2-u2-X33"},{"t":"종합 기상 관측탑","mis":"SC5-2-u2-X33"},{"t":"측우기","mis":"SC5-2-u2-X33"}],"explanation":["우주에 있어요.","구름을 찍어요.","기상 위성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#2','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C19',1,'mc','auto','바다 위에 떠서 날씨를 재는 장비는 어느 것인가요?',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"mc","stem":"바다 위에 떠서 날씨를 재는 장비는 어느 것인가요?","options":[{"t":"해양 기상 부표","correct":true},{"t":"기상 위성","mis":"SC5-2-u2-X33"},{"t":"기상 레이더","mis":"SC5-2-u2-X33"},{"t":"레윈존데","mis":"SC5-2-u2-X33"}],"explanation":["바다에 떠 있어요.","파도와 바람을 재요.","부표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#3','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C19',1,'sa','auto','여러 가지 기상 요소를 재고 기상 현상을 살피는 것을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"sa","stem":"여러 가지 기상 요소를 재고 기상 현상을 살피는 것을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["기상 관측","기상관측"],"explanation":["기상 요소를 재요.","현상을 살펴요.","기상 관측이에요."],"mis":"SC5-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#4','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C20',1,'ox','auto','일기 예보는 관측 장비 자료만 있으면 사람의 판단 없이 저절로 정확해져요.',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C20","difficulty":1,"kind":"ox","stem":"일기 예보는 관측 장비 자료만 있으면 사람의 판단 없이 저절로 정확해져요.","answer":"X","reason_options":[{"t":"예보관이 분석한 자료와 실제 상황을 종합해 판단해야 하기 때문에","correct":true},{"t":"기계가 모든 것을 다 하기 때문에","mis":"SC5-2-u2-X34"}],"mis":"SC5-2-u2-X34","explanation":["자료를 분석해요.","예보관이 판단해요.","사람의 판단이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#5','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C19',2,'match','auto','관측 장소와 그곳의 관측 장비를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-2-u2-C19","difficulty":2,"kind":"match","stem":"관측 장소와 그곳의 관측 장비를 알맞게 이으세요.","pairs":[{"l":"땅","r":"종합 기상 관측탑"},{"l":"바다","r":"해양 기상 관측선"},{"l":"하늘","r":"풍선에 단 레윈존데"},{"l":"우주","r":"기상 위성"}],"mis":"SC5-2-u2-X33","explanation":["땅엔 관측탑이에요.","바다엔 관측선이에요.","우주엔 위성이에요."],"asset":{"type":"passage","lines":["㉠ 땅 — 종합 기상 관측탑 · 기상 레이더","㉡ 바다 — 해양 기상 관측선 · 해양 기상 부표","㉢ 하늘 — 풍선에 단 레윈존데 · 드론","㉣ 우주 — 기상 위성"],"title":"어디에서 날씨를 잴까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#6','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C20',2,'mc','auto','일기 예보가 나오기까지의 ④에 들어갈 사람은 어느 것인가요?',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"mc","stem":"일기 예보가 나오기까지의 ④에 들어갈 사람은 어느 것인가요?","options":[{"t":"일기 예보관","correct":true},{"t":"슈퍼컴퓨터","mis":"SC5-2-u2-X34"},{"t":"관측 장비","mis":"SC5-2-u2-X34"},{"t":"아무도 없다","mis":"SC5-2-u2-X34"}],"explanation":["자료를 종합해요.","사람이 판단해요.","예보관이에요."],"asset":{"type":"passage","lines":["① 땅·바다·하늘·우주에서 기상 요소를 잰다.","② 다른 나라의 관측 자료도 함께 모은다.","③ 슈퍼컴퓨터가 모은 자료를 분석한다.","④ (    )이 자료와 실제 상황을 종합해 예보를 발표한다."],"title":"일기 예보가 나오기까지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#7','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C19',2,'mc','auto','집이나 학교에서 기상 요소를 재는 방법을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X04','SC5-2-u2-X33']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C19","difficulty":2,"kind":"mc","stem":"집이나 학교에서 기상 요소를 재는 방법을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"온도계 — 기온 · 빗물 받기 — 강수량","correct":true},{"t":"온도계 — 강수량 · 빗물 받기 — 기온","mis":"SC5-2-u2-X04"},{"t":"바람개비 — 습도 · 온도계 — 바람","mis":"SC5-2-u2-X04"},{"t":"기상 요소는 집에서 잴 수 없다","mis":"SC5-2-u2-X33"}],"explanation":["온도계는 기온이에요.","빗물은 강수량이에요.","생활에서도 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#8','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C20',2,'ox','auto','일기 예보에는 우리나라뿐 아니라 다른 나라의 관측 자료도 함께 쓰여요.',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"ox","stem":"일기 예보에는 우리나라뿐 아니라 다른 나라의 관측 자료도 함께 쓰여요.","answer":"O","reason_options":[{"t":"날씨는 넓은 지역의 공기와 구름이 움직이며 바뀌기 때문에","correct":true},{"t":"우리나라 날씨는 우리나라 자료만으로 충분하기 때문에","mis":"SC5-2-u2-X34"}],"mis":"SC5-2-u2-X34","explanation":["구름은 나라를 넘어요.","전 세계 자료를 모아요.","함께 써요."],"asset":{"type":"passage","lines":["① 땅·바다·하늘·우주에서 기상 요소를 잰다.","② 다른 나라의 관측 자료도 함께 모은다.","③ 슈퍼컴퓨터가 모은 자료를 분석한다.","④ (    )이 자료와 실제 상황을 종합해 예보를 발표한다."],"title":"일기 예보가 나오기까지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#9','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C21',2,'mc','auto','날씨와 우리 생활 단원에서 배운 내용으로 옳은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X16','SC5-2-u2-X26','SC5-2-u2-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C21","difficulty":2,"kind":"mc","stem":"날씨와 우리 생활 단원에서 배운 내용으로 옳은 것은 어느 것인가요?","options":[{"t":"이슬·안개·구름은 수증기가 응결해 생긴다","correct":true},{"t":"구름은 지표면 가까이에 떠 있다","mis":"SC5-2-u2-X16"},{"t":"바람은 저기압에서 고기압으로 분다","mis":"SC5-2-u2-X26"},{"t":"하늘의 색깔도 기상 요소이다","mis":"SC5-2-u2-X03"}],"explanation":["셋 다 응결이에요.","구름은 높은 곳이에요.","바람은 고 → 저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_basic#10','sci',5,2,'u2','L08','g5_2_sci_u2_L08_basic','lesson_basic','SC5-2-u2-C19',3,'error','auto','관측 장비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C19","difficulty":3,"kind":"error","stem":"관측 장비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「기상 위성은 바다 위에 떠서 파도를 재.」","correct":true,"mis_target":"SC5-2-u2-X33"},{"t":"도윤 — 「레윈존데는 풍선에 달아 하늘로 올려.」","mis":"SC5-2-u2-X33"},{"t":"민서 — 「기상 위성은 우주에서 구름을 찍어.」","mis":"SC5-2-u2-X33"}],"explanation":["위성은 우주에 있어요.","바다엔 부표가 있어요.","예린의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 땅 — 종합 기상 관측탑 · 기상 레이더","㉡ 바다 — 해양 기상 관측선 · 해양 기상 부표","㉢ 하늘 — 풍선에 단 레윈존데 · 드론","㉣ 우주 — 기상 위성"],"title":"어디에서 날씨를 잴까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
