INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#2','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C20',2,'mc','auto','일기 예보가 나오는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"mc","stem":"일기 예보가 나오는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"관측 → 분석 → 판단","correct":true},{"t":"판단 → 관측 → 분석","mis":"SC5-2-u2-X34"},{"t":"분석 → 판단 → 관측","mis":"SC5-2-u2-X34"},{"t":"관측만 하면 끝난다","mis":"SC5-2-u2-X34"}],"explanation":["먼저 재요.","컴퓨터로 분석해요.","예보관이 판단해요."],"asset":{"type":"passage","lines":["① 땅·바다·하늘·우주에서 기상 요소를 잰다.","② 다른 나라의 관측 자료도 함께 모은다.","③ 슈퍼컴퓨터가 모은 자료를 분석한다.","④ (    )이 자료와 실제 상황을 종합해 예보를 발표한다."],"title":"일기 예보가 나오기까지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#3','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C21',3,'mc','auto','맑은 날 낮 바닷가에 고기압과 저기압이 생긴 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X28','SC5-2-u2-X35','SC5-2-u2-X29']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"mc","stem":"맑은 날 낮 바닷가에 고기압과 저기압이 생긴 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"육지 위 — 저기압 · 바다 위 — 고기압","correct":true},{"t":"육지 위 — 고기압 · 바다 위 — 저기압","mis":"SC5-2-u2-X28"},{"t":"둘 다 고기압","mis":"SC5-2-u2-X35"},{"t":"바닷가에는 기압 차이가 없다","mis":"SC5-2-u2-X29"}],"explanation":["낮엔 육지가 따뜻해요.","육지 위는 저기압이에요.","해풍이 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#4','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C20',3,'ox','auto','기상청은 모은 관측 자료를 슈퍼컴퓨터로 분석하고, 예보관이 종합해 예보와 주의보를 발표해요.',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C20","difficulty":3,"kind":"ox","stem":"기상청은 모은 관측 자료를 슈퍼컴퓨터로 분석하고, 예보관이 종합해 예보와 주의보를 발표해요.","answer":"O","reason_options":[{"t":"관측 → 분석 → 판단이 이어져야 정확한 예보가 되기 때문에","correct":true},{"t":"슈퍼컴퓨터가 혼자 예보를 발표하기 때문에","mis":"SC5-2-u2-X34"}],"mis":"SC5-2-u2-X34","explanation":["컴퓨터가 분석해요.","예보관이 판단해요.","함께 예보를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#5','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C21',3,'mc','auto','이슬·안개·구름과 고기압·저기압을 견주는 기준을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X21','SC5-2-u2-X35']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"mc","stem":"이슬·안개·구름과 고기압·저기압을 견주는 기준을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"이슬·안개·구름 — 생기는 자리 · 고기압·저기압 — 날씨 특징","correct":true},{"t":"이슬·안개·구름 — 색깔 · 고기압·저기압 — 정해진 숫자","mis":"SC5-2-u2-X21"},{"t":"이슬·안개·구름 — 생기는 날짜 · 고기압·저기압 — 바람의 세기","mis":"SC5-2-u2-X35"},{"t":"둘 다 견줄 수 없다","mis":"SC5-2-u2-X35"}],"explanation":["이슬은 표면, 구름은 높은 곳이에요.","고기압은 대체로 맑아요.","기준이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#6','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C21',3,'error','auto','단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X16','SC5-2-u2-X26','SC5-2-u2-X23']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"error","stem":"단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「안개와 구름은 같은 높이에 생기니까 이름만 달라.」","correct":true,"mis_target":"SC5-2-u2-X16"},{"t":"서아 — 「바람은 고기압에서 저기압으로 불어.」","mis":"SC5-2-u2-X26"},{"t":"지호 — 「고기압이 있는 곳은 대체로 맑아.」","mis":"SC5-2-u2-X23"}],"explanation":["안개는 땅 가까이예요.","구름은 높은 곳이에요.","하준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#7','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C19',3,'mc','auto','풍선에 관측 장비를 달아 하늘 높이 올려 보내는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X33']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C19","difficulty":3,"kind":"mc","stem":"풍선에 관측 장비를 달아 하늘 높이 올려 보내는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"땅에서는 잴 수 없는 높은 하늘의 기상 요소를 재려고","correct":true},{"t":"풍선으로 구름을 없애려고","mis":"SC5-2-u2-X10"},{"t":"바다의 파도를 재려고","mis":"SC5-2-u2-X33"},{"t":"우주에서 구름 사진을 찍으려고","mis":"SC5-2-u2-X33"}],"explanation":["높은 하늘도 재야 해요.","풍선에 달아 올려요.","레윈존데예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#8','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C21',4,'mc','auto','내일 기온 15 °C, 습도 80 %, 구름 많음이라는 자료가 있어요. 가장 알맞은 생활 안내는 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X23','SC5-2-u2-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C21","difficulty":4,"kind":"mc","stem":"내일 기온 15 °C, 습도 80 %, 구름 많음이라는 자료가 있어요. 가장 알맞은 생활 안내는 어느 것인가요?","options":[{"t":"구름이 많고 습도가 높아 비가 올 수 있으니 우산을 챙기세요","correct":true},{"t":"구름이 많으니 빨래를 밖에 널기 좋아요","mis":"SC5-2-u2-X09"},{"t":"습도가 높으면 항상 눈이 오니 썰매를 챙기세요","mis":"SC5-2-u2-X23"},{"t":"날씨와 상관없이 평소처럼 지내세요","mis":"SC5-2-u2-X01"}],"explanation":["습도가 높아요.","구름도 많아요.","우산을 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#9','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C20',4,'mc','auto','「예보는 기계가 다 하니 일기 예보관은 필요 없다」는 말을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X34']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C20","difficulty":4,"kind":"mc","stem":"「예보는 기계가 다 하니 일기 예보관은 필요 없다」는 말을 바르게 고친 것은 어느 것인가요?","options":[{"t":"기계가 분석한 자료를 예보관이 실제 상황과 종합해 판단해야 정확한 예보가 된다","correct":true},{"t":"예보관이 날씨를 직접 바꾸어야 한다","mis":"SC5-2-u2-X10"},{"t":"우리나라 관측 자료만 있으면 기계로 충분하다","mis":"SC5-2-u2-X34"},{"t":"관측 장비만 있으면 분석도 필요 없다","mis":"SC5-2-u2-X34"}],"explanation":["기계가 분석해요.","사람이 판단해요.","둘 다 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_L08_challenge#10','sci',5,2,'u2','L08','g5_2_sci_u2_L08_challenge','lesson_challenge','SC5-2-u2-C21',4,'essay','teacher','내일 날씨를 기상 요소 세 가지 이상으로 예보하는 문장을 쓰고, 그 날씨에 맞는 생활 안내를 붙인 뒤 그 날씨가 고기압과 저기압 가운데 무엇의 영향일지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C21","difficulty":4,"kind":"essay","stem":"내일 날씨를 기상 요소 세 가지 이상으로 예보하는 문장을 쓰고, 그 날씨에 맞는 생활 안내를 붙인 뒤 그 날씨가 고기압과 저기압 가운데 무엇의 영향일지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 내일은 기온 25 °C, 습도 40 %, 구름이 거의 없고 비가 오지 않겠습니다. 햇볕이 좋아 빨래를 널거나 소풍을 가기 좋습니다. 구름이 적고 맑은 날씨이므로 고기압의 영향을 받을 것으로 예상합니다.","scoring_points":["기상 요소 세 가지 이상으로 예보했는가","날씨에 맞는 생활 안내를 붙였는가","고기압·저기압을 까닭과 함께 썼는가"]},"explanation":["기상 요소로 써요.","생활 안내를 붙여요.","기압과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#1','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C1',1,'mc','auto','하늘반 일지 ①에서 비 때문에 생긴 생활 모습은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"mc","stem":"하늘반 일지 ①에서 비 때문에 생긴 생활 모습은 어느 것인가요?","options":[{"t":"우산을 쓰고 장화를 신고 왔다","correct":true},{"t":"반소매를 입고 부채질을 했다","mis":"SC5-2-u2-X09"},{"t":"눈사람을 만들었다","mis":"SC5-2-u2-X09"},{"t":"날씨와 상관없이 평소와 같았다","mis":"SC5-2-u2-X01"}],"explanation":["월요일은 비가 왔어요.","우산과 장화를 챙겼어요.","날씨가 생활을 바꿔요."],"asset":{"type":"passage","lines":["월요일 아침, 비가 내려 친구들이 우산을 쓰고 장화를 신고 왔다.","점심시간에는 운동장 대신 강당에서 놀았다.","하교할 때 빨래를 밖에 널어 둔 집이 있는지 걱정하는 친구도 있었다."],"title":"① 월요일 — 비 오는 날의 학교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#2','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C2',1,'mc','auto','공기 중에 수증기가 포함된 정도를 나타내는 기상 요소는 어느 것인가요? (하늘반 일지 ② 기준)',ARRAY['SC5-2-u2-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"mc","stem":"공기 중에 수증기가 포함된 정도를 나타내는 기상 요소는 어느 것인가요? (하늘반 일지 ② 기준)","options":[{"t":"습도","correct":true},{"t":"기온","mis":"SC5-2-u2-X04"},{"t":"강수량","mis":"SC5-2-u2-X04"},{"t":"구름의 양","mis":"SC5-2-u2-X04"}],"explanation":["85 %로 적혀 있어요.","수증기 정도예요.","습도예요."],"asset":{"type":"passage","lines":["화요일 우리 지역 — 기온 12 °C · 습도 85 % · 구름 많음 · 강수량 8 mm","운동장 깃발은 남쪽을 향해 펄럭였다.","얼굴에 바람이 닿은 쪽은 북쪽이었다.","모둠마다 날씨누리에서 우리 지역 날씨를 찾아 적었다."],"title":"② 화요일 — 기상 요소 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#3','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C4',1,'mc','auto','하늘반 일지 ②의 바람 관찰로 알 수 있는 풍향은 어느 것인가요?',ARRAY['SC5-2-u2-X07','SC5-2-u2-X06','SC5-2-u2-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C4","difficulty":1,"kind":"mc","stem":"하늘반 일지 ②의 바람 관찰로 알 수 있는 풍향은 어느 것인가요?","options":[{"t":"북풍","correct":true},{"t":"남풍","mis":"SC5-2-u2-X07"},{"t":"서풍","mis":"SC5-2-u2-X06"},{"t":"알 수 없다","mis":"SC5-2-u2-X03"}],"explanation":["바람이 북쪽에서 와요.","깃발은 남쪽을 향해요.","북풍이에요."],"asset":{"type":"passage","lines":["화요일 우리 지역 — 기온 12 °C · 습도 85 % · 구름 많음 · 강수량 8 mm","운동장 깃발은 남쪽을 향해 펄럭였다.","얼굴에 바람이 닿은 쪽은 북쪽이었다.","모둠마다 날씨누리에서 우리 지역 날씨를 찾아 적었다."],"title":"② 화요일 — 기상 요소 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#4','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C8',1,'mc','auto','하늘반 일지 ④에서 풀잎과 거미줄에 맺힌 물방울은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C8","difficulty":1,"kind":"mc","stem":"하늘반 일지 ④에서 풀잎과 거미줄에 맺힌 물방울은 어느 것인가요?","options":[{"t":"이슬","correct":true},{"t":"안개","mis":"SC5-2-u2-X17"},{"t":"구름","mis":"SC5-2-u2-X17"},{"t":"비","mis":"SC5-2-u2-X14"}],"explanation":["물체 표면에 맺혀요.","풀잎·거미줄이에요.","이슬이에요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#5','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C10',1,'sa','auto','하늘반 일지 ④에서 산 위 하늘에 떠 있던 하얀 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-2-u2-C10","difficulty":1,"kind":"sa","stem":"하늘반 일지 ④에서 산 위 하늘에 떠 있던 하얀 것은 무엇인가요? 두 글자로 쓰세요.","answer":["구름"],"explanation":["높은 곳에 떠 있어요.","하늘에 보여요.","구름이에요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"},"mis":"SC5-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#6','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C11',1,'mc','auto','하늘반 일지 ⑥의 예보 지도에 표시된 「고기압」의 뜻은 어느 것인가요?',ARRAY['SC5-2-u2-X20','SC5-2-u2-X21','SC5-2-u2-X04']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑥의 예보 지도에 표시된 「고기압」의 뜻은 어느 것인가요?","options":[{"t":"주변보다 기압이 높은 곳","correct":true},{"t":"주변보다 기압이 낮은 곳","mis":"SC5-2-u2-X20"},{"t":"기압이 정해진 숫자보다 높은 곳","mis":"SC5-2-u2-X21"},{"t":"습도가 높은 곳","mis":"SC5-2-u2-X04"}],"explanation":["주변과 견줘요.","높으면 고기압이에요.","상대적이에요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#7','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C15',1,'mc','auto','바람이 부는 방향을 기압으로 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X28','SC5-2-u2-X29']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C15","difficulty":1,"kind":"mc","stem":"바람이 부는 방향을 기압으로 바르게 말한 것은 어느 것인가요?","options":[{"t":"고기압에서 저기압으로","correct":true},{"t":"저기압에서 고기압으로","mis":"SC5-2-u2-X26"},{"t":"늘 바다에서 육지로","mis":"SC5-2-u2-X28"},{"t":"위에서 아래로만","mis":"SC5-2-u2-X29"}],"explanation":["공기는 이동해요.","고기압에서 출발해요.","저기압으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#8','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C19',1,'mc','auto','하늘반 일지 ⑧에서 우주에서 구름의 모습을 찍는 장비는 어느 것인가요?',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑧에서 우주에서 구름의 모습을 찍는 장비는 어느 것인가요?","options":[{"t":"기상 위성","correct":true},{"t":"부표","mis":"SC5-2-u2-X33"},{"t":"레윈존데","mis":"SC5-2-u2-X33"},{"t":"온도계","mis":"SC5-2-u2-X33"}],"explanation":["우주에 있어요.","구름을 찍어요.","기상 위성이에요."],"asset":{"type":"passage","lines":["일요일, 일주일 기록으로 모둠 날씨 앱 「하늘반 날씨」 화면을 만들었다.","기온은 큰 숫자, 비 올 확률은 그래프, 옷차림 알림을 넣었다.","기상 위성·부표·레윈존데가 잰 자료가 예보가 된다는 것도 적었다."],"title":"⑧ 일요일 — 날씨 앱과 관측 장비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#9','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C3',2,'mc','auto','하늘반 일지 ②의 화요일 날씨를 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X05','SC5-2-u2-X06']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"mc","stem":"하늘반 일지 ②의 화요일 날씨를 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"구름이 많고 습도가 높으며 비가 왔다","correct":true},{"t":"구름이 적고 습도가 낮아 맑았다","mis":"SC5-2-u2-X05"},{"t":"비가 왔지만 습도는 낮았다","mis":"SC5-2-u2-X05"},{"t":"기온만 보면 다 알 수 있다","mis":"SC5-2-u2-X06"}],"explanation":["습도가 85 %예요.","구름이 많아요.","비가 8 mm 왔어요."],"asset":{"type":"passage","lines":["화요일 우리 지역 — 기온 12 °C · 습도 85 % · 구름 많음 · 강수량 8 mm","운동장 깃발은 남쪽을 향해 펄럭였다.","얼굴에 바람이 닿은 쪽은 북쪽이었다.","모둠마다 날씨누리에서 우리 지역 날씨를 찾아 적었다."],"title":"② 화요일 — 기상 요소 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#10','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C6',2,'mc','auto','하늘반 일지 ③에서 예보를 보고 한 대처로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X11','SC5-2-u2-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C6","difficulty":2,"kind":"mc","stem":"하늘반 일지 ③에서 예보를 보고 한 대처로 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 닫고 체육을 강당 수업으로 바꾸었다","correct":true},{"t":"화분을 베란다 밖으로 더 내놓았다","mis":"SC5-2-u2-X09"},{"t":"예보와 상관없이 운동장에서 체육을 했다","mis":"SC5-2-u2-X11"},{"t":"바람이 멈추게 했다","mis":"SC5-2-u2-X10"}],"explanation":["강한 바람과 비예요.","창문을 닫았어요.","실내로 옮겼어요."],"asset":{"type":"passage","lines":["수요일 아침, 강한 바람과 비 예보가 나왔다.","교실 창문을 닫고 운동장 체육을 강당 수업으로 바꾸었다.","집에 가서 베란다 화분을 들여놓기로 했다.","하은이는 「예보를 미리 봐서 다행이야」라고 말했다."],"title":"③ 수요일 — 예보와 대처"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#11','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C10',2,'mc','auto','하늘반 일지 ④의 세 가지를 생기는 자리로 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X16']::text[],false,'{"seq":11,"concept":"SC5-2-u2-C10","difficulty":2,"kind":"mc","stem":"하늘반 일지 ④의 세 가지를 생기는 자리로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"풀잎 물방울 — 물체 표면 · 강가의 뿌연 것 — 지표면 가까이 · 산 위 하얀 것 — 높은 곳","correct":true},{"t":"풀잎 물방울 — 높은 곳 · 강가 — 물체 표면","mis":"SC5-2-u2-X17"},{"t":"셋 다 높은 곳","mis":"SC5-2-u2-X16"},{"t":"셋 다 물체 표면","mis":"SC5-2-u2-X17"}],"explanation":["이슬은 표면이에요.","안개는 땅 가까이예요.","구름은 높은 곳이에요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#12','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C12',2,'mc','auto','하늘반 일지 ⑥의 위성 사진처럼 구름이 거의 없는 날은 대체로 무엇의 영향을 받나요?',ARRAY['SC5-2-u2-X22','SC5-2-u2-X04','SC5-2-u2-X07']::text[],false,'{"seq":12,"concept":"SC5-2-u2-C12","difficulty":2,"kind":"mc","stem":"하늘반 일지 ⑥의 위성 사진처럼 구름이 거의 없는 날은 대체로 무엇의 영향을 받나요?","options":[{"t":"고기압","correct":true},{"t":"저기압","mis":"SC5-2-u2-X22"},{"t":"습도","mis":"SC5-2-u2-X04"},{"t":"풍향","mis":"SC5-2-u2-X07"}],"explanation":["구름이 적어요.","대체로 맑아요.","고기압이에요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#13','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C14',2,'mc','auto','지면 위의 공기가 따뜻해지면 기압은 어떻게 되나요?',ARRAY['SC5-2-u2-X25','SC5-2-u2-X29']::text[],false,'{"seq":13,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"mc","stem":"지면 위의 공기가 따뜻해지면 기압은 어떻게 되나요?","options":[{"t":"낮아진다","correct":true},{"t":"높아진다","mis":"SC5-2-u2-X25"},{"t":"변하지 않는다","mis":"SC5-2-u2-X29"},{"t":"공기가 없어진다","mis":"SC5-2-u2-X29"}],"explanation":["따뜻하면 가벼워요.","기압이 낮아져요.","저기압이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#14','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C16',2,'mc','auto','하늘반 일지 ⑦에서 낮에 바람자루를 육지 쪽으로 펄럭이게 한 바람은 어느 것인가요?',ARRAY['SC5-2-u2-X28','SC5-2-u2-X29','SC5-2-u2-X07']::text[],false,'{"seq":14,"concept":"SC5-2-u2-C16","difficulty":2,"kind":"mc","stem":"하늘반 일지 ⑦에서 낮에 바람자루를 육지 쪽으로 펄럭이게 한 바람은 어느 것인가요?","options":[{"t":"해풍","correct":true},{"t":"육풍","mis":"SC5-2-u2-X28"},{"t":"바람이 없었다","mis":"SC5-2-u2-X29"},{"t":"북풍","mis":"SC5-2-u2-X07"}],"explanation":["바다에서 육지로 불어요.","낮에 불어요.","해풍이에요."],"asset":{"type":"passage","lines":["토요일, 맑은 날 바닷가로 가족 나들이를 갔다.","낮에는 바닷가 바람자루가 육지 쪽으로 펄럭였다.","저녁에는 해변 모닥불 연기가 바다 쪽으로 흘러갔다."],"title":"⑦ 토요일 — 바닷가 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#15','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C17',2,'mc','auto','하늘반 일지 ⑧의 「하늘반 날씨」 화면에서 기상 요소를 나타낸 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X30','SC5-2-u2-X31']::text[],false,'{"seq":15,"concept":"SC5-2-u2-C17","difficulty":2,"kind":"mc","stem":"하늘반 일지 ⑧의 「하늘반 날씨」 화면에서 기상 요소를 나타낸 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"기온은 큰 숫자, 비 올 확률은 그래프","correct":true},{"t":"배경 그림만 크게","mis":"SC5-2-u2-X30"},{"t":"친구 이름과 사진","mis":"SC5-2-u2-X31"},{"t":"기상 요소 없이 꾸밈만","mis":"SC5-2-u2-X30"}],"explanation":["기온은 숫자예요.","비 올 확률은 그래프예요.","알기 쉬워요."],"asset":{"type":"passage","lines":["일요일, 일주일 기록으로 모둠 날씨 앱 「하늘반 날씨」 화면을 만들었다.","기온은 큰 숫자, 비 올 확률은 그래프, 옷차림 알림을 넣었다.","기상 위성·부표·레윈존데가 잰 자료가 예보가 된다는 것도 적었다."],"title":"⑧ 일요일 — 날씨 앱과 관측 장비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#16','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C20',2,'mc','auto','관측 자료가 일기 예보가 되기까지의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":16,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"mc","stem":"관측 자료가 일기 예보가 되기까지의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"관측 → 분석 → 판단","correct":true},{"t":"판단 → 분석 → 관측","mis":"SC5-2-u2-X34"},{"t":"분석 → 관측 → 판단","mis":"SC5-2-u2-X34"},{"t":"관측만 하면 된다","mis":"SC5-2-u2-X34"}],"explanation":["먼저 재요.","분석해요.","판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#17','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C4',3,'mc','auto','하늘반 일지 ②와 ⑥을 보고 화요일과 금요일 날씨를 가장 잘 견준 것은 어느 것인가요?',ARRAY['SC5-2-u2-X08','SC5-2-u2-X05','SC5-2-u2-X06']::text[],false,'{"seq":17,"concept":"SC5-2-u2-C4","difficulty":3,"kind":"mc","stem":"하늘반 일지 ②와 ⑥을 보고 화요일과 금요일 날씨를 가장 잘 견준 것은 어느 것인가요?","options":[{"t":"화요일은 기온이 낮고 습도·구름이 많아 비가 왔고, 금요일은 습도가 낮고 구름이 적어 비가 오지 않았다","correct":true},{"t":"두 날 모두 「맑음」이라 견줄 것이 없다","mis":"SC5-2-u2-X08"},{"t":"금요일이 비가 더 많이 왔다","mis":"SC5-2-u2-X05"},{"t":"기온만 다르고 나머지는 같다","mis":"SC5-2-u2-X06"}],"explanation":["기상 요소로 견줘요.","습도·구름이 달라요.","강수량도 달라요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#18','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C8',3,'mc','auto','하늘반 일지 ⑤의 캔 실험과 ④의 풀잎 물방울이 같은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X14','SC5-2-u2-X13','SC5-2-u2-X19']::text[],false,'{"seq":18,"concept":"SC5-2-u2-C8","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑤의 캔 실험과 ④의 풀잎 물방울이 같은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 공기 중의 수증기가 차가운 표면에 응결해 맺혔다","correct":true},{"t":"둘 다 하늘에서 내린 비이다","mis":"SC5-2-u2-X14"},{"t":"둘 다 캔이나 풀잎 속 물이 스며 나왔다","mis":"SC5-2-u2-X13"},{"t":"둘 다 데워져서 물방울이 생겼다","mis":"SC5-2-u2-X19"}],"explanation":["표면이 차가워요.","수증기가 응결해요.","이슬과 같아요."],"asset":{"type":"passage","lines":["목요일 오후, 차가운 캔 겉면을 닦고 두었더니 물방울이 맺혔다.","집기병에 얼음 지퍼 백을 얹었더니 안이 뿌옇게 흐려졌다.","두 실험을 새벽에 본 것과 견주어 실험관찰에 적었다."],"title":"⑤ 목요일 오후 — 두 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#19','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C13',3,'ox','auto','고기압이 있는 날에도 구름이 조금 낄 수 있어요.',ARRAY['SC5-2-u2-X23']::text[],false,'{"seq":19,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"ox","stem":"고기압이 있는 날에도 구름이 조금 낄 수 있어요.","answer":"O","reason_options":[{"t":"고기압은 「대체로」 맑은 것이지 항상 맑은 것은 아니기 때문에","correct":true},{"t":"고기압이면 항상 구름 한 점 없기 때문에","mis":"SC5-2-u2-X23"}],"mis":"SC5-2-u2-X23","explanation":["대체로 맑아요.","항상은 아니에요.","구름이 낄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#20','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C15',3,'mc','auto','얼음물 그릇과 따뜻한 물 그릇 사이에 향 연기를 넣으면 연기는 어떻게 움직일까요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X27','SC5-2-u2-X29']::text[],false,'{"seq":20,"concept":"SC5-2-u2-C15","difficulty":3,"kind":"mc","stem":"얼음물 그릇과 따뜻한 물 그릇 사이에 향 연기를 넣으면 연기는 어떻게 움직일까요?","options":[{"t":"얼음물 쪽에서 따뜻한 물 쪽으로","correct":true},{"t":"따뜻한 물 쪽에서 얼음물 쪽으로","mis":"SC5-2-u2-X26"},{"t":"위로만 올라간다","mis":"SC5-2-u2-X27"},{"t":"움직이지 않는다","mis":"SC5-2-u2-X29"}],"explanation":["얼음물이 차가워요.","얼음물 쪽이 고기압이에요.","물 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#21','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C6',3,'mc','auto','하늘반 일지 ③에서 예보를 미리 보지 않았다면 생길 수 있는 일은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X11']::text[],false,'{"seq":21,"concept":"SC5-2-u2-C6","difficulty":3,"kind":"mc","stem":"하늘반 일지 ③에서 예보를 미리 보지 않았다면 생길 수 있는 일은 어느 것인가요?","options":[{"t":"화분이 바람에 떨어지거나 운동장 체육 중 비를 맞을 수 있다","correct":true},{"t":"바람이 불지 않았을 것이다","mis":"SC5-2-u2-X10"},{"t":"아무 일도 생기지 않는다","mis":"SC5-2-u2-X11"},{"t":"날씨가 맑아졌을 것이다","mis":"SC5-2-u2-X10"}],"explanation":["예보로 대비했어요.","안 봤다면 피해가 생겨요.","미리 아는 게 중요해요."],"asset":{"type":"passage","lines":["수요일 아침, 강한 바람과 비 예보가 나왔다.","교실 창문을 닫고 운동장 체육을 강당 수업으로 바꾸었다.","집에 가서 베란다 화분을 들여놓기로 했다.","하은이는 「예보를 미리 봐서 다행이야」라고 말했다."],"title":"③ 수요일 — 예보와 대처"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#22','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C21',3,'mc','auto','하늘반 일지 ⑥의 금요일에 바닷가로 간다면 낮에 부는 바람과 날씨를 가장 바르게 예상한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X29','SC5-2-u2-X28']::text[],false,'{"seq":22,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"mc","stem":"하늘반 일지 ⑥의 금요일에 바닷가로 간다면 낮에 부는 바람과 날씨를 가장 바르게 예상한 것은 어느 것인가요?","options":[{"t":"고기압으로 대체로 맑고, 낮에는 바다에서 육지로 해풍이 분다","correct":true},{"t":"저기압으로 비가 오고, 낮에 육풍이 분다","mis":"SC5-2-u2-X24"},{"t":"고기압이니 바람이 전혀 불지 않는다","mis":"SC5-2-u2-X29"},{"t":"맑으니 낮에 육지에서 바다로 분다","mis":"SC5-2-u2-X28"}],"explanation":["고기압이라 맑아요.","낮엔 육지가 따뜻해요.","해풍이 불어요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#23','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C10',4,'essay','teacher','하늘반 일지 ④의 세 가지가 각각 무엇인지 쓰고, 공통점과 차이점을 생기는 자리로 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u2-C10","difficulty":4,"kind":"essay","stem":"하늘반 일지 ④의 세 가지가 각각 무엇인지 쓰고, 공통점과 차이점을 생기는 자리로 설명하세요.","answer_guide":{"answer":"예: 풀잎과 거미줄의 물방울은 이슬, 강가에 낮게 깔린 뿌연 것은 안개, 산 위 하늘의 하얀 것은 구름이다. 셋 모두 공기 중의 수증기가 응결해 생긴다. 이슬은 물체 표면에 맺히고, 안개는 지표면 가까이에, 구름은 높은 곳에 떠 있다는 점이 다르다.","scoring_points":["셋의 이름을 바르게 썼는가","공통점(수증기의 응결)을 썼는가","생기는 자리 차이를 썼는가"]},"explanation":["이름을 찾아요.","공통점은 응결이에요.","자리가 달라요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#24','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C16',4,'essay','teacher','하늘반 일지 ⑦에서 낮과 저녁의 바람 방향이 왜 바뀌었는지 온도 → 기압 → 바람의 순서로 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u2-C16","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑦에서 낮과 저녁의 바람 방향이 왜 바뀌었는지 온도 → 기압 → 바람의 순서로 설명하세요.","answer_guide":{"answer":"예: 낮에는 육지가 바다보다 빨리 데워져 육지 위 공기가 가벼워지고 저기압, 바다 위가 고기압이 되어 바다에서 육지로 해풍이 불었다. 저녁에는 육지가 빨리 식어 육지 위가 고기압, 바다 위가 저기압이 되어 육지에서 바다로 육풍이 불어 연기가 바다 쪽으로 흘러갔다.","scoring_points":["낮의 온도·기압·바람을 썼는가","저녁의 온도·기압·바람을 썼는가","고기압에서 저기압으로 분다는 것을 썼는가"]},"explanation":["낮엔 해풍이에요.","저녁엔 육풍이에요.","온도 → 기압 → 바람이에요."],"asset":{"type":"passage","lines":["토요일, 맑은 날 바닷가로 가족 나들이를 갔다.","낮에는 바닷가 바람자루가 육지 쪽으로 펄럭였다.","저녁에는 해변 모닥불 연기가 바다 쪽으로 흘러갔다."],"title":"⑦ 토요일 — 바닷가 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_a#25','sci',5,2,'u2','','g5_2_sci_u2_review_a','unit_review','SC5-2-u2-C21',4,'essay','teacher','하늘반 일지 ②와 ⑥을 보고 화요일과 금요일이 각각 고기압과 저기압 가운데 무엇의 영향이었을지 쓰고, 기상 요소 두 가지 이상을 근거로 들고 그날 생활 안내를 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u2-C21","difficulty":4,"kind":"essay","stem":"하늘반 일지 ②와 ⑥을 보고 화요일과 금요일이 각각 고기압과 저기압 가운데 무엇의 영향이었을지 쓰고, 기상 요소 두 가지 이상을 근거로 들고 그날 생활 안내를 하나씩 쓰세요.","answer_guide":{"answer":"예: 화요일은 저기압, 금요일은 고기압의 영향이었을 것이다. 화요일은 습도 85 %로 높고 구름이 많으며 비가 8 mm 왔고, 금요일은 습도 45 %로 낮고 구름이 조금이며 비가 오지 않았다. 화요일에는 우산을 챙기고 실내 활동을, 금요일에는 빨래나 소풍을 권한다.","scoring_points":["두 날의 기압을 바르게 썼는가","기상 요소 두 가지 이상을 근거로 들었는가","날씨에 맞는 생활 안내를 썼는가"]},"explanation":["화요일은 흐려요.","금요일은 맑아요.","안내를 붙여요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#1','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C1',1,'ox','auto','하늘반 일지 ①에서 점심시간 놀이 장소가 바뀐 것은 날씨 때문이에요.',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"ox","stem":"하늘반 일지 ①에서 점심시간 놀이 장소가 바뀐 것은 날씨 때문이에요.","answer":"O","reason_options":[{"t":"비가 와서 운동장 대신 강당에서 놀았기 때문에","correct":true},{"t":"놀이 장소는 날씨와 상관없이 정해지기 때문에","mis":"SC5-2-u2-X01"}],"mis":"SC5-2-u2-X01","explanation":["비가 왔어요.","강당으로 옮겼어요.","날씨 때문이에요."],"asset":{"type":"passage","lines":["월요일 아침, 비가 내려 친구들이 우산을 쓰고 장화를 신고 왔다.","점심시간에는 운동장 대신 강당에서 놀았다.","하교할 때 빨래를 밖에 널어 둔 집이 있는지 걱정하는 친구도 있었다."],"title":"① 월요일 — 비 오는 날의 학교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#2','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C2',1,'sa','auto','하늘반 일지 ②에서 「8 mm」로 적힌 기상 요소는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"sa","stem":"하늘반 일지 ②에서 「8 mm」로 적힌 기상 요소는 무엇인가요? 세 글자로 쓰세요.","answer":["강수량"],"explanation":["비가 내린 정도예요.","mm로 나타내요.","강수량이에요."],"asset":{"type":"passage","lines":["화요일 우리 지역 — 기온 12 °C · 습도 85 % · 구름 많음 · 강수량 8 mm","운동장 깃발은 남쪽을 향해 펄럭였다.","얼굴에 바람이 닿은 쪽은 북쪽이었다.","모둠마다 날씨누리에서 우리 지역 날씨를 찾아 적었다."],"title":"② 화요일 — 기상 요소 기록"},"mis":"SC5-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#3','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C4',1,'ox','auto','풍향은 바람이 불어오는 방향이에요.',ARRAY['SC5-2-u2-X07']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C4","difficulty":1,"kind":"ox","stem":"풍향은 바람이 불어오는 방향이에요.","answer":"O","reason_options":[{"t":"북쪽에서 불어오는 바람을 북풍이라고 하기 때문에","correct":true},{"t":"바람이 불어 가는 쪽으로 이름을 붙이기 때문에","mis":"SC5-2-u2-X07"}],"mis":"SC5-2-u2-X07","explanation":["불어오는 쪽이에요.","북쪽에서 오면 북풍이에요.","풍향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#4','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C9',1,'mc','auto','하늘반 일지 ④에서 강가에 낮게 깔린 뿌연 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X16','SC5-2-u2-X15']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C9","difficulty":1,"kind":"mc","stem":"하늘반 일지 ④에서 강가에 낮게 깔린 뿌연 것은 어느 것인가요?","options":[{"t":"안개","correct":true},{"t":"이슬","mis":"SC5-2-u2-X17"},{"t":"구름","mis":"SC5-2-u2-X16"},{"t":"연기","mis":"SC5-2-u2-X15"}],"explanation":["땅 가까이 떠 있어요.","뿌옇게 보여요.","안개예요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#5','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C10',1,'mc','auto','이슬·안개·구름의 공통점은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C10","difficulty":1,"kind":"mc","stem":"이슬·안개·구름의 공통점은 어느 것인가요?","options":[{"t":"공기 중의 수증기가 응결해 나타난다","correct":true},{"t":"모두 높은 하늘에 떠 있다","mis":"SC5-2-u2-X17"},{"t":"모두 땅속에서 솟아난다","mis":"SC5-2-u2-X18"},{"t":"모두 물체 표면에 맺힌다","mis":"SC5-2-u2-X17"}],"explanation":["셋 다 물방울이에요.","수증기가 응결했어요.","공통점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#6','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C11',1,'sa','auto','일정한 넓이에 작용하는 공기의 무게를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"sa","stem":"일정한 넓이에 작용하는 공기의 무게를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기압"],"explanation":["공기도 무게가 있어요.","누르는 힘이에요.","기압이에요."],"mis":"SC5-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#7','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C15',1,'ox','auto','바람 발생 모형실험에서 향 연기는 차가운 모래 쪽에서 따뜻한 물 쪽으로 움직였어요.',ARRAY['SC5-2-u2-X25']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C15","difficulty":1,"kind":"ox","stem":"바람 발생 모형실험에서 향 연기는 차가운 모래 쪽에서 따뜻한 물 쪽으로 움직였어요.","answer":"O","reason_options":[{"t":"차가운 모래 쪽이 고기압, 따뜻한 물 쪽이 저기압이기 때문에","correct":true},{"t":"따뜻한 물 쪽이 고기압이기 때문에","mis":"SC5-2-u2-X25"}],"mis":"SC5-2-u2-X25","explanation":["모래 쪽이 고기압이에요.","물 쪽이 저기압이에요.","고 → 저로 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#8','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C19',1,'mc','auto','하늘반 일지 ⑧에서 바다 위에서 날씨를 재는 장비는 어느 것인가요?',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑧에서 바다 위에서 날씨를 재는 장비는 어느 것인가요?","options":[{"t":"부표","correct":true},{"t":"기상 위성","mis":"SC5-2-u2-X33"},{"t":"레윈존데","mis":"SC5-2-u2-X33"},{"t":"기상 레이더","mis":"SC5-2-u2-X33"}],"explanation":["바다에 떠 있어요.","파도와 바람을 재요.","부표예요."],"asset":{"type":"passage","lines":["일요일, 일주일 기록으로 모둠 날씨 앱 「하늘반 날씨」 화면을 만들었다.","기온은 큰 숫자, 비 올 확률은 그래프, 옷차림 알림을 넣었다.","기상 위성·부표·레윈존데가 잰 자료가 예보가 된다는 것도 적었다."],"title":"⑧ 일요일 — 날씨 앱과 관측 장비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#9','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C3',2,'ox','auto','비 오는 날은 맑은 날보다 습도가 높은 편이에요.',ARRAY['SC5-2-u2-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"ox","stem":"비 오는 날은 맑은 날보다 습도가 높은 편이에요.","answer":"O","reason_options":[{"t":"비 오는 날은 공기 중에 수증기가 많기 때문에","correct":true},{"t":"비 오는 날은 공기가 말라 있기 때문에","mis":"SC5-2-u2-X05"}],"mis":"SC5-2-u2-X05","explanation":["비 오는 날은 습해요.","수증기가 많아요.","습도가 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#10','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C6',2,'ox','auto','하늘반 일지 ③의 하은이 말처럼 예보를 미리 보면 피해를 예방할 수 있어요.',ARRAY['SC5-2-u2-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C6","difficulty":2,"kind":"ox","stem":"하늘반 일지 ③의 하은이 말처럼 예보를 미리 보면 피해를 예방할 수 있어요.","answer":"O","reason_options":[{"t":"날씨에 맞게 미리 대비할 수 있기 때문에","correct":true},{"t":"예보를 보면 날씨가 바뀌기 때문에","mis":"SC5-2-u2-X10"}],"mis":"SC5-2-u2-X10","explanation":["미리 알았어요.","대비했어요.","피해를 막아요."],"asset":{"type":"passage","lines":["수요일 아침, 강한 바람과 비 예보가 나왔다.","교실 창문을 닫고 운동장 체육을 강당 수업으로 바꾸었다.","집에 가서 베란다 화분을 들여놓기로 했다.","하은이는 「예보를 미리 봐서 다행이야」라고 말했다."],"title":"③ 수요일 — 예보와 대처"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#11','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C9',2,'ox','auto','하늘반 일지 ④에서 해가 뜨고 강가의 뿌연 것이 걷힌 것은 기온이 올랐기 때문이에요.',ARRAY['SC5-2-u2-X19']::text[],false,'{"seq":11,"concept":"SC5-2-u2-C9","difficulty":2,"kind":"ox","stem":"하늘반 일지 ④에서 해가 뜨고 강가의 뿌연 것이 걷힌 것은 기온이 올랐기 때문이에요.","answer":"O","reason_options":[{"t":"기온이 오르면 응결해 떠 있던 작은 물방울이 줄어들기 때문에","correct":true},{"t":"기온이 오르면 안개가 더 짙어지기 때문에","mis":"SC5-2-u2-X19"}],"mis":"SC5-2-u2-X19","explanation":["해가 떴어요.","기온이 올라요.","안개가 걷혀요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#12','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C13',2,'mc','auto','하늘반 일지 ⑥의 금요일 날씨로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X23','SC5-2-u2-X05']::text[],false,'{"seq":12,"concept":"SC5-2-u2-C13","difficulty":2,"kind":"mc","stem":"하늘반 일지 ⑥의 금요일 날씨로 알맞은 것은 어느 것인가요?","options":[{"t":"대체로 맑아 빨래나 야외 활동을 하기 좋다","correct":true},{"t":"흐리고 비가 와서 우산이 꼭 필요하다","mis":"SC5-2-u2-X24"},{"t":"고기압이라 항상 구름 한 점 없다","mis":"SC5-2-u2-X23"},{"t":"습도가 높아 곰팡이가 잘 핀다","mis":"SC5-2-u2-X05"}],"explanation":["고기압이 있어요.","구름 조금이에요.","대체로 맑아요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#13','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C14',2,'ox','auto','두 곳의 온도가 다르면 기압 차이가 생겨 바람이 불 수 있어요.',ARRAY['SC5-2-u2-X29']::text[],false,'{"seq":13,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"ox","stem":"두 곳의 온도가 다르면 기압 차이가 생겨 바람이 불 수 있어요.","answer":"O","reason_options":[{"t":"온도 차이가 기압 차이를 만들고 공기가 이동하기 때문에","correct":true},{"t":"온도와 바람은 아무 상관이 없기 때문에","mis":"SC5-2-u2-X29"}],"mis":"SC5-2-u2-X29","explanation":["온도가 달라요.","기압 차이가 생겨요.","바람이 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#14','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C16',2,'mc','auto','하늘반 일지 ⑦에서 저녁 모닥불 연기가 바다 쪽으로 흘러간 까닭은 어느 것인가요?',ARRAY['SC5-2-u2-X28','SC5-2-u2-X29','SC5-2-u2-X25']::text[],false,'{"seq":14,"concept":"SC5-2-u2-C16","difficulty":2,"kind":"mc","stem":"하늘반 일지 ⑦에서 저녁 모닥불 연기가 바다 쪽으로 흘러간 까닭은 어느 것인가요?","options":[{"t":"육지가 빨리 식어 고기압이 되어 육지에서 바다로 육풍이 불었다","correct":true},{"t":"바다가 빨리 식어 고기압이 되었다","mis":"SC5-2-u2-X28"},{"t":"연기는 늘 바다를 좋아한다","mis":"SC5-2-u2-X29"},{"t":"따뜻한 육지 쪽 기압이 높아졌다","mis":"SC5-2-u2-X25"}],"explanation":["밤엔 육지가 차가워요.","육지 위가 고기압이에요.","육풍이에요."],"asset":{"type":"passage","lines":["토요일, 맑은 날 바닷가로 가족 나들이를 갔다.","낮에는 바닷가 바람자루가 육지 쪽으로 펄럭였다.","저녁에는 해변 모닥불 연기가 바다 쪽으로 흘러갔다."],"title":"⑦ 토요일 — 바닷가 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#15','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C18',2,'mc','auto','날씨 앱 화면을 공유한 뒤 쓰는 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X32','SC5-2-u2-X30']::text[],false,'{"seq":15,"concept":"SC5-2-u2-C18","difficulty":2,"kind":"mc","stem":"날씨 앱 화면을 공유한 뒤 쓰는 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「옷차림 알림이 쓸모 있어요. 습도도 넣으면 더 좋겠어요.」","correct":true},{"t":"「별로예요.」","mis":"SC5-2-u2-X32"},{"t":"「우리가 더 잘했어요 ㅋㅋ」","mis":"SC5-2-u2-X32"},{"t":"「꾸밈만 있으면 돼요.」","mis":"SC5-2-u2-X30"}],"explanation":["잘한 점을 써요.","보완할 점도 써요.","고운 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#16','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C20',2,'ox','auto','일기 예보관은 관측 자료와 실제 상황을 종합해 예보를 발표해요.',ARRAY['SC5-2-u2-X34']::text[],false,'{"seq":16,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"ox","stem":"일기 예보관은 관측 자료와 실제 상황을 종합해 예보를 발표해요.","answer":"O","reason_options":[{"t":"자료를 사람이 판단해야 정확한 예보가 되기 때문에","correct":true},{"t":"예보는 기계가 혼자 발표하기 때문에","mis":"SC5-2-u2-X34"}],"mis":"SC5-2-u2-X34","explanation":["자료를 모아요.","예보관이 판단해요.","예보를 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#17','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C4',3,'error','auto','하늘반 일지 ②를 기록하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X07','SC5-2-u2-X05','SC5-2-u2-X04']::text[],false,'{"seq":17,"concept":"SC5-2-u2-C4","difficulty":3,"kind":"error","stem":"하늘반 일지 ②를 기록하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「깃발이 남쪽을 향했으니 남풍이라고 적자.」","correct":true,"mis_target":"SC5-2-u2-X07"},{"t":"하은 — 「습도가 85 %로 높아.」","mis":"SC5-2-u2-X05"},{"t":"도윤 — 「강수량은 8 mm야.」","mis":"SC5-2-u2-X04"}],"explanation":["바람은 북쪽에서 왔어요.","불어오는 쪽이 풍향이에요.","시우의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["화요일 우리 지역 — 기온 12 °C · 습도 85 % · 구름 많음 · 강수량 8 mm","운동장 깃발은 남쪽을 향해 펄럭였다.","얼굴에 바람이 닿은 쪽은 북쪽이었다.","모둠마다 날씨누리에서 우리 지역 날씨를 찾아 적었다."],"title":"② 화요일 — 기상 요소 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#18','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C8',3,'ox','auto','추운 날 바깥에서 따뜻한 교실에 들어왔을 때 안경이 흐려지는 것은 이슬이 생기는 과정과 같아요.',ARRAY['SC5-2-u2-X13']::text[],false,'{"seq":18,"concept":"SC5-2-u2-C8","difficulty":3,"kind":"ox","stem":"추운 날 바깥에서 따뜻한 교실에 들어왔을 때 안경이 흐려지는 것은 이슬이 생기는 과정과 같아요.","answer":"O","reason_options":[{"t":"차가워진 안경 표면에 교실 공기 중의 수증기가 응결하기 때문에","correct":true},{"t":"안경 속에서 물이 스며 나오기 때문에","mis":"SC5-2-u2-X13"}],"mis":"SC5-2-u2-X13","explanation":["안경이 차가워요.","수증기가 응결해요.","표면에 맺혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#19','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C13',3,'error','auto','하늘반 일지 ⑥을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X23','SC5-2-u2-X24','SC5-2-u2-X05']::text[],false,'{"seq":19,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"error","stem":"하늘반 일지 ⑥을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「고기압이니까 이번 주 내내 절대 비가 오지 않아.」","correct":true,"mis_target":"SC5-2-u2-X23"},{"t":"예린 — 「구름이 적어 소풍 가기 좋겠어.」","mis":"SC5-2-u2-X24"},{"t":"은우 — 「습도가 45 %로 낮은 편이야.」","mis":"SC5-2-u2-X05"}],"explanation":["대체로 맑아요.","절대는 아니에요.","지호의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#20','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C15',3,'error','auto','바람 발생 모형실험 계획을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X27']::text[],false,'{"seq":20,"concept":"SC5-2-u2-C15","difficulty":3,"kind":"error","stem":"바람 발생 모형실험 계획을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「두 그릇 온도를 똑같이 맞춰야 연기가 잘 움직여.」","correct":true,"mis_target":"SC5-2-u2-X27"},{"t":"도윤 — 「두 그릇 온도 차가 클수록 방향이 뚜렷해.」","mis":"SC5-2-u2-X27"},{"t":"하린 — 「다 쓴 향은 모래 상자에서 꺼.」","mis":"SC5-2-u2-X27"}],"explanation":["온도 차가 필요해요.","차가 클수록 뚜렷해요.","예린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#21','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C7',3,'mc','auto','하늘반 일지 ①을 네 컷 만화로 그릴 때 날씨와 생활이 가장 잘 드러나는 계획은 어느 것인가요?',ARRAY['SC5-2-u2-X12','SC5-2-u2-X02']::text[],false,'{"seq":21,"concept":"SC5-2-u2-C7","difficulty":3,"kind":"mc","stem":"하늘반 일지 ①을 네 컷 만화로 그릴 때 날씨와 생활이 가장 잘 드러나는 계획은 어느 것인가요?","options":[{"t":"우산과 장화를 신고 등교 → 강당에서 놀기 → 빨래 걱정","correct":true},{"t":"교실에서 숙제하기 → 양치하기","mis":"SC5-2-u2-X12"},{"t":"맑은 하늘에서 소풍 가기","mis":"SC5-2-u2-X02"},{"t":"「비」라고 글자만 크게 쓰기","mis":"SC5-2-u2-X12"}],"explanation":["비가 보여야 해요.","생활 모습도 보여요.","날씨와 생활이 함께예요."],"asset":{"type":"passage","lines":["월요일 아침, 비가 내려 친구들이 우산을 쓰고 장화를 신고 왔다.","점심시간에는 운동장 대신 강당에서 놀았다.","하교할 때 빨래를 밖에 널어 둔 집이 있는지 걱정하는 친구도 있었다."],"title":"① 월요일 — 비 오는 날의 학교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#22','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C21',3,'mc','auto','배운 내용을 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X16','SC5-2-u2-X23','SC5-2-u2-X03']::text[],false,'{"seq":22,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"mc","stem":"배운 내용을 바르게 이은 것은 어느 것인가요?","options":[{"t":"수증기가 응결하면 이슬·안개·구름이 생기고, 바람은 고기압에서 저기압으로 분다","correct":true},{"t":"구름은 땅 가까이 생기고 바람은 저기압에서 분다","mis":"SC5-2-u2-X16"},{"t":"고기압은 항상 비가 오고 이슬은 하늘에서 내린다","mis":"SC5-2-u2-X23"},{"t":"기상 요소는 하늘 색깔 하나뿐이다","mis":"SC5-2-u2-X03"}],"explanation":["응결이 공통이에요.","바람은 고 → 저예요.","이어서 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#23','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C9',4,'essay','teacher','하늘반 일지 ⑤의 집기병 실험이 ④의 강가 모습과 어떻게 닮았는지 쓰고, 해가 뜨면 강가의 뿌연 것이 걷히는 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u2-C9","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑤의 집기병 실험이 ④의 강가 모습과 어떻게 닮았는지 쓰고, 해가 뜨면 강가의 뿌연 것이 걷히는 까닭을 쓰세요.","answer_guide":{"answer":"예: 집기병 안의 수증기가 얼음 때문에 차가워져 응결해 작은 물방울로 떠 있어 뿌옇게 된 것처럼, 강가에서도 새벽에 차가워진 공기 속 수증기가 응결해 지표면 가까이에 떠 있는 안개가 생겼다. 해가 떠 기온이 오르면 떠 있던 작은 물방울이 줄어 안개가 걷힌다.","scoring_points":["두 현상이 닮은 점(차가워져 응결)을 썼는가","지표면 가까이에 떠 있음을 썼는가","기온이 오르면 걷히는 까닭을 썼는가"]},"explanation":["둘 다 안개예요.","차가워져 응결해요.","기온이 오르면 걷혀요."],"asset":{"type":"passage","lines":["목요일 오후, 차가운 캔 겉면을 닦고 두었더니 물방울이 맺혔다.","집기병에 얼음 지퍼 백을 얹었더니 안이 뿌옇게 흐려졌다.","두 실험을 새벽에 본 것과 견주어 실험관찰에 적었다."],"title":"⑤ 목요일 오후 — 두 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#24','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C14',4,'essay','teacher','한겨울 따뜻한 방의 창문을 열었을 때 찬 바깥 공기가 방 안으로 들어오는 까닭을 기압과 바람으로 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u2-C14","difficulty":4,"kind":"essay","stem":"한겨울 따뜻한 방의 창문을 열었을 때 찬 바깥 공기가 방 안으로 들어오는 까닭을 기압과 바람으로 설명하세요.","answer_guide":{"answer":"예: 바깥 공기는 차가워 무겁고 기압이 높아 고기압이 되고, 방 안 공기는 따뜻해 가볍고 기압이 낮아 저기압이 된다. 공기는 고기압에서 저기압으로 이동하므로 찬 바깥 공기가 방 안으로 들어온다.","scoring_points":["바깥과 방의 기압을 바르게 썼는가","온도와 기압을 이었는가","공기가 이동하는 방향을 썼는가"]},"explanation":["바깥이 차가워요.","바깥이 고기압이에요.","방으로 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_b#25','sci',5,2,'u2','','g5_2_sci_u2_review_b','unit_review','SC5-2-u2-C17',4,'essay','teacher','하늘반 일지 ⑧의 「하늘반 날씨」 화면을 더 좋게 만들 방법 두 가지를 기상 요소와 생활 정보로 제안하고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u2-C17","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑧의 「하늘반 날씨」 화면을 더 좋게 만들 방법 두 가지를 기상 요소와 생활 정보로 제안하고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 습도와 바람(풍향)을 아이콘으로 더하면 날씨를 더 자세히 알 수 있다. 저기압이 다가오는 날에는 「우산 챙기세요」 알림을 맨 위에 크게 띄우면 사람들이 바로 대비할 수 있다. 화면을 쓰는 사람이 날씨 정보를 정확하고 쉽게 알게 하는 것이 목적이기 때문이다.","scoring_points":["기상 요소를 더하는 제안을 했는가","생활 정보 제안을 했는가","날씨 앱의 목적과 이어 까닭을 썼는가"]},"explanation":["기상 요소를 더해요.","생활 알림을 더해요.","정보가 먼저예요."],"asset":{"type":"passage","lines":["일요일, 일주일 기록으로 모둠 날씨 앱 「하늘반 날씨」 화면을 만들었다.","기온은 큰 숫자, 비 올 확률은 그래프, 옷차림 알림을 넣었다.","기상 위성·부표·레윈존데가 잰 자료가 예보가 된다는 것도 적었다."],"title":"⑧ 일요일 — 날씨 앱과 관측 장비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#1','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C1',1,'mc','auto','하늘반 친구들이 한 일 가운데 날씨와 상관없이 하는 일은 어느 것인가요?',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"mc","stem":"하늘반 친구들이 한 일 가운데 날씨와 상관없이 하는 일은 어느 것인가요?","options":[{"t":"손을 씻는다","correct":true},{"t":"더운 날 그늘에서 쉰다","mis":"SC5-2-u2-X01"},{"t":"비 오는 날 비옷을 입는다","mis":"SC5-2-u2-X01"},{"t":"추운 날 장갑을 낀다","mis":"SC5-2-u2-X01"}],"explanation":["손 씻기는 늘 해요.","날씨와 상관없어요.","나머지는 날씨 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#2','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C2',1,'mc','auto','기상 요소만 모은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X03']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"mc","stem":"기상 요소만 모은 것은 어느 것인가요?","options":[{"t":"기온 · 습도 · 바람","correct":true},{"t":"기온 · 하늘의 색깔 · 바람","mis":"SC5-2-u2-X03"},{"t":"습도 · 구름의 모양 · 기분","mis":"SC5-2-u2-X03"},{"t":"무지개 · 강수량 · 습도","mis":"SC5-2-u2-X03"}],"explanation":["기상 요소는 잴 수 있어요.","기온·습도·바람이에요.","색깔은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#3','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C4',1,'mc','auto','날씨를 기상 요소로 나타내면 좋은 점은 어느 것인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X08']::text[],false,'{"seq":3,"concept":"SC5-2-u2-C4","difficulty":1,"kind":"mc","stem":"날씨를 기상 요소로 나타내면 좋은 점은 어느 것인가요?","options":[{"t":"날씨를 구체적으로 알고 견주기 쉽다","correct":true},{"t":"날씨를 바꿀 수 있다","mis":"SC5-2-u2-X10"},{"t":"날씨가 예뻐진다","mis":"SC5-2-u2-X08"},{"t":"맑음·흐림만 알면 된다","mis":"SC5-2-u2-X08"}],"explanation":["숫자로 나타내요.","구체적이에요.","견주기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#4','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C8',1,'ox','auto','하늘반 일지 ⑤에서 캔 겉면의 물방울은 캔 속 음료예요.',ARRAY['SC5-2-u2-X13']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C8","difficulty":1,"kind":"ox","stem":"하늘반 일지 ⑤에서 캔 겉면의 물방울은 캔 속 음료예요.","answer":"X","reason_options":[{"t":"캔 주변 공기 중의 수증기가 차가운 겉면에서 응결한 것이기 때문에","correct":true},{"t":"캔에서 음료가 새어 나왔기 때문에","mis":"SC5-2-u2-X13"}],"mis":"SC5-2-u2-X13","explanation":["캔은 새지 않아요.","주변 수증기가 응결해요.","이슬과 같아요."],"asset":{"type":"passage","lines":["목요일 오후, 차가운 캔 겉면을 닦고 두었더니 물방울이 맺혔다.","집기병에 얼음 지퍼 백을 얹었더니 안이 뿌옇게 흐려졌다.","두 실험을 새벽에 본 것과 견주어 실험관찰에 적었다."],"title":"⑤ 목요일 오후 — 두 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#5','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C10',1,'ox','auto','안개와 구름은 물방울이 떠 있는 높이가 달라요.',ARRAY['SC5-2-u2-X16']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C10","difficulty":1,"kind":"ox","stem":"안개와 구름은 물방울이 떠 있는 높이가 달라요.","answer":"O","reason_options":[{"t":"안개는 지표면 가까이, 구름은 높은 곳에 떠 있기 때문에","correct":true},{"t":"안개와 구름은 같은 높이에 떠 있기 때문에","mis":"SC5-2-u2-X16"}],"mis":"SC5-2-u2-X16","explanation":["안개는 땅 가까이예요.","구름은 높은 곳이에요.","높이가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#6','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C11',1,'ox','auto','주변보다 기압이 낮은 곳을 저기압이라고 해요.',ARRAY['SC5-2-u2-X20']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"ox","stem":"주변보다 기압이 낮은 곳을 저기압이라고 해요.","answer":"O","reason_options":[{"t":"저기압은 주변보다 상대적으로 기압이 낮은 곳이기 때문에","correct":true},{"t":"저기압은 주변보다 기압이 높은 곳이기 때문에","mis":"SC5-2-u2-X20"}],"mis":"SC5-2-u2-X20","explanation":["주변과 견줘요.","낮으면 저기압이에요.","높으면 고기압이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#7','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C15',1,'mc','auto','바람 발생 모형실험에서 향 연기를 넣는 까닭은 어느 것인가요?',ARRAY['SC5-2-u2-X29','SC5-2-u2-X27','SC5-2-u2-X15']::text[],false,'{"seq":7,"concept":"SC5-2-u2-C15","difficulty":1,"kind":"mc","stem":"바람 발생 모형실험에서 향 연기를 넣는 까닭은 어느 것인가요?","options":[{"t":"공기의 움직임을 눈으로 보려고","correct":true},{"t":"향 연기가 바람을 만들려고","mis":"SC5-2-u2-X29"},{"t":"그릇을 데우려고","mis":"SC5-2-u2-X27"},{"t":"구름을 만들려고","mis":"SC5-2-u2-X15"}],"explanation":["공기는 안 보여요.","연기가 함께 움직여요.","움직임이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#8','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C19',1,'ox','auto','레윈존데는 풍선에 달아 하늘 높이 올려 보내는 관측 장비예요.',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"ox","stem":"레윈존데는 풍선에 달아 하늘 높이 올려 보내는 관측 장비예요.","answer":"O","reason_options":[{"t":"높은 하늘의 기상 요소를 재기 위해서이기 때문에","correct":true},{"t":"레윈존데는 바다 위에 떠서 파도를 재기 때문에","mis":"SC5-2-u2-X33"}],"mis":"SC5-2-u2-X33","explanation":["풍선에 달아요.","하늘 높이 올라가요.","높은 곳을 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#9','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C3',2,'mc','auto','하늘반 일지 ②의 화요일과 ⑥의 금요일을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-2-u2-X05','SC5-2-u2-X06']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"mc","stem":"하늘반 일지 ②의 화요일과 ⑥의 금요일을 바르게 견준 것은 어느 것인가요?","options":[{"t":"화요일은 금요일보다 습도가 높고 구름이 많았다","correct":true},{"t":"금요일이 화요일보다 비가 더 많이 왔다","mis":"SC5-2-u2-X05"},{"t":"두 날은 기온만 달랐다","mis":"SC5-2-u2-X06"},{"t":"금요일이 화요일보다 습도가 높았다","mis":"SC5-2-u2-X05"}],"explanation":["화요일 습도 85 %예요.","금요일은 45 %예요.","구름도 화요일이 많아요."],"asset":{"type":"passage","lines":["금요일 기상 위성 사진 — 우리나라 위에 구름이 거의 없었다.","예보 지도 — 우리나라 쪽에 고기압이 표시되었다.","금요일 우리 지역 — 기온 22 °C · 습도 45 % · 구름 조금 · 강수량 0 mm"],"title":"⑥ 금요일 — 위성 사진과 기압"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#10','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C5',2,'match','auto','날씨와 알맞은 대처를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u2-C5","difficulty":2,"kind":"match","stem":"날씨와 알맞은 대처를 이으세요.","pairs":[{"l":"습한 날","r":"제습기를 켠다"},{"l":"폭염","r":"야외 활동을 줄이고 물을 마신다"},{"l":"강한 바람","r":"화분을 들여놓는다"}],"mis":"SC5-2-u2-X09","explanation":["습하면 제습기예요.","폭염엔 쉬어요.","바람엔 들여놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#11','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C10',2,'error','auto','하늘반 일지 ④를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X16','SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":11,"concept":"SC5-2-u2-C10","difficulty":2,"kind":"error","stem":"하늘반 일지 ④를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「강가의 뿌연 것과 산 위 하얀 것은 같은 높이에 있어.」","correct":true,"mis_target":"SC5-2-u2-X16"},{"t":"서아 — 「풀잎 물방울은 표면에 맺힌 이슬이야.」","mis":"SC5-2-u2-X17"},{"t":"하린 — 「셋 다 수증기가 응결한 거야.」","mis":"SC5-2-u2-X18"}],"explanation":["안개는 땅 가까이예요.","구름은 높은 곳이에요.","준서의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["목요일 새벽, 학교 앞 강가에 뿌연 것이 낮게 깔려 있었다.","화단 풀잎과 거미줄에는 물방울이 맺혀 있었다.","멀리 산 위 하늘에는 하얀 것이 떠 있었다.","해가 뜨고 기온이 오르자 강가의 뿌연 것은 걷혔다."],"title":"④ 목요일 새벽 — 물방울 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#12','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C12',2,'ox','auto','기상 위성 사진에서 구름이 많이 낀 곳은 저기압이 있는 경우가 많아요.',ARRAY['SC5-2-u2-X22']::text[],false,'{"seq":12,"concept":"SC5-2-u2-C12","difficulty":2,"kind":"ox","stem":"기상 위성 사진에서 구름이 많이 낀 곳은 저기압이 있는 경우가 많아요.","answer":"O","reason_options":[{"t":"저기압이 있는 곳은 대체로 구름이 많기 때문에","correct":true},{"t":"구름이 많은 곳은 언제나 고기압이기 때문에","mis":"SC5-2-u2-X22"}],"mis":"SC5-2-u2-X22","explanation":["구름이 많아요.","저기압인 경우가 많아요.","비가 올 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#13','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C14',2,'mc','auto','온도·기압·바람을 바른 순서로 이은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X29']::text[],false,'{"seq":13,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"mc","stem":"온도·기압·바람을 바른 순서로 이은 것은 어느 것인가요?","options":[{"t":"온도 차이 → 기압 차이 → 바람","correct":true},{"t":"바람 → 기압 차이 → 온도 차이","mis":"SC5-2-u2-X29"},{"t":"기압 차이 → 온도 차이 → 바람","mis":"SC5-2-u2-X29"},{"t":"셋은 서로 상관없다","mis":"SC5-2-u2-X29"}],"explanation":["먼저 온도가 달라요.","기압 차이가 생겨요.","바람이 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#14','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C16',2,'ox','auto','맑은 날 낮에 바닷가에서는 바다에서 육지로 바람이 불어요.',ARRAY['SC5-2-u2-X28']::text[],false,'{"seq":14,"concept":"SC5-2-u2-C16","difficulty":2,"kind":"ox","stem":"맑은 날 낮에 바닷가에서는 바다에서 육지로 바람이 불어요.","answer":"O","reason_options":[{"t":"낮에 육지가 더 따뜻해 육지 위가 저기압이 되기 때문에","correct":true},{"t":"낮에 바다가 더 따뜻해 바다 위가 저기압이 되기 때문에","mis":"SC5-2-u2-X28"}],"mis":"SC5-2-u2-X28","explanation":["낮엔 육지가 따뜻해요.","육지 위는 저기압이에요.","해풍이 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#15','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C17',2,'ox','auto','날씨 앱 화면에 넣은 그림은 출처를 밝히고 개인 정보는 넣지 않아요.',ARRAY['SC5-2-u2-X31']::text[],false,'{"seq":15,"concept":"SC5-2-u2-C17","difficulty":2,"kind":"ox","stem":"날씨 앱 화면에 넣은 그림은 출처를 밝히고 개인 정보는 넣지 않아요.","answer":"O","reason_options":[{"t":"남의 그림에도 주인이 있고 개인 정보는 지켜야 하기 때문에","correct":true},{"t":"그림은 누구 것이든 마음대로 써도 되기 때문에","mis":"SC5-2-u2-X31"}],"mis":"SC5-2-u2-X31","explanation":["그림 출처를 밝혀요.","개인 정보는 빼요.","바르게 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#16','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C20',2,'mc','auto','예보를 만들 때 다른 나라의 관측 자료도 모으는 까닭은 어느 것인가요?',ARRAY['SC5-2-u2-X34','SC5-2-u2-X10','SC5-2-u2-X01']::text[],false,'{"seq":16,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"mc","stem":"예보를 만들 때 다른 나라의 관측 자료도 모으는 까닭은 어느 것인가요?","options":[{"t":"구름과 공기는 나라를 넘어 움직이기 때문","correct":true},{"t":"우리나라 자료만 있으면 충분하기 때문","mis":"SC5-2-u2-X34"},{"t":"날씨를 바꾸기 위해서","mis":"SC5-2-u2-X10"},{"t":"다른 나라 날씨는 우리와 상관없기 때문","mis":"SC5-2-u2-X01"}],"explanation":["구름은 움직여요.","나라를 넘어요.","전 세계 자료를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#17','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C4',3,'mc','auto','「오늘은 좀 춥고 흐리다」를 기상 요소로 가장 잘 고친 것은 어느 것인가요?',ARRAY['SC5-2-u2-X08','SC5-2-u2-X03']::text[],false,'{"seq":17,"concept":"SC5-2-u2-C4","difficulty":3,"kind":"mc","stem":"「오늘은 좀 춥고 흐리다」를 기상 요소로 가장 잘 고친 것은 어느 것인가요?","options":[{"t":"기온 8 °C, 습도 70 %, 구름 많음, 비는 오지 않음","correct":true},{"t":"하늘이 회색이고 기분이 안 좋다","mis":"SC5-2-u2-X08"},{"t":"날씨가 별로다","mis":"SC5-2-u2-X08"},{"t":"하늘 색깔이 어둡다","mis":"SC5-2-u2-X03"}],"explanation":["기온으로 춥다를 나타내요.","구름으로 흐림을 나타내요.","구체적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#18','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C8',3,'mc','auto','이슬이 잘 생기는 때로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X19','SC5-2-u2-X14']::text[],false,'{"seq":18,"concept":"SC5-2-u2-C8","difficulty":3,"kind":"mc","stem":"이슬이 잘 생기는 때로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기온이 낮아 물체 표면이 차가워진 맑은 새벽","correct":true},{"t":"기온이 가장 높은 한낮","mis":"SC5-2-u2-X19"},{"t":"비가 쏟아지는 오후","mis":"SC5-2-u2-X14"},{"t":"땅이 뜨겁게 데워진 때","mis":"SC5-2-u2-X19"}],"explanation":["표면이 차가워야 해요.","새벽이 차가워요.","이슬이 맺혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#19','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C13',3,'mc','auto','「저기압」의 날씨를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X23','SC5-2-u2-X24','SC5-2-u2-X35']::text[],false,'{"seq":19,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"mc","stem":"「저기압」의 날씨를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"대체로 구름이 많고 비나 눈이 올 수 있다","correct":true},{"t":"언제나 반드시 비가 온다","mis":"SC5-2-u2-X23"},{"t":"대체로 맑고 건조하다","mis":"SC5-2-u2-X24"},{"t":"기압과 날씨는 상관없다","mis":"SC5-2-u2-X35"}],"explanation":["대체로 흐려요.","비나 눈이 올 수 있어요.","항상은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#20','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C15',3,'ox','auto','두 그릇이 모두 같은 온도의 따뜻한 물이면 향 연기가 한쪽으로 뚜렷하게 움직이지 않아요.',ARRAY['SC5-2-u2-X29']::text[],false,'{"seq":20,"concept":"SC5-2-u2-C15","difficulty":3,"kind":"ox","stem":"두 그릇이 모두 같은 온도의 따뜻한 물이면 향 연기가 한쪽으로 뚜렷하게 움직이지 않아요.","answer":"O","reason_options":[{"t":"온도 차이가 없으면 기압 차이도 생기지 않기 때문에","correct":true},{"t":"따뜻한 물만 있으면 바람이 더 세지기 때문에","mis":"SC5-2-u2-X29"}],"mis":"SC5-2-u2-X29","explanation":["온도가 같아요.","기압 차이가 없어요.","바람이 안 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#21','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C6',3,'ox','auto','날씨 정보를 미리 알면 날씨를 바꿀 수는 없지만 계획을 바꿀 수 있어요.',ARRAY['SC5-2-u2-X10']::text[],false,'{"seq":21,"concept":"SC5-2-u2-C6","difficulty":3,"kind":"ox","stem":"날씨 정보를 미리 알면 날씨를 바꿀 수는 없지만 계획을 바꿀 수 있어요.","answer":"O","reason_options":[{"t":"날씨에 맞게 대비하고 계획을 세울 수 있기 때문에","correct":true},{"t":"예보를 알면 날씨가 예보대로 바뀌기 때문에","mis":"SC5-2-u2-X10"}],"mis":"SC5-2-u2-X10","explanation":["날씨는 못 바꿔요.","계획은 바꿀 수 있어요.","대비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#22','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C21',3,'error','auto','일주일 일지를 정리하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X35','SC5-2-u2-X05','SC5-2-u2-X28']::text[],false,'{"seq":22,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"error","stem":"일주일 일지를 정리하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「구름이 많은 날은 고기압이라 빨래를 널기 좋아.」","correct":true,"mis_target":"SC5-2-u2-X35"},{"t":"유나 — 「습도가 높고 구름이 많은 날은 비가 올 수 있어.」","mis":"SC5-2-u2-X05"},{"t":"지호 — 「맑은 날 낮 바닷가엔 해풍이 불어.」","mis":"SC5-2-u2-X28"}],"explanation":["구름이 많으면 저기압이에요.","빨래는 맑은 날이에요.","은우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#23','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C8',4,'essay','teacher','차가운 캔 겉면의 물방울이 캔 속 음료가 아니라는 것을 확인하는 방법을 쓰고, 물방울이 어디에서 왔는지 이슬과 이어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u2-C8","difficulty":4,"kind":"essay","stem":"차가운 캔 겉면의 물방울이 캔 속 음료가 아니라는 것을 확인하는 방법을 쓰고, 물방울이 어디에서 왔는지 이슬과 이어 설명하세요.","answer_guide":{"answer":"예: 겉면의 물방울과 캔 속 음료를 흰 종이에 각각 묻혀 색깔을 견주면, 물방울은 투명하고 음료는 색이 있어 서로 다르다는 것을 알 수 있다. 물방울은 캔 주변 공기 중의 수증기가 차가운 캔 표면에 닿아 응결한 것으로, 풀잎에 이슬이 맺히는 것과 같은 과정이다.","scoring_points":["확인 방법을 썼는가","물방울이 공기 중 수증기에서 왔다고 썼는가","이슬과 같은 과정임을 썼는가"]},"explanation":["색을 견줘요.","수증기가 응결해요.","이슬과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#24','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C15',4,'essay','teacher','바람 발생 모형실험에서 모래 대신 얼음물을 쓰면 결과가 어떻게 될지 예상하고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u2-C15","difficulty":4,"kind":"essay","stem":"바람 발생 모형실험에서 모래 대신 얼음물을 쓰면 결과가 어떻게 될지 예상하고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 향 연기는 얼음물 쪽에서 따뜻한 물 쪽으로 움직일 것이다. 얼음물 쪽은 온도가 낮아 공기가 무겁고 고기압이 되며, 따뜻한 물 쪽은 저기압이 되어 공기가 고기압에서 저기압으로 이동하기 때문이다. 두 그릇의 온도 차가 더 커져 방향이 더 뚜렷할 것이다.","scoring_points":["연기의 방향을 바르게 예상했는가","온도와 기압을 이어 까닭을 썼는가","고기압에서 저기압으로 이동함을 썼는가"]},"explanation":["얼음물이 차가워요.","고기압이 돼요.","물 쪽으로 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_c#25','sci',5,2,'u2','','g5_2_sci_u2_review_c','unit_review','SC5-2-u2-C20',4,'essay','teacher','하늘반 일지 ⑧의 관측 장비들이 잰 자료가 우리가 보는 일기 예보가 되기까지의 과정을 쓰고, 일기 예보관이 꼭 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u2-C20","difficulty":4,"kind":"essay","stem":"하늘반 일지 ⑧의 관측 장비들이 잰 자료가 우리가 보는 일기 예보가 되기까지의 과정을 쓰고, 일기 예보관이 꼭 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 기상 위성·부표·레윈존데 같은 장비가 땅·바다·하늘·우주에서 기상 요소를 재고, 다른 나라 자료도 함께 모은다. 슈퍼컴퓨터가 자료를 분석하고, 일기 예보관이 자료와 실제 상황을 종합해 판단해 예보를 발표한다. 기계의 분석만으로는 실제 상황을 다 담지 못해 사람의 판단이 필요하다.","scoring_points":["관측 단계를 썼는가","분석과 판단 단계를 썼는가","예보관이 필요한 까닭을 썼는가"]},"explanation":["관측해요.","분석해요.","예보관이 판단해요."],"asset":{"type":"passage","lines":["일요일, 일주일 기록으로 모둠 날씨 앱 「하늘반 날씨」 화면을 만들었다.","기온은 큰 숫자, 비 올 확률은 그래프, 옷차림 알림을 넣었다.","기상 위성·부표·레윈존데가 잰 자료가 예보가 된다는 것도 적었다."],"title":"⑧ 일요일 — 날씨 앱과 관측 장비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#1','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C1',1,'mc','auto','하늘반 일지 ①에서 걱정한 「밖에 널어 둔 빨래」는 어떻게 하는 것이 알맞나요?',ARRAY['SC5-2-u2-X09','SC5-2-u2-X01','SC5-2-u2-X10']::text[],false,'{"seq":1,"concept":"SC5-2-u2-C1","difficulty":1,"kind":"mc","stem":"하늘반 일지 ①에서 걱정한 「밖에 널어 둔 빨래」는 어떻게 하는 것이 알맞나요?","options":[{"t":"비가 오니 안으로 들여놓는다","correct":true},{"t":"비가 오니 더 오래 널어 둔다","mis":"SC5-2-u2-X09"},{"t":"날씨와 상관없으니 그냥 둔다","mis":"SC5-2-u2-X01"},{"t":"비를 멈추게 한다","mis":"SC5-2-u2-X10"}],"explanation":["비가 오면 젖어요.","안으로 들여요.","날씨에 맞게 해요."],"asset":{"type":"passage","lines":["월요일 아침, 비가 내려 친구들이 우산을 쓰고 장화를 신고 왔다.","점심시간에는 운동장 대신 강당에서 놀았다.","하교할 때 빨래를 밖에 널어 둔 집이 있는지 걱정하는 친구도 있었다."],"title":"① 월요일 — 비 오는 날의 학교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#2','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C2',1,'mc','auto','「기온」이 알려 주는 것은 어느 것인가요?',ARRAY['SC5-2-u2-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u2-C2","difficulty":1,"kind":"mc","stem":"「기온」이 알려 주는 것은 어느 것인가요?","options":[{"t":"공기의 따뜻하고 차가운 정도","correct":true},{"t":"비가 내린 양","mis":"SC5-2-u2-X04"},{"t":"공기 속 수증기의 정도","mis":"SC5-2-u2-X04"},{"t":"하늘을 덮은 구름의 양","mis":"SC5-2-u2-X04"}],"explanation":["온도계로 재요.","덥고 추운 정도예요.","기온이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#3','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C4',1,'sa','auto','남쪽에서 불어오는 바람을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u2-C4","difficulty":1,"kind":"sa","stem":"남쪽에서 불어오는 바람을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["남풍"],"explanation":["불어오는 쪽이 이름이에요.","남쪽에서 와요.","남풍이에요."],"mis":"SC5-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#4','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C9',1,'mc','auto','하늘반 일지 ⑤의 집기병 실험은 어떤 자연 현상과 닮았나요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":4,"concept":"SC5-2-u2-C9","difficulty":1,"kind":"mc","stem":"하늘반 일지 ⑤의 집기병 실험은 어떤 자연 현상과 닮았나요?","options":[{"t":"안개","correct":true},{"t":"이슬","mis":"SC5-2-u2-X17"},{"t":"바람","mis":"SC5-2-u2-X18"},{"t":"무지개","mis":"SC5-2-u2-X18"}],"explanation":["작은 물방울이 떠 있어요.","뿌옇게 보여요.","안개와 닮았어요."],"asset":{"type":"passage","lines":["목요일 오후, 차가운 캔 겉면을 닦고 두었더니 물방울이 맺혔다.","집기병에 얼음 지퍼 백을 얹었더니 안이 뿌옇게 흐려졌다.","두 실험을 새벽에 본 것과 견주어 실험관찰에 적었다."],"title":"⑤ 목요일 오후 — 두 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#5','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C10',1,'mc','auto','차가워진 물체 표면에 맺히는 것은 어느 것인가요?',ARRAY['SC5-2-u2-X17','SC5-2-u2-X18']::text[],false,'{"seq":5,"concept":"SC5-2-u2-C10","difficulty":1,"kind":"mc","stem":"차가워진 물체 표면에 맺히는 것은 어느 것인가요?","options":[{"t":"이슬","correct":true},{"t":"안개","mis":"SC5-2-u2-X17"},{"t":"구름","mis":"SC5-2-u2-X17"},{"t":"바람","mis":"SC5-2-u2-X18"}],"explanation":["표면에 맺혀요.","풀잎·자동차 위예요.","이슬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#6','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C11',1,'mc','auto','고기압과 저기압을 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X21','SC5-2-u2-X06','SC5-2-u2-X03']::text[],false,'{"seq":6,"concept":"SC5-2-u2-C11","difficulty":1,"kind":"mc","stem":"고기압과 저기압을 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"주변과 견주어 기압이 높은지 낮은지로 정한다","correct":true},{"t":"정해진 숫자 하나로 정한다","mis":"SC5-2-u2-X21"},{"t":"기온 하나로 정한다","mis":"SC5-2-u2-X06"},{"t":"하늘 색깔로 정한다","mis":"SC5-2-u2-X03"}],"explanation":["숫자로 외우지 않아요.","주변과 견줘요.","상대적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#7','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C15',1,'sa','auto','두 곳의 기압 차이로 공기가 이동하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-2-u2-C15","difficulty":1,"kind":"sa","stem":"두 곳의 기압 차이로 공기가 이동하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["바람"],"explanation":["기압 차이가 생겨요.","공기가 이동해요.","바람이에요."],"mis":"SC5-2-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#8','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C19',1,'mc','auto','학교에서 기온을 재려면 무엇을 쓰면 되나요?',ARRAY['SC5-2-u2-X04','SC5-2-u2-X33']::text[],false,'{"seq":8,"concept":"SC5-2-u2-C19","difficulty":1,"kind":"mc","stem":"학교에서 기온을 재려면 무엇을 쓰면 되나요?","options":[{"t":"온도계","correct":true},{"t":"바람개비","mis":"SC5-2-u2-X04"},{"t":"빗물 받는 그릇","mis":"SC5-2-u2-X04"},{"t":"나침반","mis":"SC5-2-u2-X33"}],"explanation":["기온은 따뜻하고 차가운 정도예요.","온도계로 재요.","생활에서도 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#9','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C3',2,'mc','auto','여러 날의 기상 자료로 규칙을 찾는 바른 방법은 어느 것인가요?',ARRAY['SC5-2-u2-X06','SC5-2-u2-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u2-C3","difficulty":2,"kind":"mc","stem":"여러 날의 기상 자료로 규칙을 찾는 바른 방법은 어느 것인가요?","options":[{"t":"여러 날을 모아 맑은 날과 비 오는 날의 기상 요소를 견준다","correct":true},{"t":"하루 자료만 보고 규칙을 정한다","mis":"SC5-2-u2-X06"},{"t":"기온 하나만 본다","mis":"SC5-2-u2-X06"},{"t":"비 오는 날은 습도가 낮다고 정한다","mis":"SC5-2-u2-X05"}],"explanation":["여러 날을 모아요.","여러 요소를 봐요.","그래야 규칙이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#10','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C5',2,'mc','auto','날씨가 음식과 생활에 주는 영향을 옳게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u2-X01','SC5-2-u2-X09']::text[],false,'{"seq":10,"concept":"SC5-2-u2-C5","difficulty":2,"kind":"mc","stem":"날씨가 음식과 생활에 주는 영향을 옳게 말한 것은 어느 것인가요?","options":[{"t":"기온과 습도가 높으면 음식이 쉽게 상한다","correct":true},{"t":"날씨는 음식과 상관없다","mis":"SC5-2-u2-X01"},{"t":"습도가 높으면 빨래가 더 잘 마른다","mis":"SC5-2-u2-X09"},{"t":"추운 날엔 얇게 입는다","mis":"SC5-2-u2-X09"}],"explanation":["덥고 습한 날이에요.","곰팡이가 잘 자라요.","음식이 상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#11','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C9',2,'mc','auto','하늘반 일지 ⑤의 집기병이 뿌옇게 흐려진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X15','SC5-2-u2-X13','SC5-2-u2-X19']::text[],false,'{"seq":11,"concept":"SC5-2-u2-C9","difficulty":2,"kind":"mc","stem":"하늘반 일지 ⑤의 집기병이 뿌옇게 흐려진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"집기병 안 수증기가 차가워져 응결해 작은 물방울로 떠 있어서","correct":true},{"t":"향 연기가 가득 차서","mis":"SC5-2-u2-X15"},{"t":"얼음이 녹아 물이 튀어서","mis":"SC5-2-u2-X13"},{"t":"데워져서 물방울이 생겨서","mis":"SC5-2-u2-X19"}],"explanation":["얼음이 차갑게 해요.","수증기가 응결해요.","작은 물방울이 떠 있어요."],"asset":{"type":"passage","lines":["목요일 오후, 차가운 캔 겉면을 닦고 두었더니 물방울이 맺혔다.","집기병에 얼음 지퍼 백을 얹었더니 안이 뿌옇게 흐려졌다.","두 실험을 새벽에 본 것과 견주어 실험관찰에 적었다."],"title":"⑤ 목요일 오후 — 두 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#12','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C13',2,'match','auto','기압과 그때 하기 좋은 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC5-2-u2-C13","difficulty":2,"kind":"match","stem":"기압과 그때 하기 좋은 일을 알맞게 이으세요.","pairs":[{"l":"고기압이 자리 잡은 날","r":"빨래를 밖에 넌다"},{"l":"저기압이 다가오는 날","r":"우산을 챙긴다"}],"mis":"SC5-2-u2-X24","explanation":["고기압은 맑아요.","저기압은 흐려요.","대비가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#13','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C14',2,'error','auto','온도와 기압을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X25','SC5-2-u2-X29']::text[],false,'{"seq":13,"concept":"SC5-2-u2-C14","difficulty":2,"kind":"error","stem":"온도와 기압을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「따뜻한 공기 쪽 기압이 더 높아.」","correct":true,"mis_target":"SC5-2-u2-X25"},{"t":"지호 — 「차가운 공기는 무거워 기압이 높아져.」","mis":"SC5-2-u2-X25"},{"t":"은우 — 「기압 차이가 생기면 공기가 움직여.」","mis":"SC5-2-u2-X29"}],"explanation":["따뜻하면 가벼워요.","기압이 낮아요.","유나의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#14','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C16',2,'sa','auto','맑은 날 밤 바닷가에서 육지에서 바다로 부는 바람을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SC5-2-u2-C16","difficulty":2,"kind":"sa","stem":"맑은 날 밤 바닷가에서 육지에서 바다로 부는 바람을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["육풍"],"explanation":["육지에서 불어요.","밤에 불어요.","육풍이에요."],"mis":"SC5-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#15','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C18',2,'mc','auto','날씨 앱 화면을 만드는 차례로 알맞은 것은 어느 것인가요? (하늘반 일지 ⑧)',ARRAY['SC5-2-u2-X32']::text[],false,'{"seq":15,"concept":"SC5-2-u2-C18","difficulty":2,"kind":"mc","stem":"날씨 앱 화면을 만드는 차례로 알맞은 것은 어느 것인가요? (하늘반 일지 ⑧)","options":[{"t":"계획하기 → 해 보기 → 나누기","correct":true},{"t":"나누기 → 해 보기 → 계획하기","mis":"SC5-2-u2-X32"},{"t":"해 보기 → 계획하기 → 나누기","mis":"SC5-2-u2-X32"},{"t":"해 보기만 하면 된다","mis":"SC5-2-u2-X32"}],"explanation":["먼저 계획해요.","만들어요.","나눠요."],"asset":{"type":"passage","lines":["일요일, 일주일 기록으로 모둠 날씨 앱 「하늘반 날씨」 화면을 만들었다.","기온은 큰 숫자, 비 올 확률은 그래프, 옷차림 알림을 넣었다.","기상 위성·부표·레윈존데가 잰 자료가 예보가 된다는 것도 적었다."],"title":"⑧ 일요일 — 날씨 앱과 관측 장비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#16','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C20',2,'mc','auto','관측 자료를 빠르게 분석하는 데 쓰는 장비는 어느 것인가요?',ARRAY['SC5-2-u2-X33']::text[],false,'{"seq":16,"concept":"SC5-2-u2-C20","difficulty":2,"kind":"mc","stem":"관측 자료를 빠르게 분석하는 데 쓰는 장비는 어느 것인가요?","options":[{"t":"슈퍼컴퓨터","correct":true},{"t":"측우기","mis":"SC5-2-u2-X33"},{"t":"부표","mis":"SC5-2-u2-X33"},{"t":"바람자루","mis":"SC5-2-u2-X33"}],"explanation":["자료가 아주 많아요.","빠르게 분석해요.","슈퍼컴퓨터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#17','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C4',3,'ox','auto','두 지역의 날씨를 견줄 때 「맑음」 「흐림」만 쓰는 것보다 기상 요소로 나타내는 것이 좋아요.',ARRAY['SC5-2-u2-X08']::text[],false,'{"seq":17,"concept":"SC5-2-u2-C4","difficulty":3,"kind":"ox","stem":"두 지역의 날씨를 견줄 때 「맑음」 「흐림」만 쓰는 것보다 기상 요소로 나타내는 것이 좋아요.","answer":"O","reason_options":[{"t":"기상 요소로 나타내면 차이를 구체적이고 객관적으로 알 수 있기 때문에","correct":true},{"t":"맑음과 흐림만 알면 모두 알 수 있기 때문에","mis":"SC5-2-u2-X08"}],"mis":"SC5-2-u2-X08","explanation":["기상 요소는 구체적이에요.","차이가 보여요.","견주기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#18','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C8',3,'error','auto','캔 실험을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X13','SC5-2-u2-X19','SC5-2-u2-X14']::text[],false,'{"seq":18,"concept":"SC5-2-u2-C8","difficulty":3,"kind":"error","stem":"캔 실험을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「캔에 작은 구멍이 있어서 음료가 새어 나온 거야.」","correct":true,"mis_target":"SC5-2-u2-X13"},{"t":"서아 — 「캔 주변 공기의 수증기가 응결했어.」","mis":"SC5-2-u2-X19"},{"t":"민서 — 「풀잎 이슬과 같은 과정이야.」","mis":"SC5-2-u2-X14"}],"explanation":["캔은 새지 않아요.","주변 수증기예요.","하준의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["목요일 오후, 차가운 캔 겉면을 닦고 두었더니 물방울이 맺혔다.","집기병에 얼음 지퍼 백을 얹었더니 안이 뿌옇게 흐려졌다.","두 실험을 새벽에 본 것과 견주어 실험관찰에 적었다."],"title":"⑤ 목요일 오후 — 두 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#19','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C13',3,'mc','auto','어느 날 습도 92 %, 구름의 양 10, 강수량 15 mm였어요. 이날 받은 영향과 알맞은 대비를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u2-X24','SC5-2-u2-X06']::text[],false,'{"seq":19,"concept":"SC5-2-u2-C13","difficulty":3,"kind":"mc","stem":"어느 날 습도 92 %, 구름의 양 10, 강수량 15 mm였어요. 이날 받은 영향과 알맞은 대비를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"저기압 — 우산을 챙기고 실내 활동을 한다","correct":true},{"t":"고기압 — 빨래를 밖에 넌다","mis":"SC5-2-u2-X24"},{"t":"고기압 — 선크림만 챙긴다","mis":"SC5-2-u2-X24"},{"t":"알 수 없다 — 기온이 없어서","mis":"SC5-2-u2-X06"}],"explanation":["습도가 높아요.","비가 왔어요.","저기압이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#20','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C15',3,'mc','auto','바람 발생 모형실험 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u2-X26','SC5-2-u2-X29','SC5-2-u2-X25']::text[],false,'{"seq":20,"concept":"SC5-2-u2-C15","difficulty":3,"kind":"mc","stem":"바람 발생 모형실험 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"바람은 온도가 낮은 고기압 쪽에서 온도가 높은 저기압 쪽으로 분다","correct":true},{"t":"바람은 따뜻한 쪽에서 차가운 쪽으로 분다","mis":"SC5-2-u2-X26"},{"t":"바람은 온도와 상관없이 분다","mis":"SC5-2-u2-X29"},{"t":"따뜻한 쪽이 고기압이다","mis":"SC5-2-u2-X25"}],"explanation":["모래 쪽이 차가워요.","고기압이에요.","고 → 저로 불어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#21','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C6',3,'error','auto','하늘반 일지 ③을 읽고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u2-X10','SC5-2-u2-X11','SC5-2-u2-X09']::text[],false,'{"seq":21,"concept":"SC5-2-u2-C6","difficulty":3,"kind":"error","stem":"하늘반 일지 ③을 읽고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「예보를 봤으니 이제 바람이 약해질 거야.」","correct":true,"mis_target":"SC5-2-u2-X10"},{"t":"하은 — 「예보 덕분에 창문을 미리 닫았어.」","mis":"SC5-2-u2-X11"},{"t":"준서 — 「화분을 들여놓으면 피해를 막을 수 있어.」","mis":"SC5-2-u2-X09"}],"explanation":["예보는 날씨를 못 바꿔요.","대비하게 해 줘요.","시우의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["수요일 아침, 강한 바람과 비 예보가 나왔다.","교실 창문을 닫고 운동장 체육을 강당 수업으로 바꾸었다.","집에 가서 베란다 화분을 들여놓기로 했다.","하은이는 「예보를 미리 봐서 다행이야」라고 말했다."],"title":"③ 수요일 — 예보와 대처"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#22','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C21',3,'ox','auto','날씨를 기상 요소로 나타내고 기압과 바람을 알면 생활 계획을 더 잘 세울 수 있어요.',ARRAY['SC5-2-u2-X01']::text[],false,'{"seq":22,"concept":"SC5-2-u2-C21","difficulty":3,"kind":"ox","stem":"날씨를 기상 요소로 나타내고 기압과 바람을 알면 생활 계획을 더 잘 세울 수 있어요.","answer":"O","reason_options":[{"t":"날씨를 예상해 알맞게 대비할 수 있기 때문에","correct":true},{"t":"날씨는 생활과 상관없기 때문에","mis":"SC5-2-u2-X01"}],"mis":"SC5-2-u2-X01","explanation":["기상 요소를 읽어요.","기압과 바람을 알아요.","계획을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#23','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C10',4,'essay','teacher','「구름은 하늘에 있고 이슬은 땅에 있으니 둘은 전혀 다른 것」이라는 친구의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u2-C10","difficulty":4,"kind":"essay","stem":"「구름은 하늘에 있고 이슬은 땅에 있으니 둘은 전혀 다른 것」이라는 친구의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 구름과 이슬은 생기는 자리가 다를 뿐, 둘 다 공기 중의 수증기가 응결해 생긴다는 공통점이 있다. 이슬은 차가워진 물체 표면에 맺히고 구름은 지표면으로부터 높은 곳에 떠 있다.","scoring_points":["공통점을 들어 고쳤는가","자리 차이를 바르게 썼는가","친구의 말에서 틀린 점을 짚었는가"]},"explanation":["공통점이 있어요.","자리만 달라요.","바르게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#24','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C16',4,'essay','teacher','맑은 날 바닷가에서 오후에 연을 날리고 밤에 모닥불을 피울 때 연과 연기가 갈 쪽을 예상하고 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u2-C16","difficulty":4,"kind":"essay","stem":"맑은 날 바닷가에서 오후에 연을 날리고 밤에 모닥불을 피울 때 연과 연기가 갈 쪽을 예상하고 까닭을 쓰세요.","answer_guide":{"answer":"예: 오후에는 육지가 더 따뜻해 저기압이 되어 바다에서 육지로 해풍이 불므로 연은 육지 쪽으로 날아간다. 밤에는 육지가 빨리 식어 고기압이 되어 육지에서 바다로 육풍이 불므로 모닥불 연기는 바다 쪽으로 흘러간다.","scoring_points":["연의 방향과 해풍을 썼는가","연기의 방향과 육풍을 썼는가","기압 차이로 까닭을 설명했는가"]},"explanation":["오후엔 해풍이에요.","밤엔 육풍이에요.","기압으로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u2_review_d#25','sci',5,2,'u2','','g5_2_sci_u2_review_d','unit_review','SC5-2-u2-C21',4,'essay','teacher','하늘반 일주일 일지 가운데 두 날을 골라, 그날 배운 개념(기상 요소·이슬과 안개·기압·바람 가운데)을 이어 우리 생활에 어떻게 쓸 수 있는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u2-C21","difficulty":4,"kind":"essay","stem":"하늘반 일주일 일지 가운데 두 날을 골라, 그날 배운 개념(기상 요소·이슬과 안개·기압·바람 가운데)을 이어 우리 생활에 어떻게 쓸 수 있는지 쓰세요.","answer_guide":{"answer":"예: 목요일 새벽에는 기온이 낮아 수증기가 응결해 안개가 끼었으니, 안개 낀 날 아침에는 앞이 잘 보이지 않아 천천히 조심해서 다녀야 한다. 토요일 바닷가에서는 낮에 해풍, 밤에 육풍이 부니 모닥불은 연기가 바다 쪽으로 가는 밤에 바람을 살피며 피우면 좋다.","scoring_points":["두 날과 개념을 바르게 이었는가","개념을 정확하게 설명했는가","생활에 쓰는 방법을 구체적으로 썼는가"]},"explanation":["두 날을 골라요.","개념을 이어요.","생활에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
